$script:MeshRoot             = Join-Path $script:AppDataRoot 'meshes'
$script:BlenderFolder        = Join-Path $script:AppDataRoot 'blender'
$script:BlenderStatusFile    = Join-Path $script:AppDataRoot 'blender-status.json'
