        bridge_status = 'Bridge-Statusprüfung'
        raycast = 'Strahlmessung'
        raycast_many = 'Mehrfach-Strahlmessung'
        ground_height = 'Bodenhöhenmessung'
        measure = 'Abstandsmessung'
        measure_height = 'Höhenmessung'
