tools.wait = function(args)
    local seconds = tonumber(args.seconds) or 1
    if seconds > 60 then seconds = 60 end
    local startSeq = outputSeq
    task.wait(seconds)
    return ok({ waited = seconds, output = readOutput({ since = startSeq, limit = 200 }).lines })
end

