        # ---------------- PLAY / TEST ----------------
                                        $t.Add(@{ name = 'report_done'; category = 'session'; summary = 'Eine kurze, lebendige Windows-11-Mitteilung senden.';
            description = 'Als letzten Call verwenden, wenn die Arbeit fertig ist. Arena schreibt SELBST einen aussagekraeftigen Titel und einen natuerlichen, einladenden Inhalt – keine trockene Liste. Verlaessliches Windows-11-Anzeigebudget: Titel maximal 70 Zeichen, Inhalt maximal 140 Zeichen. Microsoft definiert fuer ToastGeneric keine feste Zeichenobergrenze pro Feld; die sichtbare Menge haengt von Breite, Skalierung und Layout ab. Deshalb erzwingt die Bridge diese konservativen Vollanzeige-Grenzen. Gute Form: Titel="✅ Arena hat den Lauf-Bug behoben!", message="Der Lauf-Bug ist weg – komm ins Spiel und probiere es aus!".';
            params = @{ title = @{ type = 'string'; required = $true; default = '-'; description = 'Von Arena formulierter lebendiger Titel, maximal 70 Zeichen.' }; message = @{ type = 'string'; required = $true; default = '-'; description = 'Ein natuerlicher, einladender Satz, maximal 140 Zeichen; keine Auflistung.' } };
            returns = '{ delivered, title, message, limits: { titleCharacters=70, messageCharacters=140 } }';
            example = @{ title = '✅ Arena hat den Lauf-Bug behoben!'; message = 'Der Lauf-Bug ist weg – komm ins Spiel und probiere es aus!' };
            errors = @('UNACKED_USER_MESSAGE: mindestens eine Nutzernachricht ist noch unbeantwortet/unbestaetigt - erst anwenden, beantworten und mit ack_user_message bestaetigen, dann erneut report_done.', 'NOTIFICATIONS_DISABLED', 'DRAFT_GRADE_RISK: model_audit hat die Arbeit als Entwurf benotet (wenige Teile, keine Polygon-/Mesh-/Union-/Detail-Geometrie) - nachbauen oder die Einfachheit mit grade erklaeren.', 'BAD_ARGS: title/message fehlen oder ueberschreiten 70/140 Zeichen.');
            notes = @('Version 7.2.0: Die Antwort enthaelt notification { flowId, platformVerdict, platformReason, verified }. Steht dort NOTIFICATION_UNVERIFIED, hat Windows die Meldung vermutlich unterdrueckt (Grund im Feld platformReason) - behaupte dann NICHT, der Nutzer sei benachrichtigt, sondern sage im Antworttext, was fertig ist und dass die Windows-Meldung moeglicherweise nicht erscheint.', 'Version 7.2.0: Die Antwort enthaelt buildRegister { models, audited, unaudited, drafts, declared, averageFinishScore } und buildRegisterNote: was wurde gebaut, was davon ist mit model_audit gemessen, was ist noch Entwurf. Steht dort ein ungeprueftes Modell, hat model_audit diese Geometrie nie gemessen - hole das nach oder sage ehrlich, was ungeprueft ist.') })
                        $t.Add(@{ name = 'set_context'; category = 'session'; summary = 'Seite wechseln: server oder client.';
            description = 'Bestimmt, welche Seite Laufzeit-Werkzeuge (run_lua) treffen. run_lua selbst laeuft IMMER nur auf der Server/Seite - fuer den Client die client_-Werkzeuge.';
            params = @{ context = @{ type = "'server'|'client'"; required = $true; default = '-'; description = '' } };
            returns = '{ context, note }';
            example = @{ context = 'client' };
            errors = @('BAD_ARGS: context muss server oder client sein.') })
                                        $t.Add(@{ name = 'wait'; category = 'session'; summary = 'Im Place warten + Output mitlesen.';
            params = @{ seconds = @{ type = 'number'; required = $false; default = '1'; description = 'max 60.' } };
            returns = '{ waited, output: [...] }';
            example = @{ seconds = 2 };
            errors = @() })

        # ---------------- GUI / CLIENT ----------------
                                                        

        # ---------------- SIMULATION (sim_start bewusst gesperrt) ----------------
        $t.Add(@{ name = 'sim_start'; category = 'sim'; summary = 'Deaktiviert: keine unterstuetzte Physik-/Skript-Simulation im echten Edit-Modus.';
            description = 'Dieser Aufruf ist dauerhaft gesperrt, solange die dokumentierte Roblox-Studio-API keinen unterstuetzten Weg fuer Physik/Skripte bei EditModeActive=true bietet. Die fruehere Implementierung nutzte StudioTestService:ExecuteRunModeAsync (offizieller Studio Run) und verliess den Edit-Modus. Nicht erneut versuchen; compile_check und run_lua bleiben verfuegbar, Live-Verhalten muss der Nutzer in Studio pruefen.';
            params = @{};
            returns = '{ ok=false, code="SIM_DISABLED", reason="EDIT_MODE_SIMULATION_UNAVAILABLE" }';
            example = @{};
            errors = @('SIM_DISABLED: sim_start ist bis zu einer unterstuetzten echten Edit-Modus-Simulation deaktiviert.') })
        $t.Add(@{ name = 'sim_stop'; category = 'sim'; summary = 'Nur eine bestaetigt bridge-eigene Studio-Run-Session stoppen.';
            description = 'Stoppt ausschliesslich eine bereits laufende, der Bridge gehoerende Session mit RunService:Stop() und wartet auf EditModeActive=true (12s). Der Start neuer Studio-Run-Simulationen ist deaktiviert; ein vom Nutzer gestarteter Test wird nicht fernbeendet. Fallback: Shift+F5; nicht in einer Schleife wiederholen.';
            params = @{};
            returns = '{ ok, state { running=false, editModeActive=true, stoppedByBridge } }';
            example = @{};
            errors = @('SIM_NOT_BRIDGE_OWNED: aktive Session ist nicht als bridge-eigen bestaetigt.', 'SIM_STOP_NEEDS_USER: Nutzer muss selbst stoppen.') })
        $t.Add(@{ name = 'sim_status'; category = 'sim'; summary = 'Studio-Teststatus lesen; sim_start ist deaktiviert (read-only).';
            description = 'Liest EditModeActive, RunService-Modus (Studio Run vs Play/F5, sonst unknown), startedByBridge/simStartedAt und die verfuegbare Player-Zahl. simAllowed ist immer false: Die fruehere Studio-Run-Implementierung verliess den Edit-Modus (EditModeActive=false); die dokumentierte API bietet keinen unterstuetzten true Edit-Modus-Pfad fuer Physik/Skripte.';
            params = @{};
            returns = '{ running, mode, editModeActive, runServiceRunning, startedByBridge, simStartedAt, simAllowed=false, playerCount, note }';
            example = @{};
            errors = @() })

        # ---------------- MESH / BLENDER (Version 7.4.0) ----------------
        $t.Add(@{ name = 'blender_status'; category = 'mesh'; summary = 'Ist Blender bereit? Zustand, Version, Pfad, Probe.';
            description = 'Liest den Schritt-4-Zustand der Bridge: Blender wird gesucht (vorhandene Installationen zuerst), die Version gemessen und eine ECHTE Faehigkeitsprobe gefahren (Blender baut im Hintergrund wirklich ein OBJ - und seit 7.5.0 zusaetzlich die Upload-Datei FBX/GLB fuer Roblox Open Cloud; das steht danach in uploadExport). Nur wenn die Probe bestanden ist, wird state ready und der Mesh-Bau frei. Mit action="check" wird die ganze Pruefung erneut angestossen (Hintergrund, sofortige Antwort - danach kurz erneut lesen). Solange state nicht ready ist, ist der Mesh-Bau deaktiviert - build_mesh_model antwortet dann BLENDER_NOT_READY. Der Polygon-Weg (build_polygon_model) funktioniert unabhaengig davon.';
            params = @{ action = @{ type = 'string'; required = $false; default = '-'; description = 'Leer oder "check" (Suche + Version + echte Faehigkeitsprobe erneut starten).' } };
            returns = '{ ok, result { started, blender { state, ready, version, path, source, percent, message, detail, probe, enabled, meshFolder, installLog, uploadExport, uploadExportDetail, uploadHint? }, note } }';
            example = @{};
            errors = @() })
        $t.Add(@{ name = 'build_mesh_model'; category = 'mesh'; summary = 'STANDARDWEG fuer 3D-Modelle (7.5.5): Blender baut im Hintergrund ein OBJ (ein Slot = ein MeshPart).';
            description = 'STANDARDWEG (Version 7.5.5, Blender-first): JEDES 3D-Modell, das Arena baut, geht zuerst hierueber - glatte, organische, detailreiche oder hochteilige Formen ebenso wie Gebaeude, Fahrzeuge und Requisiten. Blender baut sie im HINTERGRUND - dieser Aufruf antwortet sofort mit jobId, also NIEMALS synchron warten. Je Slot liefert der Aufruf ein Blender-Python-Skript (nur Geometrie: bpy, bmesh, math, mathutils, random; Datei-/Netzwerk-/Prozesszugriff, bpy.ops.wm.* und Exportfunktionen werden vor dem Start abgelehnt). 1 Blender-Einheit = 1 Stud; im Skript ist Z DIE HOEHE (Blender-Konvention - Z nach oben bauen, der Export dreht das Modell auf Roblox-Y; NIEMALS in Blender-Y hochbauen, genau das hat in 7.5.0 den liegenden Baum erzeugt). Die bbox-Mitte am Ursprung setzt der Runner der Bridge automatisch, Modifier werden beim Export angewandt. WICHTIG: EIN zusammenhaengendes Modell = EIN Slot (ein Baum ist EIN Mesh); mehrere Slots NUR fuer Animation, eigene Farbe/Material je Teil oder wenn EIN Mesh das Dreiecks-Budget sprengt - siehe meshBuildRules.ONE_MODEL_ONE_MESH. Danach MISST die Bridge das Ergebnis (Dreiecke, Groesse in Studs), legt die viereckigen MeshPart-Platzhalter selbst in den Place UND erzeugt je Slot eine Upload-Datei (FBX, sonst GLB). Danach gehoert der Upload DIR: upload_asset { slotKey } schickt genau diese Datei ueber die Roblox-Open-Cloud-API nach Roblox und nennt die echte Asset-Id; mesh_apply_asset setzt die Geometrie in die Platzhalter. Der Nutzer laedt NICHTS mehr von Hand hoch - er braucht nur einmal seinen Open-Cloud-Schluessel in den Einstellungen (die Antwort OPENCLOUD_KEY_MISSING nennt dir den Satz fuer ihn). Fortschritt und Zahlen mit mesh_status lesen (kurz pollen, nicht in einer engen Schleife). Siehe meshBuildRules und cloudUploadRules in den Guides.';
            params = @{ modelName = @{ type = 'string'; required = $true; default = '-'; description = 'Name des Modells (auch fuer die Platzhalter-Namen).' }; slots = @{ type = 'array'; required = $true; default = '-'; description = 'Array von { name, script, offset {x,y,z}, targetTriangles, color, material, canCollide } - ein Eintrag je MeshPart (max. 12). EIN zusammenhaengendes Modell gehoert in EINEN Slot (siehe meshBuildRules.ONE_MODEL_ONE_MESH); mehrere Slots nur fuer Animation, eigene Farbe/Material oder gesprengtes Dreiecks-Budget.' }; parentRef = @{ type = 'string'; required = $false; default = 'game.Workspace'; description = 'Wohin die Platzhalter kommen.' }; origin = @{ type = 'table'; required = $false; default = '{x=0,y=0,z=0}'; description = 'Weltposition des Modell-Ursprungs; Slot-Offsets kommen darauf.' }; rotationY = @{ type = 'number'; required = $false; default = '0'; description = 'Drehung um Y in Grad.' }; anchored = @{ type = 'boolean'; required = $false; default = 'true'; description = 'Anchored der Platzhalter.' }; timeoutSeconds = @{ type = 'number'; required = $false; default = '300'; description = 'Zeitlimit je Slot (max. 900).' } };
            returns = '{ ok, result { jobId, state="queued", slotCount, blender, meshFolder, note, files } }';
            example = @{ modelName = 'Turret'; origin = @{ x = 12; y = 4; z = -18 }; slots = @( @{ name = 'base'; script = 'bpy.ops.mesh.primitive_cylinder_add(vertices=24, radius=1.4, depth=0.6)'; color = '#8A8F99' } ) };
            errors = @('BLENDER_NOT_READY: Blender fehlt/installiert noch - nichts wurde gebaut.', 'SCRIPT_REJECTED: mindestens ein Skript ist gesperrt (problems nennt den Grund).', 'BUDGET_EXCEEDED: mehr als 12 Slots.', 'BAD_ARGS: slots fehlt oder ist leer.') })
        $t.Add(@{ name = 'mesh_status'; category = 'mesh'; summary = 'Zustand der Mesh-Jobs, gemessene Dreiecke/Groesse, Platzhalter, Ids.';
            description = 'Liest alle Mesh-Jobs dieser Sitzung aus dem Register der Bridge: Zustand, Ordner, je Slot die GEMESSENEN Dreiecke und die Groesse in Studs, die Platzhalter, die eingetragene Asset-Id und die zurueckgelesene MeshId. readyForUpload nennt genau die Dateien, die der Nutzer noch hochladen muss. Mit action="placeholders" werden die Platzhalter neu angefordert (z.B. nachdem sie im Studio geloescht wurden).';
            params = @{ jobId = @{ type = 'string'; required = $false; default = '-'; description = 'Nur diesen Job lesen.' }; action = @{ type = 'string'; required = $false; default = '-'; description = 'Leer oder "placeholders" (Platzhalter neu anfordern).' } };
            returns = '{ ok, result { blender, jobs [ { jobId, modelName, state, folder, placeholdersCreated, placeholderState, slots [ { key, name, state, triangles, size, fileName, objPath, assetId, meshIdReadBack, placeholderPath, error } ] } ], readyForUpload, appliedCount, failedCount, summary, note } }';
            example = @{};
            errors = @() })
        $t.Add(@{ name = 'mesh_cancel'; category = 'mesh'; summary = 'Laufenden Blender-Job abbrechen.';
            description = 'Beendet den laufenden Blender-Job (ohne jobId den neuesten dieser Sitzung). Eine halbfertige OBJ-Datei wird verworfen; bereits gemessene Slots bleiben unveraendert. Nicht in einer Schleife aufrufen.';
            params = @{ jobId = @{ type = 'string'; required = $false; default = '-'; description = 'Job aus build_mesh_model/mesh_status.' } };
            returns = '{ ok, result { jobId, cancelled, note } }';
            example = @{ jobId = 'mesh_1a2b3c4d5e' };
            errors = @('NO_JOB: es laeuft kein Job.') })
        $t.Add(@{ name = 'mesh_apply_asset'; category = 'mesh'; summary = 'Hochgeladene Mesh-Ids in die vorhandenen Platzhalter setzen.';
            description = 'Setzt die Geometrie in die BESTEHENDEN MeshPart-Platzhalter (Slot-keys aus mesh_status). Groesse, Position, Welds, Attribute und Animationen bleiben erhalten. MeshPart.MeshId ist schreibgeschuetzt - die Bridge benutzt deshalb InsertService:CreateMeshPartAsync + MeshPart:ApplyMesh ueber das Plugin. Die Asset-Id kommt normalerweise aus upload_asset: Roblox Open Cloud legt ein hochgeladenes FBX/GLB als MODELL an; die Bridge laedt es, nimmt die MeshId aus dem MeshPart darin und setzt sie ein (applyPath = modelMeshId). Eine direkt hochgeladene Mesh-Id funktioniert genauso (applyPath = meshId). Nach dem Einsetzen meldet die Antwort je Slot die zurueckgelesene MeshId - erst dann ist der Slot wirklich fertig.';
            params = @{ slots = @{ type = 'array'; required = $true; default = '-'; description = 'Array von { key, assetId } - keys aus mesh_status, assetId ist die Zahl aus Roblox (rbxassetid:// optional).' } };
            returns = '{ ok, result { applied [ { key, state, assetId, meshIdReadBack, path, error } ], pluginResult, note } }';
            example = @{ slots = @( @{ key = 'mesh_1a2b3c4d5e:base'; assetId = 1234567890 } ) };
            errors = @('BAD_ARGS: slots fehlt oder enthaelt keine gueltige key/assetId.', 'STUDIO_UNREACHABLE_OR_TIMEOUT: Studio hat nicht geantwortet - nichts wurde eingesetzt.') })
        $t.Add(@{ name = 'mesh_slots'; category = 'mesh'; summary = 'Viereckige MeshPart-Platzhalter anlegen (interner Baustein des Mesh-Wegs).';
            description = 'Legt die viereckigen MeshPart-Platzhalter mit den GEMESSENEN Maßen an und markiert sie mit ArenaMeshSlot/ArenaMeshState/ArenaPlaceholder. Normalerweise macht das die Bridge nach dem Blender-Bau selbst - dieser Aufruf ist fuer Sonderfaelle (z.B. Platzhalter an anderer Stelle neu anlegen). Die Groesse muss von mesh_status kommen; sie darf nicht geschaetzt werden.';
            params = @{ slots = @{ type = 'array'; required = $true; default = '-'; description = 'Array von { key, name, size {x,y,z}, position {x,y,z}, rotationY, color, material, canCollide, fileName } (max. 40).' }; parentRef = @{ type = 'string'; required = $false; default = 'game.Workspace'; description = 'Elternobjekt.' }; modelName = @{ type = 'string'; required = $false; default = 'ArenaMesh'; description = 'Namensbestandteil.' }; buildId = @{ type = 'string'; required = $false; default = '-'; description = 'Job-Id aus mesh_status.' } };
            returns = '{ ok, created, failed, createdCount, failedCount, note }';
            example = @{ slots = @( @{ key = 'mesh_1a2b3c4d5e:base'; name = 'base'; size = @{ x = 2.8; y = 0.6; z = 2.8 } } ) };
            errors = @('BAD_ARGS: slots fehlt.', 'BUDGET_EXCEEDED: mehr als 40 Platzhalter.') })
        $t.Add(@{ name = 'mesh_apply'; category = 'mesh'; summary = 'Interner Befehl der Bridge: Geometrie einsetzen (nicht direkt aufrufen).';
            description = 'Wird von der Bridge (mesh_apply_asset) an das Plugin geschickt. Der Aufruf setzt je Slot { key, assetId } die Geometrie in den bestehenden MeshPart mit dem Attribut ArenaMeshSlot. Nicht direkt benutzen - die Dokumentation steht bei mesh_apply_asset.';
            params = @{ slots = @{ type = 'array'; required = $true; default = '-'; description = 'Array von { key, assetId }.' } };
            returns = '{ ok, applied, failed, appliedCount, failedCount, note }';
            example = @{ slots = @( @{ key = 'mesh_1a2b3c4d5e:base'; assetId = '1234567890' } ) };
            errors = @('BAD_ARGS: slots fehlt.') })
        $t.Add(@{ name = 'mesh_drop'; category = 'mesh'; summary = 'Interner Befehl der Bridge: Mesh-Slot stornieren (nicht direkt aufrufen).';
            description = 'Aufaeum-Werkzeug fuer Mesh-Slots: loescht jedes MeshPart mit dem Attribut ArenaMeshSlot = key aus dem Place - den Platzhalter UND ein schon eingesetztes Mesh. Seit 7.5.0 gibt es dafuer kein Fenster mehr (das Mesh-Fenster ist entfernt) - der Aufruf ist ein ganz normales Werkzeug. Ehrlich: ein eingesetztes Mesh wird NICHT wiederhergestellt (es kommt kein Platzhalter zurueck). Nuetzlich, wenn du einen Slot endgueltig verwirfst oder einen Fehlbau wegraeumen willst. Wie jeder schreibende Befehl ist er im laufenden Playtest (Testmodus) blockiert.';
            params = @{ slots = @{ type = 'array'; required = $true; default = '-'; description = 'Array von { key } (keys aus mesh_status).' } };
            returns = '{ ok, dropped, failed, droppedCount, failedCount, note }';
            example = @{ slots = @( @{ key = 'mesh_1a2b3c4d5e:base' } ) };
            errors = @('BAD_ARGS: slots fehlt.', 'SIM_RUNNING/USER_PLAYTEST_ACTIVE: im laufenden Playtest sind schreibende Befehle gesperrt.') })

        # ---------------- ROBLOX OPEN CLOUD (Version 7.5.2) ----------------
        $t.Add(@{ name = 'upload_asset'; category = 'cloud'; summary = 'Asset-Datei (Modell, Bild, Audio, Animation, Video) per Roblox Open Cloud hochladen.';
            description = 'Laedt eine Datei ueber die OFFIZIELLE Roblox-Open-Cloud-Assets-API in das Roblox-Konto des Nutzers hoch und antwortet mit der ASSET-ID, die Roblox selbst genannt hat. Danach setzt DU das Asset selbst in den Place ein: ein Mesh mit mesh_apply_asset in den bestehenden Platzhalter (oder insert_asset fuer das komplette Modell), ein Bild mit set_property auf Decal.Texture / Texture.Texture / ImageLabel.Image / MeshPart.TextureID. Der Nutzer muss NICHTS mehr von Hand hochladen - das Mesh-Fenster gibt es nicht mehr. QUELLE (genau eine): slotKey = ein Mesh-Slot aus mesh_status (die Bridge kennt die fertige FBX/GLB-Datei dazu), filePath = eine Datei im Ordner der Bridge, oder contentBase64 + fileName = ein Bild, das DU erzeugt hast (kein Dateipfad noetig). Optional assetType: Model, Decal, Image, Audio, Animation (RBXM/RBXMX) oder Video. Formate: FBX/GLB/GLTF/RBXM/RBXMX, PNG/JPG/JPEG/BMP/TGA, MP3/OGG/WAV/FLAC, MP4/MOV. Bridge-Limit: 20 MiB je Datei. Roblox prueft zusaetzlich Konto, Moderation, Dauer, Aufloesung und Kontingente. Bild/Audio/Video-Inhalte koennen nicht per Update ersetzt werden; Metadaten schon. Fuer vorhandene Mesh-Binaerdaten und alle weiteren Asset-Funktionen open_cloud nutzen. Braucht der Upload laenger, antwortet das Werkzeug mit state=pending und einer operationId - dann einfach upload_asset { operationId } erneut aufrufen (nicht in einer engen Schleife pollen). Fehlt der Schluessel, antwortet das Werkzeug OPENCLOUD_KEY_MISSING mit einem userMessage-Satz: sage ihn dem Nutzer WORTLICH auf Deutsch. Der Asset-Ersteller ist standardmaessig das Roblox-Konto, das gerade in Studio angemeldet ist: Das Plugin meldet dafuer StudioService:GetUserId() als editorUserId. Nur wenn keine gueltige Studio-ID vorliegt, nutzt die Bridge automatisch die Resource aus dem API-Key (Introspect). Der Key muss ASSETS write fuer das angemeldete Studio-Konto erlauben; es gibt kein manuelles Entwickler-Feld. Bei JEDEM gescheiterten Upload steht der EXAKTE Dateipfad in der Antwort (filePath/filePathHint): nenne ihn dem Nutzer woertlich in einer eigenen Zeile, damit er die Datei notfalls selbst in Roblox hochladen kann (Toolbox -> Import).';
            params = @{
                slotKey = @{ type = 'string'; required = $false; default = '-'; description = 'Mesh-Slot aus mesh_status (z. B. mesh_1a2b3c4d5e:base). Die Bridge sucht die passende FBX/GLB-Datei selbst und traegt die Asset-Id danach in den Slot ein.' }
                filePath = @{ type = 'string'; required = $false; default = '-'; description = 'Absoluter Pfad oder Pfad relativ zum Mesh-Ordner der Bridge. Nur Dateien aus dem Bridge-Ordner werden hochgeladen (Sicherheit) - eigene Bilder stattdessen als contentBase64 schicken.' }
                contentBase64 = @{ type = 'string'; required = $false; default = '-'; description = 'Dateiinhalt direkt als Base64 (zusammen mit fileName). So kannst du ein selbst erzeugtes Bild ohne Datei auf der Festplatte hochladen.' }
                fileName = @{ type = 'string'; required = $false; default = '-'; description = 'Dateiname MIT Endung, wenn contentBase64 genutzt wird (oder um den Anzeigenamen zu bestimmen).' }
                assetType = @{ type = 'string'; required = $false; default = 'aus der Endung'; description = 'Model, Decal, Image, Audio, Animation oder Video. Animation bei RBXM/RBXMX ausdrücklich setzen. Leer = passend zur Endung.' }
                displayName = @{ type = 'string'; required = $false; default = 'Dateiname'; description = 'Anzeigename des Assets in Roblox.' }
                description = @{ type = 'string'; required = $false; default = 'Arena Roblox Bridge'; description = 'Beschreibung des Assets in Roblox.' }
                operationId = @{ type = 'string'; required = $false; default = '-'; description = 'Nur angeben, um einen schon laufenden Upload weiterzuverfolgen (aus einer frueheren pending-Antwort).' }
                forceNew = @{ type = 'boolean'; required = $false; default = 'false'; description = 'Slot wurde schon hochgeladen und soll trotzdem ein NEUES Asset bekommen (sonst kommt die alte Asset-Id zurueck).' }
                waitSeconds = @{ type = 'number'; required = $false; default = '20'; description = 'Wie lange die Bridge auf die Fertigmeldung von Roblox wartet (max. 45).' }
            };
            returns = '{ ok, result { state="uploaded", assetId, rbxassetId, assetType, fileName, bytes, operationId, slotKey, filePath, filePathHint, howToUse, note } } bzw. { ok=false, code, error, status?, robloxResponse?, userMessage?, howToFix?, filePath?, filePathHint? } bzw. { ok=true, result { state="pending", operationId, nextCall, filePath, filePathHint } }';
            example = @{ slotKey = 'mesh_1a2b3c4d5e:base'; displayName = 'Turm Sockel' };
            errors = @(
                'OPENCLOUD_KEY_MISSING: kein API-Schluessel hinterlegt - userMessage WORTLICH an den Nutzer (Einstellungen -> ROBLOX OPEN CLOUD -> Tutorial).',
                'OPENCLOUD_CREATOR_MISSING: Studio hat keine angemeldete Nutzer-ID gemeldet und Introspect hat keine passende Key-Resource geliefert - melde dich in Studio an oder pruefe den Key-Empfaenger; userMessage WORTLICH an den Nutzer.',
                'Bei jedem Fehler nennt die Antwort filePath/filePathHint - diesen Pfad dem Nutzer IMMER woertlich sagen, damit er die Datei selbst hochladen kann.',
                'OPENCLOUD_KEY_REJECTED: Roblox hat den Schluessel abgelehnt (401/403) - ungueltig, abgelaufen oder ohne die Rechte Assets + Lesen + Schreiben.',
                'OPENCLOUD_RATE_LIMITED: Roblox drosselt (429) - spaeter erneut versuchen, dem Nutzer ehrlich sagen.',
                'OPENCLOUD_UPLOAD_REJECTED: Roblox hat die Datei abgelehnt (anderer 4xx) - robloxResponse nennt den Grund.',
                'OPENCLOUD_SERVER_ERROR: Roblox stoert (5xx).',
                'OPENCLOUD_UNREACHABLE: keine Antwort / Netzwerkfehler.',
                'OPENCLOUD_OPERATION_FAILED: Roblox hat die Datei nach dem Upload abgelehnt (Moderation/Format) - robloxResponse nennt den Grund.',
                'NO_UPLOAD_FILE: zum Slot liegt keine FBX/GLB bereit (Slot neu bauen).',
                'UNSUPPORTED_FORMAT: Endung nicht erlaubt - OBJ kann Roblox Open Cloud NICHT hochladen.',
                'FILE_TOO_LARGE: ueber 20 MB.',
                'PATH_OUTSIDE_BRIDGE: filePath liegt ausserhalb des Bridge-Ordners.',
                'BAD_ARGS: keine Quelle angegeben oder contentBase64 ohne fileName.'
            ) })


        $t.Add(@{ name = 'open_cloud'; category = 'cloud'; summary = 'Alle ausdrücklich freigegebenen Roblox-Cloud-Funktionen ohne Herausgabe des API-Keys.';
            description = 'Zuerst list (optional scope), dann describe mit operation-ID, danach call. Der feste geprüfte Katalog enthält Assets, Veröffentlichung, DataStores, Analytics, Events, Inventar, Creator Store, Asset-Freigaben und erlaubte Legacy-Verwaltung. describe liefert den offiziellen Pfad, Parameter, vollständige Request-Schemas und Quellen. Kein frei wählbarer URL-/Methoden-/Auth-Proxy. Gesperrte Rechte und Funktionen sind ausgeschlossen. Ziel-IDs müssen aus dem Nutzerauftrag oder einer echten API-Antwort stammen, nie raten. Roblox prüft die Ressourcen/Rollen des Keys. Nur call verwendet den lokal verschlüsselten Key. Schreibaktionen brauchen Vollzugriff der Sitzung. Kein automatischer Retry nach Timeout. Bei ausstehenden Operationen den passenden Lese-Endpunkt aus list nutzen.';
            params = @{
                action = @{ type = 'string'; required = $false; default = 'list'; description = 'list | describe | call' }
                scope = @{ type = 'string'; required = $false; default = '-'; description = 'Bei list nach einer exakten freigegebenen Berechtigung filtern.' }
                operation = @{ type = 'string'; required = $false; default = '-'; description = 'Bei describe/call: ID aus list.' }
                path = @{ type = 'object'; required = $false; default = '{}'; description = 'Pfadparameter aus describe, z. B. universe_id. Unkodiert übergeben.' }
                query = @{ type = 'object'; required = $false; default = '{}'; description = 'Dokumentierte Query-Parameter: Filter, updateMask, Pagination usw.; unkodiert.' }
                headers = @{ type = 'object'; required = $false; default = '{}'; description = 'Nur dokumentierte fachliche Header, niemals Authentifizierung.' }
                body = @{ type = 'any JSON'; required = $false; default = '-'; description = 'JSON-Body gemäß describe. Alle dokumentierten Felder werden weitergegeben.' }
                form = @{ type = 'object'; required = $false; default = '{}'; description = 'Multipart-Textfelder; Objekte (z. B. Asset request) werden als JSON serialisiert.' }
                files = @{ type = 'array'; required = $false; default = '[]'; description = 'Multipart-Dateien: [{field,fileName,contentType,contentBase64}]. Mehrere Dateien/gleiche Feldnamen möglich. Keine lokalen Dateipfade.' }
                contentBase64 = @{ type = 'string'; required = $false; default = '-'; description = 'Alternativ rohe Binärdatei, insbesondere RBXL/RBXLX beim Veröffentlichen.' }
                contentType = @{ type = 'string'; required = $false; default = '-'; description = 'Bei Binärdatei z. B. application/xml (RBXLX) oder application/octet-stream (RBXL).' }
            };
            returns = '{ ok, result, status?, operation?, code?, error?, requiredScopes? }';
            example = @{ action = 'list'; scope = 'asset-permissions:write' };
            errors = @('OPENCLOUD_POLICY_DENIED: nicht freigegeben.', 'OPENCLOUD_SCOPE_INCOMPLETE: genau benanntes Recht fehlt.', 'OPENCLOUD_CHECK_FAILED: keine sichere Key-Prüfung möglich.', 'READONLY_TOKEN: Schreibzugriff ausgeschaltet.', 'BAD_ARGS: Parameter korrigieren.', 'OPENCLOUD_HTTP_ERROR: Roblox hat abgelehnt oder keine Antwort geliefert; nicht blind wiederholen.') })

        $t.Add(@{ name = 'creator_dashboard'; category = 'cloud'; summary = 'Offizielle Roblox-Open-Cloud-Metadaten, Gamepasses und Developer-Produkte verwalten.';
            description = 'Verwaltet ausschließlich das aktuelle, bereits veröffentlichte Spiel der verbundenen Roblox-Studio-Sitzung. Version 7.6.0: Es gibt KEINEN lokalen Opt-in-Schalter mehr - was dieses Werkzeug darf, entscheidet allein der Open-Cloud-Schlüssel und seine Scopes (universe, universe.place, game-pass, developer-product). Fehlt ein Scope, antwortet Roblox 403 und das Werkzeug nennt ihn ehrlich (OPENCLOUD_SCOPE_MISSING). Verwendet universeId/gameId und placeId nur aus der aktiven Sitzung; frei übergebene Ziel-IDs werden abgelehnt. Unterstützt die offiziellen Open Cloud Universe-/Place-GETs und Updates für displayName/description sowie die dokumentierten Game-pass- und Developer-product-APIs (auflisten, Details lesen, erstellen, aktualisieren). Gamepass-/Produkt-Icons gehen beim Erstellen/Aktualisieren als PNG/JPEG über das dokumentierte imageFile-Multipart-Feld mit. Keine Creator-Hub-Cookies, keine undokumentierten Seiten, kein Erstellen/Löschen/Veröffentlichen von Places oder Universes. Schreibaktionen werden zusätzlich vom Read-only-Modus der aktuellen Sitzung blockiert.';
            params = @{
                action = @{ type = 'string'; required = $true; default = '-'; description = 'universe_get|universe_update|place_get|place_update|gamepass_list|gamepass_get|gamepass_create|gamepass_update|developer_product_list|developer_product_get|developer_product_create|developer_product_update.' }
                displayName = @{ type = 'string'; required = $false; default = '-'; description = 'Für universe_update/place_update: nur den Anzeigenamen ändern.' }
                description = @{ type = 'string'; required = $false; default = '-'; description = 'Für universe_update/place_update: Beschreibung ändern (leerer Text löscht sie, falls Roblox das zulässt).' }
                id = @{ type = 'string'; required = $false; default = '-'; description = 'Positive numerische ID für gamepass_get/gamepass_update/developer_product_get/developer_product_update; alternativ gamePassId oder productId.' }
                gamePassId = @{ type = 'string'; required = $false; default = '-'; description = 'Gamepass-ID für gamepass_get/gamepass_update.' }
                productId = @{ type = 'string'; required = $false; default = '-'; description = 'Developer-Product-ID für developer_product_get/developer_product_update.' }
                name = @{ type = 'string'; required = $false; default = '-'; description = 'Für gamepass_create/developer_product_create erforderlich; bei Updates optional.' }
                isForSale = @{ type = 'boolean'; required = $false; default = '-'; description = 'Gamepass/Developer-Product zum Verkauf anbieten oder deaktivieren.' }
                price = @{ type = 'integer'; required = $false; default = '-'; description = 'Standardpreis als nichtnegative int64-Robux-Zahl; Roblox prüft weitere Produktregeln.' }
                isRegionalPricingEnabled = @{ type = 'boolean'; required = $false; default = '-'; description = 'Regionale Preisgestaltung des Gamepasses/Produkts.' }
                storePageEnabled = @{ type = 'boolean'; required = $false; default = '-'; description = 'Nur für developer_product_update: externe Store-Seite aktivieren/deaktivieren.' }
                iconBase64 = @{ type = 'string'; required = $false; default = '-'; description = 'PNG/JPEG-Dateiinhalt in Base64; wird als imageFile multipart gesendet (max. 10 MiB).' }
                iconFileName = @{ type = 'string'; required = $false; default = '-'; description = 'Dateiname mit .png/.jpg/.jpeg, zusammen mit iconBase64.' }
                pageSize = @{ type = 'integer'; required = $false; default = 50; description = 'Listenseite 1-100 Einträge.' }
                pageToken = @{ type = 'string'; required = $false; default = '-'; description = 'nextPageToken aus der vorigen Listenantwort.' }
            };
            returns = '{ ok, action, status, universeId, placeId, requiredScopes, result } bzw. { ok=false, code, error, status?, robloxResponse?, howToFix? }';
            example = @{ action = 'gamepass_list'; pageSize = 50 };
            errors = @('PUBLISHED_PLACE_REQUIRED: aktive Studio-Sitzung hat keine veröffentlichten IDs.', 'READONLY_TOKEN: schreibende Aktion in einer Read-only-Sitzung.', 'OPENCLOUD_SCOPE_MISSING: Roblox nennt den erforderlichen Scope.', 'OPENCLOUD_KEY_MISSING: kein API-Schlüssel hinterlegt - userMessage WÖRTLICH an den Nutzer.', 'CREATOR_DASHBOARD_CONFLICT: z. B. Place in aktiver Team-Create-Sitzung.', 'BAD_ARGS/UNSUPPORTED_ICON_FORMAT/ICON_FORMAT_MISMATCH: ungültige Eingabe.') })

        $t.Add(@{ name = 'datastore'; category = 'cloud'; summary = 'DataStores des verbundenen Spiels über die offizielle stabile Open-Cloud-v2-API lesen und schreiben.';
            description = 'Version 7.6.0: Spielerdaten von außerhalb des Servers lesen und ändern - z. B. Savedaten prüfen, Coins korrigieren, kaputte Einträge reparieren oder Leaderboards pflegen. Verwendet die offizielle stabile API /cloud/v2/universes/{universeId}/data-stores/... und zielt AUSSCHLIESSLICH auf die Universe der verbundenen Studio-Sitzung; frei übergebene universeId/placeId werden abgelehnt. Erforderliche Scopes am Schlüssel: universe-datastores.control (list), universe-datastores.objects (list/read/create/update/delete), universe-datastores.versions (list). Fehlt ein Scope, antwortet Roblox 403 und das Werkzeug nennt den fehlenden Scope (OPENCLOUD_SCOPE_MISSING). Schreibaktionen (create/update/increment/delete) werden im Read-only-Modus blockiert. Werte sind JSON: übergib value als JSON-Wert oder valueJson als JSON-Text. Der Standard-Scope eines DataStores heißt "global" (wie DataStoreService in Studio). WICHTIG: Open Cloud trennt Anlegen und Ändern - create_entry schlägt fehl, wenn der Eintrag existiert, update_entry wenn nicht; increment_entry zählt atomar hoch (auch negativ).';
            params = @{
                action = @{ type = 'string'; required = $true; default = '-'; description = 'list_datastores|list_entries|get_entry|create_entry|update_entry|increment_entry|delete_entry|list_versions.' }
                datastoreName = @{ type = 'string'; required = $false; default = '-'; description = 'Name des DataStores, z. B. "PlayerData" (für alle Aktionen außer list_datastores; alternativ datastoreId aus list_datastores).' }
                datastoreId = @{ type = 'string'; required = $false; default = '-'; description = 'DataStore-ID aus list_datastores (Alternative zu datastoreName).' }
                scope = @{ type = 'string'; required = $false; default = 'global'; description = 'DataStore-Scope; der Engine-Standard ist "global".' }
                entryId = @{ type = 'string'; required = $false; default = '-'; description = 'Schlüssel des Eintrags (max. 50 Zeichen), z. B. "Player_12345" (Alias: entryKey, key).' }
                value = @{ type = 'any JSON'; required = $false; default = '-'; description = 'Für create_entry/update_entry: der neue Wert (Objekt, Zahl, Text, bool).' }
                valueJson = @{ type = 'string'; required = $false; default = '-'; description = 'Alternative zu value: fertiger JSON-Text des Wertes.' }
                amount = @{ type = 'number'; required = $false; default = '-'; description = 'Für increment_entry: Betrag (auch negativ, z. B. -10).' }
                pageSize = @{ type = 'integer'; required = $false; default = 50; description = 'Listenseite 1-256 Einträge.' }
                pageToken = @{ type = 'string'; required = $false; default = '-'; description = 'nextPageToken aus der vorigen Listenantwort.' }
                filter = @{ type = 'string'; required = $false; default = '-'; description = 'Für list_entries: CEL-Filter auf die ID, z. B. id.startsWith("Player_").' }
                showDeleted = @{ type = 'boolean'; required = $false; default = 'false'; description = 'Für list_datastores: zum Löschen vorgemerkte Stores mitlisten.' }
            };
            returns = '{ ok, status, action, universeId, datastoreName, scope, entryId, requiredScopes, result } bzw. { ok=false, code, error, status?, robloxResponse?, howToFix?, userMessage? }';
            example = @{ action = 'get_entry'; datastoreName = 'PlayerData'; entryId = 'Player_12345' };
            errors = @('OPENCLOUD_KEY_MISSING: kein API-Schlüssel hinterlegt - userMessage WÖRTLICH an den Nutzer.', 'OPENCLOUD_SCOPE_MISSING: dem Schlüssel fehlt ein universe-datastores-Scope.', 'DATASTORE_NOT_FOUND: Store/Eintrag unbekannt - list_datastores/list_entries zeigen die echten Namen.', 'READONLY_TOKEN: schreibende Aktion in einer Read-only-Sitzung.', 'PUBLISHED_PLACE_REQUIRED: aktive Studio-Sitzung hat keine veröffentlichte Universe-ID.', 'BAD_ARGS: ungültige Aktion/Felder.') })

        # ---------------- JOBS ----------------
        $t.Add(@{ name = 'start_job'; category = 'jobs'; summary = 'Arbeit im Hintergrund starten (keine 60s-Grenze).';
            description = 'Startet Lua-Code ODER einen Tool-Call als Job im Studio. Laeuft unabhaengig weiter, auch wenn der HTTP-Call timet-out. Fortschritt: job kann job.progress(percent, message) rufen (im Code als job-Parameter: job:progress(...)). Ergebnis: job_result. Abbruch: cancel_job (kooperativ).';
            params = @{ name = @{ type = 'string'; required = $false; default = "'job'"; description = 'Merkname.' }; source = @{ type = 'string'; required = $false; default = 'null'; description = 'Lua-Code (in der persistenten Umgebung). (alternativ tool+args)' }; tool = @{ type = 'string'; required = $false; default = 'null'; description = 'Tool-Name, der im Job laufen soll.' }; args = @{ type = 'table'; required = $false; default = '{}'; description = 'Argumente fuer tool.' } };
            returns = '{ ok, jobId, status="running", poll = "job_status / job_result" }';
            example = @{ name = 'build wall'; source = 'for i=1,500 do ... end; return "done"' };
            errors = @('BAD_ARGS: source oder tool+args angeben.', 'COMPILE_ERROR: bei source.') })
        $t.Add(@{ name = 'job_status'; category = 'jobs'; summary = 'Läuft der Job? Wie weit?';
            params = @{ jobId = @{ type = 'string'; required = $true; default = '-'; description = '' } };
            returns = '{ status: "running"|"done"|"error", progress (0..1), progressMessage, secondsElapsed, hasResult }';
            example = @{ jobId = 'job_3' };
            errors = @('JOB_NOT_FOUND') })
        $t.Add(@{ name = 'job_result'; category = 'jobs'; summary = 'Ergebnis eines fertigen Jobs holen.';
            params = @{ jobId = @{ type = 'string'; required = $true; default = '-'; description = '' }; keep = @{ type = 'bool'; required = $false; default = 'false'; description = 'true = Ergebnis behalten, sonst wird es nach dem Hohlen entfernt.' } };
            returns = '{ ok, result (Rueckgabewert), output (gedrucktes waehrend des Jobs), durationSeconds, error? { code, message } }';
            example = @{ jobId = 'job_3' };
            errors = @('JOB_NOT_FOUND', 'JOB_RUNNING: noch nicht fertig - job_status warten.') })
        $t.Add(@{ name = 'list_jobs'; category = 'jobs'; summary = 'Alle Jobs (aktiv + erledigt).';
            params = @{};
            returns = '{ jobs: [ { id, name, status, progress, secondsElapsed } ], activeCount }';
            example = @{};
            errors = @() })
        $t.Add(@{ name = 'cancel_job'; category = 'jobs'; summary = 'Job abbrechen (kooperativ).';
            description = 'Setzt ein Flag, das der Job-Code ueber job:cancelled() pruefen kann. Lua-Threads lassen sich nicht hart toeten - der Code sollte in Schlingen job:cancelled() pruefen.';
            params = @{ jobId = @{ type = 'string'; required = $true; default = '-'; description = '' } };
            returns = '{ cancelled = true, note }';
            example = @{ jobId = 'job_3' };
            errors = @('JOB_NOT_FOUND') })
        $t.Add(@{ name = 'force_fail'; category = 'jobs'; summary = 'Haengende Studio-Queue sofort leeren (Admin-Reset, ohne Studio-Neustart).';
            description = 'Rettungsanker, wenn Befehle in pendingInStudio haengen: JEDER noch offene Befehl dieses Places wird sofort mit einem endgueltigen Fehler beantwortet (Code FORCE_CLEARED), die serielle Warteschlange wird geleert und Studio wird gebeten, seine lokale Queue zu verwerfen. Kein Befehl wird wiederholt. Ein haengendes Lua im Plugin kann trotzdem einen Studio-Neustart brauchen - dann zeigt die Antwort executor.alive=false.';
            params = @{ reason = @{ type = 'string'; required = $false; default = 'cleared by admin control'; description = 'Grund, der in jeder Fehlerantwort steht.' }; code = @{ type = 'string'; required = $false; default = 'FORCE_CLEARED'; description = 'Fehlercode der Antworten (z. B. FORCE_CLEARED).' } };
            returns = '{ ok, action, clearedCommands, executor: { alive, runningCommandId, queueDepth }, queue, note }';
            example = @{ reason = 'bridge wedged after a 15 minute list_jobs block' };
            errors = @() })
        $t.Add(@{ name = 'clear_pending'; category = 'jobs'; summary = 'Alias fuer force_fail (Queue leeren).';
            description = 'Exakt dasselbe wie force_fail: alle offenen Befehle sofort mit FORCE_CLEARED beantworten und die Warteschlange leeren. Fuer Notfaelle gedacht, wenn die KI sonst nur noch Timeouts sieht.';
            params = @{ reason = @{ type = 'string'; required = $false; default = 'cleared by admin control'; description = 'Grund in der Fehlerantwort.' }; code = @{ type = 'string'; required = $false; default = 'FORCE_CLEARED'; description = 'Antwortcode.' } };
            returns = '{ ok, action, clearedCommands, executor, queue, note }';
            example = @{};
            errors = @() })
        $t.Add(@{ name = 'get_pending'; category = 'jobs'; summary = 'Was laeuft noch in Studio? (ueberlebte Timeouts).';
            description = 'Listet pro commandId ausstehende Befehle (queued/delivered/received/started), Executor-Heartbeats, Zeitbudget und späte Ergebnisse. Ein Folgeaufruf kann auf serialisierte Studio-Arbeit warten; bei Executor-Ausfall gibt der Watchdog die Queue frei und meldet, ob Teiländerungen möglich sind. Vor einem Retry Zustand prüfen.';
            params = @{};
            returns = '{ runningInStudio: [ { commandId, tool, status, seconds, queuedAt, deliveredAt, receivedAt, startedAt, heartbeatAt, budgetSeconds } ], lateResults: [ { tool, commandId, result } ] }';
            example = @{};
            errors = @() })

        # ---------------- SYSTEM ----------------
        $t.Add(@{ name = 'batch'; category = 'system'; summary = 'Viele Tools in einer Anfrage.';
            description = 'sequenziell (Standard) oder parallel=true. stopOnError=true bricht beim ersten Fehler ab. ACHTUNG: parallel=true fuehrt die Calls GLEICHZEITIG im Studio aus - nur fuer echte Unabhaengigkeiten.';
            params = @{ commands = @{ type = 'array'; required = $true; default = '-'; description = '[ { tool, args }, ... ].' }; parallel = @{ type = 'bool'; required = $false; default = 'false'; description = '' }; stopOnError = @{ type = 'bool'; required = $false; default = 'false'; description = '' }; timeoutSeconds = @{ type = 'number'; required = $false; default = '90'; description = 'parallel-Modus.' } };
            returns = '{ results: [ ...je Call... ], count, failed, mode }';
            example = @{ commands = @(@{ tool = 'create_instance'; args = @{ className = 'Part'; name = 'A' } }, @{ tool = 'create_instance'; args = @{ className = 'Part'; name = 'B' } }) };
            errors = @() })
        $t.Add(@{ name = 'parallel'; category = 'system'; summary = 'Kurzform: batch mit parallel=true.';
            params = @{ commands = @{ type = 'array'; required = $true; default = '-'; description = '' } };
            returns = 'wie batch';
            example = @{ commands = @(@{ tool = 'clone_instance'; args = @{ ref = '#42'; count = 10 } }) };
            errors = @() })
        $t.Add(@{ name = 'undo'; category = 'system'; summary = 'Letzte Aenderung rueckgaengig (Studio-History).';
            description = 'Nimmt den letzten Schritt in der Studio-History zurueck (wie Strg+Z). Unions setzen vorher automatisch einen Punkt.';
            params = @{};
            example = @{};
            returns = '{ undone }';
            errors = @('RUNTIME_ERROR: Undo nicht moeglich.') })
        $t.Add(@{ name = 'redo'; category = 'system'; summary = 'Wiederholen.';
            description = 'Macht den letzten undo wieder gueltig (wie Strg+Y).';
            params = @{};
            example = @{};
            returns = '{ redone }';
            errors = @() })
        $t.Add(@{ name = 'set_waypoint'; category = 'system'; summary = 'Undo-Punkt setzen.';
            description = 'Setzt einen sichtbaren Punkt in der Studio-History, damit der Benutzer deine Arbeit in EINEM Schritt rueckgaengig machen kann. Die Bridge setzt vor union, create, delete & Co. automatisch welche.';
            params = @{ name = @{ type = 'string'; required = $false; default = "'manual'"; description = '' } };
            returns = '{ waypoint }';
            example = @{ name = 'Before the wall' };
            errors = @() })
        $t.Add(@{ name = 'get_notices'; category = 'system'; summary = 'Was ist passiert, ohne dass du es getan hast?';
            description = 'Meldungen wie "Benutzer hat den Test gestartet/stoppt", "Plugin neu verbunden" etc. Kommen auch automatisch als notices in fast jeder Antwort.';
            params = @{ all = @{ type = 'bool'; required = $false; default = 'false'; description = 'true = auch schon gelieferte.' } };
            returns = '{ notices: [ { seq, kind, message, time, data } ] }';
            example = @{};
            errors = @() })
        $t.Add(@{ name = 'get_events'; category = 'system'; summary = 'Ereignisse von der Bridge-Seite.';
            description = 'Dasselbe wie get_notices, aber uebersteht Plugin-Reloads (wird im Programm gespeichert).';
            params = @{};
            returns = '{ events: [...], count }';
            example = @{};
            errors = @() })
        $t.Add(@{ name = 'scaffold_ui_scripts'; category = 'session'; summary = 'Aufbau-Vorschlag fuer eine Oberflaeche: welche KLEINEN Skripte, wer macht was.';
            description = 'Server-Werkzeug ohne Studio-Umlauf. Es liefert die Aufteilung (Config, State, je Bildschirm ein View, Input, Update, Effects, Data), die Reihenfolge und die Leitplanken - damit eine GUI in StarterGui als echte, editierbare Instanzen entsteht und die Logik in mehreren kleinen Skripten liegt, nicht in einem 10.000-Zeilen-LocalScript. Die Strukturmessung (codeLayout) meldet MONOLITH_RISK, wenn ein Skript ueber 400 Zeilen hat oder ueber 15 Instance.new enthaelt. Regeln: uiStructureRules.';
            params = @{ ui = @{ type = 'string'; required = $true; default = '-'; description = 'Name der Oberflaeche, z.B. "Shop".' }; screens = @{ type = 'string[]'; required = $false; default = 'null'; description = 'Bildschirmseiten, je eine bekommt ein eigenes View-Skript.' }; mode = @{ type = 'string'; required = $false; default = 'new'; description = '"new" oder "extend" (bestehende, vom Nutzer gebaute GUI erweitern).' } };
            returns = '{ ui, mode, structure, scripts: [ { name, className, responsibility, why, order } ], buildOrder, limits, note }';
            example = @{ ui = 'Shop'; screens = @( 'Shop', 'Inventory' ); mode = 'extend' };
            errors = @('BAD_ARGS: ui fehlt.') })
        $t.Add(@{ name = 'ask_user'; category = 'session'; summary = 'PFLICHT statt Chat-Frage: den Nutzer im Bridge-Fenster fragen.';
            description = 'Wenn du eine echte Nutzerantwort brauchst, verwende dieses Bridge-Werkzeug statt einer Frage im normalen Chat. Das Fenster erscheint nahe des Mauszeigers; der Nutzer antwortet dort ueber Optionen oder eigene Antwort. Chat darf nur mitteilen, dass eine Bridge-Frage offen ist. Der ganze Baum kommt in EINER Anfrage. Bedingungen erlaubt: when = [ { questionId = "fruehererId", anyOf = ["optionA"], allOf = [...], custom = true } ] auf eine FRUEHERE Frage (mehrere Ebenen tief). Der gesamte Baum zaehlt: max 12 Fragen, max 6 Optionen je Frage, max 400 Zeichen je Text, Ids eindeutig. waitSeconds (max 50) wartet; sonst liefert der Aufruf { state: "waiting", askId, nextCall } und du setzt mit derselben askId und resume=true fort. Antworten kommen notfalls als _bridge.userAnswers mit. Wenn das Werkzeug fehlschlaegt: Fehler melden und abhaengige Arbeit anhalten, nicht in den Chat ausweichen.';
            params = @{ title = @{ type = 'string'; required = $true; default = '-'; description = 'Kurze Ueberschrift (max 90 Zeichen).' }; message = @{ type = 'string'; required = $false; default = 'null'; description = 'Einleitungssatz (max 600 Zeichen).' }; questions = @{ type = 'object[]'; required = $true; default = '-'; description = 'Je Frage: { id, text, options: [ { id, label, description? } ], allowCustomResponse?, required?, multi?, when? }.' }; expiresInSeconds = @{ type = 'int'; required = $false; default = '86400'; description = '30..86400 (24 h): das Fenster bleibt offen, bis der Nutzer antwortet, abbricht oder Studio endet.' }; waitSeconds = @{ type = 'int'; required = $false; default = '0'; description = '0..50: aktiv auf die Antwort warten (0 = sofort zurueck und spaeter mit resume=true fortsetzen).' }; askId = @{ type = 'string'; required = $false; default = 'null'; description = 'Zum Fortsetzen einer offenen Frage.' }; resume = @{ type = 'bool'; required = $false; default = 'false'; description = 'true = erneut auf diese Frage warten.' } };
            returns = '{ state: waiting|answered, askId, answers: { frageId: { optionIds, labels, custom } }, path, notShown, summary, secondsLeft, nextCall }';
            example = @{ title = 'Welcher Baumstil?'; waitSeconds = 45; questions = @( @{ id = 'style'; text = 'Welchen Stil willst du?'; options = @( @{ id = 'organic'; label = 'Organisch' }, @{ id = 'lowpoly'; label = 'Low-Poly' } ) }, @{ id = 'detail'; text = 'Welche Details?'; multi = $true; when = @( @{ questionId = 'style'; anyOf = @('organic') } ); options = @( @{ id = 'leaves'; label = 'Laub' }, @{ id = 'branches'; label = 'Zweige' } ) } ) };
            errors = @('ASK_TOO_MANY_QUESTIONS: mehr als 12 Fragen oder mehr als 6 Optionen je Frage.', 'ASK_GRAPH_INVALID: doppelte/fehlende Ids, unbekannte Bedingung, weniger als 2 Optionen.', 'ASK_CYCLE: eine Frage haengt von sich selbst oder einer SPAETEREN Frage ab.', 'ASK_EXPIRED: das Fenster lief ab, ohne dass geantwortet wurde.', 'ASK_UNKNOWN: unbekannte askId.') })
        $t.Add(@{ name = 'confirm_action'; category = 'session'; summary = 'PFLICHT statt Chat-Frage: Ja/Nein im Bridge-Fenster bestaetigen lassen.';
            description = 'Abkuerzung fuer ask_user mit genau einer Frage und zwei Optionen. Verwende sie fuer erforderliche Ja/Nein-Entscheidungen und riskante Schritte statt in normalem Chat um eine Antwort zu bitten. Fuer Loeschungen, Umbauten, Ueberschreiben von Nutzerarbeit oder teure Schritte. Der Nutzer kann auch eine eigene Antwort schreiben.';
            params = @{ title = @{ type = 'string'; required = $true; default = '-'; description = 'Was bestaetigt werden soll.' }; message = @{ type = 'string'; required = $false; default = 'null'; description = 'Was passiert, wenn der Nutzer zustimmt.' }; confirmLabel = @{ type = 'string'; required = $false; default = 'Ja, mach das'; description = '' }; cancelLabel = @{ type = 'string'; required = $false; default = 'Nein, nicht'; description = '' }; expiresInSeconds = @{ type = 'int'; required = $false; default = '86400'; description = '30..86400 (24 h): das Fenster bleibt offen, bis der Nutzer antwortet oder abbricht.' }; waitSeconds = @{ type = 'int'; required = $false; default = '0'; description = '0..50, wie ask_user.' } };
            returns = '{ state, askId, confirmed: true/false, customResponse, answers, path, notShown, summary }';
            example = @{ title = 'Darf ich das bestehende Gebaeude ersetzen?'; message = 'Alle Teile des alten Hauses werden geloescht und neu gebaut.'; waitSeconds = 45 };
            errors = @('ASK_EXPIRED: keine Antwort im Zeitfenster.', 'ASK_UNKNOWN: unbekannte askId.') })
        $t.Add(@{ name = 'wait_for_user'; category = 'session'; summary = 'Aktiv auf eine Nachricht des Nutzers warten (max. 50 s).';
            description = 'Blockiert, bis der Nutzer ueber die Bridge schreibt ("Nachricht an Arena senden" im Menue der Place-Zeile) oder die Zeit ablaeuft. Die Nachrichten selbst stehen im Umschlag DERSELBEN Antwort unter _bridge.userMessages. Nur an einer echten Entscheidungsstelle benutzen, nie als Dauer-Polling. Der harte HTTP-Deckel liegt bei 55/85 s, deshalb ist maxSeconds auf 50 begrenzt.';
            params = @{ maxSeconds = @{ type = 'int'; required = $false; default = '30'; description = '1..50.' } };
            returns = '{ state: messages_waiting|timeout, reason, waitedSeconds, messageCount, maxSeconds, note }';
            example = @{ maxSeconds = 25 };
            errors = @() })
        $t.Add(@{ name = 'ack_user_message'; category = 'session'; summary = 'Nachricht des Nutzers als gelesen bestaetigen (Pflicht).';
            description = 'Beendet die Wiederholung einer Nutzernachricht und zeigt dem Nutzer im Fenster "von Arena bestaetigt" plus deine optionale Kurzantwort. Ohne Bestaetigung wird dieselbe Nachricht in bis zu drei Antworten wiederholt und die Oberflaeche meldet ehrlich "angekommen, nicht bestaetigt".';
            params = @{ id = @{ type = 'string'; required = $false; default = 'null'; description = 'Eine Nachrichten-Id aus _bridge.userMessages.' }; ids = @{ type = 'string[]'; required = $false; default = 'null'; description = 'Mehrere Ids.' }; all = @{ type = 'bool'; required = $false; default = 'false'; description = 'true = alle offenen Nachrichten.' }; reply = @{ type = 'string'; required = $false; default = 'null'; description = 'Kurze Antwort an den Nutzer (max. 300 Zeichen).' } };
            returns = '{ acked, replyShownToUser, note }';
            example = @{ id = 'msg_ab12cd34ef56'; reply = 'Verstanden - ich baue den Baum neu.' };
            errors = @('BAD_ARGS: weder id, ids noch all=true.', 'ACK_UNKNOWN_MESSAGE: keine offene Nachricht mit dieser Id (knownMessageIds nennt die gueltigen).') })
        $t.Add(@{ name = 'get_chunk'; category = 'system'; summary = 'Stueck eines grossen Ergebnisses holen.';
            description = 'Wenn eine Antwort zu gross ist, liegt sie im Programm: blobId + chunkCount. Alle Chunks in Reihe holen und zusammenfuegen = komplettes Ergebnis (nie abgeschnitten).';
            params = @{ blobId = @{ type = 'string'; required = $true; default = '-'; description = '' }; index = @{ type = 'int'; required = $true; default = '-'; description = '1..chunkCount.' } };
            returns = '{ data, index, chunkCount, isLast, totalChars }';
            example = @{ blobId = 'blob_abc'; index = 1 };
            errors = @('REF_NOT_FOUND: unbekanntes/abgelaufenes blobId (30 Min).') })
        $t.Add(@{ name = 'upload_text'; category = 'system'; summary = 'Grossen Text in Stuecken hochladen.';
            description = 'Fuer Skriptquellen > 50 KB: in Chunks hierher, danach sourceRef=<uploadId> an set_script_source/insert_script. Der Text wird unverändert übernommen (kein String-Schneidwerk, keine %-Kollisionen).';
            params = @{ text = @{ type = 'string'; required = $true; default = '-'; description = 'Stueck (oder alles).' }; uploadId = @{ type = 'string'; required = $false; default = 'neu'; description = 'Fuer mehrere Chunks: gleicher Wert.' }; chunkIndex = @{ type = 'int'; required = $false; default = '1'; description = '' }; chunkCount = @{ type = 'int'; required = $false; default = '1'; description = '' } };
            returns = '{ uploadId, chars, complete, useAs }';
            example = @{ text = 'local M = {}'; chunkIndex = 1; chunkCount = 3; uploadId = 'myScript' };
            errors = @() })
        $t.Add(@{ name = 'get_docs'; category = 'system'; summary = 'Doku holen: pro Tool, pro Kategorie oder komplett.';
            description = 'Dasselbe wie GET /api/docs - als Tool. Ohne Argumente: komplett. Version 7.1.4: Der Sessionstart liefert nur noch die Kernwerkzeuge vollstaendig (Bauen, Audit, Lesen, Sitzung) und alle uebrigen als Index mit Name/Kategorie/Kurztext. Vor dem ersten Einsatz eines Index-Werkzeugs hier die Parameter holen - die Doku ist hier IMMER vollstaendig.';
            params = @{ tool = @{ type = 'string'; required = $false; default = 'null'; description = 'Einzelnes Tool (z.B. "union").' }; category = @{ type = 'string'; required = $false; default = 'null'; description = 'info, spatial, orientation, create, properties, scripts, fill, union, assets, output, play, gui, jobs, system.' }; full = @{ type = 'bool'; required = $false; default = 'false'; description = 'Komplette Doku.' } };
            returns = 'Doku-JSON (siehe /api/docs)';
            example = @{ tool = 'fill_region' };
            errors = @('REF_NOT_FOUND: unbekanntes Tool/Kategorie (Liste im Fehler).') })
        $t.Add(@{ name = 'capture_screenshot'; category = 'system'; summary = 'Roblox-Studio-Fenster als Screenshot erfassen.';
            description = 'Erfasst das Studio-Fenster. Arena kann frei zwischen Screenshot und den textuellen Szenenwerkzeugen mit exakten Objektwerten wählen.';
            params = @{ confirm = @{ type = 'bool'; required = $false; default = 'false'; description = 'Aus Kompatibilitaetsgruenden akzeptiert; nicht mehr erforderlich.' }; includeBase64 = @{ type = 'bool'; required = $false; default = 'false'; description = 'Bild als Base64-Blob.' }; maxWidth = @{ type = 'int'; required = $false; default = '1100'; description = '' } };
            returns = '{ file, width, height, advice }';
            example = @{ confirm = $true };
            errors = @('RUNTIME_ERROR: Studio-Fenster nicht sichtbar.') })

        return ,$t
    }


    # ------------------------------------------------------------------
    # MANIFEST: die Bedienungsanleitung für die KI
    # ------------------------------------------------------------------
    # ==================================================================
    # GELEITINFORMATIONEN: Regeln, Koordinaten, Play-Modi, Jobs, Fehler-
    # Codes, Workflows. Stecken in Manifest, /api/docs und _sessionStart.
    # ==================================================================
    function Get-BridgeAskUserProtocol {
        return @{
            required = $true
            channel = 'Arena Roblox Bridge ask_user/confirm_action window'
            whenToUse = 'Use the Bridge question tools whenever a real user choice or clarification is needed to continue safely or correctly; do not ask routine questions whose answers are already known.'
            toolChoice = 'Use confirm_action for one yes/no confirmation and ask_user for clarification, custom text, or multiple/conditional choices. Put related choices into one ask_user decision tree.'
            chatRule = 'Never ask the user to answer a question in ordinary chat and never wait for a chat reply. Chat may only announce that the Bridge question window is open and ask the user to answer there.'
            waiting = 'Keep the same askId open and resume it with ask_user { askId, resume: true } until answered or cancelled. Read _bridge.userAnswers and never guess while openQuestions is present.'
            toolFailure = 'If a Bridge question tool fails or is unavailable, explain the exact error and stop work that depends on the answer. Do not fall back to a normal chat question.'
        }
    }

    function Get-BridgeGuides {
        $askUserProtocol = Get-BridgeAskUserProtocol
        return @{
            askUserProtocol = $askUserProtocol
            importantRules = @(
                'Choose the tools and workflow that best fit the task. The bridge exposes precise read, build, script, asset, playtest and batch tools; these are capabilities, not a mandatory checklist.',
                'BLENDER-FIRST (Version 7.5.5): For ANY nontrivial custom 3D model the standard is build_mesh_model (Blender), then upload_asset, then mesh_apply_asset. build_polygon_model is NOT the default any more. Use it ONLY when the user explicitly asks for polygon building - then pass userRequestedPolygon=true. Before that call you warn the user yourself: many WedgeParts can make Roblox Studio lag badly, and you recommend the Blender path. Native Parts stay right for truly simple, repeated or explicitly primitive geometry; build_assembly complements repeats; do not reduce a hero/custom model to primitive blocks. Only in an allowed polygon build (userRequestedPolygon=true): NEVER set autoWeld=false unless physically independent polygon pieces are requested. Afterward verify incomplete=false, facesSkipped=0, skipped=[]; inspect fallbackFaces/warnings, run model_audit. See modelBuildRules for the finish bar.',
                'NONTRIVIAL 3D BUILD METHOD (ALL CATEGORIES, Version 7.5.5): Blender first. Follow modelBuildRules.blenderWorkflow: build_mesh_model per form (one model = one mesh, see meshBuildRules), wait for mesh_status to report uploadReady, upload_asset, mesh_apply_asset, then model_audit and fix the findings. Polygon building (build_polygon_model) only with userRequestedPolygon=true after the lag warning. This applies equally to architecture, vehicles, furniture, machines, props, terrain, characters and creatures; only truly simple standard shapes or explicit primitive/blockout requests are exceptions.',
                'For any visual/3D deliverable, make the result intentionally layered and finished: clear primary silhouette, secondary functional forms, tertiary trim/details, coherent palette/materials, and correct joins/placement. Complexity must be purposeful, not random part count. A simple object may remain simple; an unrequested blockout/primitive-only first draft is not a finished build. This standard is global and does not depend on model names or animal/tree examples.',
                'For ANY visual/GUI work, ALWAYS use build_interface (whole screen in one call) or build_surface unless the user explicitly asks for raw GuiObjects: the bridge owns AnchorPoint, Scale-only UDim2, aspect locking, corner-safe padding, layered shadows, scaled strokes, gradients on strokes, REAL raster textures, CanvasGroup discipline and the runtime motion script. Call ui_capabilities first (it probes this Studio build instead of trusting training data), ui_skin to pick or extract an art direction, ui_glow for glow (never hand-build it), ui_texture for the real-texture-first recipe, ui_radial for radial menus (one image id, both colours engine-owned), and ui_audit afterwards - it measures offsetRatio, contrast, per-device pixel sizes, glow/texture/radial usage and a blandness score. See uiEngineRules below for the hard rules.',
                'Object ids such as #42 are stable within the current plugin session and avoid ambiguity when names repeat. Paths and selectors are also accepted where documented.',
                'Several Places can be connected. With the Alle-Places token, GET /api/places returns targetPlace values; selecting one target keeps edits unambiguous.',
                'Queue recovery is explicit and diagnosable: GET /api/queue shows queued/delivered/running commandIds, delivery/start timestamps and executor liveness; POST /api/queue with action=cancel and commandId cancels one command, while action=reset abandons pending work and asks the plugin to reset its local queue. A reset/cancel can leave partial edits; inspect before retrying.',
                'Normal GET and POST tool calls use the same bridge code path. Queue cancellation/reset are mutating controls and require POST.',
                'After an HTTP timeout, a Studio command remains tracked by commandId and may return through _bridge.lateResults. A plugin execution budget and an INDEPENDENT server-side watchdog (queue.sweep) abandon stalled commands so they cannot block the serial queue forever; inspect the Place before retrying because partial changes may exist. Use asJob=true when a long task should deliberately continue in the background. HTTP answers are capped at 55 seconds by default (85 seconds maximum) so a Cloudflare 524 can never cut the connection before the bridge replies.',
                'Asset search covers the Creator Store categories including 3D models, models, meshes/MeshParts, plugins, fonts, audio, images/decals, video and animation. Insertion still reports Roblox permission/privacy errors and warns before inserting scripts.',
                'OPEN-CLOUD-POLICY (7.6.2): use open_cloud list/describe/call for the full approved catalog. The fixed user allowlist AND the exact required key permissions apply. No blanket Read+Write requirement. No key export or arbitrary URL forwarding. Banned functions remain banned even with an all-permissions key. Failed introspection blocks calls; keys with expiration are refused. Mutations require readwrite session access. Existing creator_dashboard/datastore shortcuts stay session-bound. open_cloud accepts documented resource IDs for the user task; Roblox checks resource authorization.',
                'sim_start is disabled because the former official Studio Run simulation exits Edit mode (EditModeActive=false), and the documented Studio API has no supported true Edit-mode physics/script path. A USER-started Play/F5 test is separate, blocks building (USER_PLAYTEST_ACTIVE), and can only be ended by the user.',
                'Windows finish notifications use report_done { title, message }. Arena writes a lively title (max 70 characters) and an inviting body (max 140); avoid dry changelog lists.',
                'Responses include typed error codes and concrete diagnostics. Use those details to decide the next step.',
                'HARD CONSTRAINT for any hand-written WedgePart/triangle geometry (build_polygon_model already does this correctly - this rule is for genuinely custom run_lua geometry code only): see polygonEngineRules below for the mandatory WedgePart axis convention and the canonical seamless-triangle formula. Getting the axis order wrong is the single most common cause of 90-degree rotation errors and gaping seams in procedural low-poly builds.',
                'BRIDGE-ONLY QUESTIONS (mandatory, 7.5.8): whenever a user answer is needed to continue safely or correctly, ask via ask_user in the Bridge for clarification/choices or confirm_action for yes/no. Never pose the question in normal chat and never wait for a chat reply. Chat may only say that a Bridge question window is open and ask the user to answer there. Put related decisions in one ask_user tree; resume the same askId until answered/cancelled; read _bridge.userAnswers and never guess while openQuestions is present. If the Bridge tool fails, report the exact error and stop dependent work - do not fall back to chat.',
                'FINISH GRADE (7.2.0): model_audit now grades every build (finishScore 0..100, grade draft/simple/detailed/sculpted). grade "draft" means at least 4 parts, no polygon/mesh/union/detail geometry and more than 60 % primitives - report_done answers DRAFT_GRADE_RISK until you rebuild the silhouette with real structure. If the simplicity IS what the user asked for, declare it while building: build_polygon_model/build_assembly { grade = "simple" | "lowpoly" | "blockout" } writes the attribute ArenaDeclaredGrade and the audit stops calling it a draft. report_done also returns buildRegister: it lists what you built and what model_audit has not measured yet.',
                'USER CHANNEL (7.2.0, HARDENED 7.6.0): the user can message you WHILE you work ("Nachricht an Arena senden" in the bridge place row). Every response then carries _bridge.userMessages plus _bridge.userMessageContract, the message text appears at the TOP and the BOTTOM of _bridge.attention, and _bridge.openUserMessageCount tells you how many messages are still unacknowledged. Read it first, apply it, tell the user what you changed, and acknowledge with ack_user_message { id } - an unacknowledged message repeats in up to TEN responses AND report_done fails with UNACKED_USER_MESSAGE until every message is acknowledged, so a message can never be forgotten or outlasted. wait_for_user { maxSeconds <= 50 } blocks until a message arrives; use it only at a real decision point, never as polling. The user can also switch the place to read-only from the same menu, which is reported as WRITE_LOCKED_BY_USER.'
                'HARD ORGANIC EVIDENCE CONTRACT (separate from the global builder preference): when an organic model is explicitly built with organic=true or is registered from per-model model_audit evidence, build and audit the real model in Studio, use a deliberate palette, install motion under that model, and fix its organicQuality issues. report_done requires fresh passing evidence for every registered organic model, even after a handoff. This is not selected or enforced from animal/tree names; see organicBuildRules for the stricter per-organic-model evidence contract.'
                'BLENDER-MESH-BAU (7.5.0, der starke Weg fuer anspruchsvolle Modelle - ausdruecklich empfohlen): build_mesh_model laesst Blender im Hintergrund die Form bauen, die Bridge MISST sie (Dreiecke, Groesse in Studs), legt die viereckigen MeshPart-Platzhalter in den Place und erzeugt je Slot eine Upload-Datei (FBX, sonst GLB). Danach ist der Upload DEIN Schritt und keiner des Nutzers mehr: upload_asset { slotKey } schickt die Datei ueber die Roblox-Open-Cloud-API nach Roblox und nennt dir die ECHTE Asset-Id; mesh_apply_asset setzt die Geometrie in die bestehenden Platzhalter (applyPath nennt den Weg). Der Nutzer laedt NICHTS mehr von Hand hoch - das Fenster "Mesh-Uploads" ist seit 7.5.0 entfernt. Braucht er erst einen Open-Cloud-Schluessel, antwortet upload_asset mit OPENCLOUD_KEY_MISSING und einem userMessage-Satz: sage ihn ihm WORTLICH (Einstellungen -> ROBLOX OPEN CLOUD -> Tutorial). Solange ein Platzhalter noch keine Geometrie hat, ist es KEIN fertiges Modell: report_done antwortet MESH_UPLOAD_PENDING. Siehe meshBuildRules und cloudUploadRules.',
                'BAUEN GEHT VOR SUCHEN UND VOR PRIMITIVEN (7.5.5, Blender-first): baue eigene 3D-Geometrie, statt sie im Katalog zu suchen oder aus Baellen und Bloecken zusammenzustecken. Fuer jede nichttriviale Form nimm build_mesh_model (Blender) - der Standardweg. build_polygon_model nur auf ausdruecklichen Nutzerwunsch (userRequestedPolygon=true), und dann warnst du vorher vor Lag durch viele WedgeParts und empfiehlst Blender. Der Katalog (search_assets/insert_asset) ist ein NOTBEHELFER, den du dem Nutzer anbietest - kein Standard. Bloecke, Kugeln und Zylinder sind Bausteine fuer einfache Stuetzen und Details, nicht fuer das Modell selbst.'
            )
            worldEngineRules = @{
                title = 'World Engine 1.0 - the world is a place with rules, not a pile of parts'
                workflow = 'site_survey (measure ground, water, clearance, existing parts) -> world_style (palette, materials, density, weathering, seed) -> style_lock -> build with prop_place / build_assembly / build_polygon_model / refine -> model_audit + world_audit. Never place a large build without the survey, never call it finished while model_audit reports placeholders.'
                determinism = 'EVERY variation comes from the style seed (prop_place, refine, variation). The same seed must rebuild the same world - math.random is forbidden for anything a user could see twice.'
                styleLock = 'A style lock turns measurement on: world_audit then reports styleCompliance, colour distance and off-style parts. Building without a style is allowed but measurably worse - that is the honest contract, not a hidden penalty.'
                light = 'Light comes from world_glow (one engine-built light per part, clamped brightness/range). Never fake glow with stacked transparent spheres or dozens of flickering lights, and never leave a night scene without Atmosphere/Sky.'
                phases = 'model_audit phases: blockout (placeholders/blockouts exist) -> modelled (clean geometry, no mesh/union yet) -> refined (ArenaDetail parts exist) -> polished (details + light + atmosphere). report_done is only honest in refined/polished; blockout means handoff or keep working.'
                props = 'prop_save stores a selection under workspace.ArenaProps; prop_place clones it with deterministic variation and ground snap. Prefer saved props over rebuilding the same tree ten times by hand.'
            }
            toolboxRules = @{
                title = 'Toolbox Engine 1.0 (Version 7.5.5) - Blender first, catalog last, never in parallel'
                default = 'BLENDER FIRST (Version 7.5.5): Jedes nichttriviale 3D-Modell baut Arena ueber build_mesh_model (Blender), dann upload_asset und mesh_apply_asset. build_polygon_model ist KEIN Standard mehr: nur auf ausdruecklichen Nutzerwunsch (userRequestedPolygon=true), und dann warnt Arena vorher vor Lag durch viele WedgeParts und empfiehlt Blender. Primitive und Katalog sind Notbehelfe. Keep simple tasks simple. Organic models use the same Blender path with an explicit palette and enabled motion; fresh evidence is required before report_done.'
                beforeUsingTheCatalog = 'If a procedural shape is genuinely not realistic enough or technically out of reach, say so and OFFER a limited, transparent fallback FIRST. Let the user decide. Do not start catalog calls on your own initiative.'
                hardLimits = 'Per place the bridge allows at most 2 catalog requests at a time and EXACTLY ONE active asset import. Anything beyond that answers immediately with TOOLBOX_BUSY or TOOLBOX_IMPORT_IN_FLIGHT. Never run asset searches in parallel, never poll in a loop, and never retry automatically after a timeout.'
                timeouts = 'Every catalog request has a hard time limit (12 s, 8 s for the pre-insert validation) and a 25 s budget per tool call. A failure is FINAL and typed: CATALOG_TIMEOUT or CATALOG_UNAVAILABLE. Say "Katalog nicht verfuegbar" to the user and continue procedurally instead of retrying.'
                insertIsNotCancellable = 'InsertService:LoadAsset is a native yielding Roblox call that CANNOT be aborted. If an import hangs you get TOOLBOX_IMPORT_UNCONFIRMED and then TOOLBOX_IMPORT_WEDGED; imports stay locked for that place. Do NOT retry - ask the user to close Roblox Studio completely and reopen the place, check for a half-inserted model, then build procedurally.'
                idempotency = 'Repeating the same insert_asset (same assetId/parentRef/name) inside 120 s returns the stored result with idempotentReplay=true and inserts NOTHING a second time. Pass a fresh requestId or allowDuplicate=true when a second copy is really wanted.'
            }
            polygonEngineRules = @{
                title = 'Polygon Engine 2.0 - canonical WedgePart rule (prevents 90-degree rotation errors and seam gaps forever)'
                whenThisApplies = 'build_polygon_model already implements this correctly (longest-edge base, side-corrected inward skin offset, retry/fallback triangulation, vertex welding) - always STRONGLY prefer it for modelling. Only read on if you are writing bespoke geometry directly with run_lua/Instance.new("WedgePart") because the task needs logic the tool does not cover.'
                axisRule = 'The slanted face of a WedgePart is NEVER in its local X plane. Local X = thickness / face normal. Local Y = height / the axis orthogonal to the base edge. Local Z = the base-edge direction (dir, or -dir for the mirrored half). Build every WedgePart CFrame as CFrame.fromMatrix(position, normal, up, dir) - swapping which vector goes into which slot is exactly what produces 90-degree rotation errors.'
                seamRule = 'Seam gaps come from placing the wedge thickness symmetrically around the supplied skin points. Instead, treat the given triangle points as the exact outer skin and shift the whole wedge inward by half the thickness along -normal (skinOffset = -normal * thickness * 0.5) before building the CFrame, so neighbouring faces overlap cleanly on the inside instead of leaving visible grooves.'
                referenceLua = @'
-- Canonical zero-error formula for hand-written run_lua triangle/wedge builders.
-- applyProps(part, props, parent) is your own helper that sets Color/Material/
-- Anchored/CanCollide/Parent etc. - keep using whatever the rest of your script uses.
local function drawSeamlessTriangle(p1, p2, p3, parent, props)
    -- 1. Re-label so the LONGEST edge becomes the base (p2 -> p3); this
    --    guarantees the altitude foot from p1 lands inside that edge.
    local ab, ac, bc = (p2-p1).Magnitude, (p3-p1).Magnitude, (p3-p2).Magnitude
    if ab >= ac and ab >= bc then p1, p2, p3 = p3, p1, p2
    elseif ac >= ab and ac >= bc then p1, p2, p3 = p2, p3, p1 end

    local baseVec = p3 - p2
    local baseLen = baseVec.Magnitude
    if baseLen < 0.001 then return end
    local dir = baseVec.Unit

    -- 2. Face normal and the altitude foot point (pMid) on the base edge.
    local normal = (p2 - p1):Cross(p3 - p1).Unit
    local proj = (p1 - p2):Dot(dir)
    local pMid = p2 + dir * proj
    local height = (p1 - pMid).Magnitude
    local up = (p1 - pMid).Unit

    local len1 = proj
    local len2 = baseLen - proj
    local thickness = props.Thickness or 0.2

    -- 3. Side-corrected skin placement: shift the wedge thickness INWARD so
    --    the given points stay the exact outer skin and neighbours seal.
    local skinOffset = -normal * (thickness * 0.5)

    -- Wedge 1 (pMid -> p2): local X=normal (thickness), Y=up (height), Z=-dir (base).
    if len1 > 0.01 and height > 0.01 then
        local w1 = Instance.new("WedgePart")
        w1.Size = Vector3.new(thickness, height, len1)
        w1.CFrame = CFrame.fromMatrix((pMid + p2)/2 + up * (height/2) + skinOffset, normal, up, -dir)
        applyProps(w1, props, parent)
    end

    -- Wedge 2 (pMid -> p3): mirrored, Z=dir.
    if len2 > 0.01 and height > 0.01 then
        local w2 = Instance.new("WedgePart")
        w2.Size = Vector3.new(thickness, height, len2)
        w2.CFrame = CFrame.fromMatrix((pMid + p3)/2 + up * (height/2) + skinOffset, -normal, up, dir)
        applyProps(w2, props, parent)
    end
end
'@
            }
            modelBuildRules = @{
                title = 'Model Build Engine 1.1 - universal polygon workflow for every nontrivial 3D category'
                whenThisApplies = 'Every task that creates or materially remodels visible 3D geometry, regardless of subject, model name or whether it is organic. This is a global build preference, not an animal/tree-only rule.'
                default = 'For every nontrivial custom model, aim materially beyond a first-pass primitive sketch. Design a readable primary silhouette, add secondary forms that explain function and proportion, then add restrained tertiary details, trim, joints and surface structure. Use explicit, coherent color/material roles and correct attachment/placement. More parts without design purpose is not more quality.'
                polygonPreference = 'BLENDER-FIRST (Version 7.5.5): For EVERY nontrivial custom visible 3D model in ANY category the first model-creation call is build_mesh_model (one model = one mesh, see meshBuildRules). build_polygon_model is NOT the first call any more - it needs an explicit user request (userRequestedPolygon=true) and a prior warning to the user about lag from many WedgeParts. Native Parts remain right for genuinely standard supports, pivots and small accents; build_assembly for repeated modules.'
                polygonDecision = 'Choose the geometry representation by shape, not by subject: polygons = individual planar faces/panels; submodels = named components and material/color groups containing faces; volumes = closed lofts for a shape whose cross-section changes along a centerline; build_assembly = repeated modules; native Parts = genuinely standard supports, pivots and accents. A polygon is one skin, not a solid: construct front/back/sides/ends or use closeOpenings for unmatched loops. A single front silhouette plus thickness is still a plate.'
                polygonInputContract = 'Structured form: build_polygon_model { modelName, origin={x,y,z}, rotation={x,y,z in degrees}, scale, style={...}, submodels=[{name,style,polygons=[{name,points=[{x,y,z},...],style?}]}], volumes=[{name,role,sides=6..16,sections=[{center,heightRadius,depthRadius},...]}], closeOpenings, autoWeld, mainWelds, maxWedges }. Points are actual local geometry. Each face must have >=3 ordered distinct coplanar vertices, no self-crossing/duplicate/collinear runs. origin/rotation/scale transform the model; Position/Size/CFrame/Orientation inside polygon properties are ignored.'
                polygonWorkflow = '1 inspect Place/selection and choose a stable frame, dimensions, palette/materials. 2 Plan the full silhouette as named large forms and surfaces before writing. 3 Make one structured build_polygon_model call for the principal model; share exact coordinates on adjacent face edges. 4 Add repeated modules via build_assembly and deliberate details/refine; do not replace the hero silhouette with blocks. 5 Read the returned model id, result.incomplete, facesSkipped, skipped, fallbackFaces, triangles, wedges, warnings and geometry. Do NOT accept ok=true as proof when faces are skipped. Fix bad named faces/point loops and rebuild. 6 Run model_audit on the returned model, plus world_audit for scenes; fix findings before report_done. The core build_polygon_model docs include a complete closed LowPolyHouse example.'
                polygonPatterns = 'Facade/roof/shield/panel = explicit planar polygons; closed box/building/housing = all outer faces sharing exact edge coordinates; tapered curved hull/handle/shaft/column/branch = volume stations with heightRadius+depthRadius; arches/frames can be assembled from individually valid faces plus repeated supports; rails/windows/spokes/ribs = build_assembly. Use closeOpenings=true only as an auto-cap safety net, not as a substitute for planning the shell. For cross-submodel motion, set parts unanchored and use mainWelds; inside each submodel AutoWeld is already on.'
                polygonBudget = 'Each n-vertex face usually produces n-2 triangles and two WedgeParts per triangle. Budget about 2*(n-2) wedges per polygon plus volume/cap faces. The default maxWedges is 4000 and the hard maximum is 10000; simplify/split into coherent submodels if necessary. A normal OK response may carry incomplete=true or warnings: require facesSkipped=0 and skipped=[] and inspect fallbackFaces.'
                polygonTemplate = 'build_polygon_model { modelName="<name>", grade="lowpoly|detailed|simple|blockout", origin={x=0,y=0,z=0}, rotation={x=0,y=0,z=0}, scale=1, style={thickness=0.04,anchored=true,canCollide=false}, submodels=[{name="Shell",style={color="#...",material="SmoothPlastic"},polygons=[{name="Front",points=[...]},{name="Back",points=[...]},{name="SideA",points=[...]},{name="SideB",points=[...]},{name="Top",points=[...]},{name="Bottom",points=[...]}]}], autoWeld=true, maxWedges=4000 }. This is a closed-shell skeleton: replace each placeholder with valid ordered planar coordinates and expand to the complete silhouette; the LowPolyHouse tool example is a fully specified call.'
                complementaryTools = 'Use build_assembly for repeated structural or modular pieces (frames, stairs, rails, facades, ribs, supports) and combine it with a polygon-built hero silhouette when both are useful. Use native Parts for genuinely simple standard shapes, structural supports, joints, pivots and small accents; bulk_create/grid/clone are for repetition, not for replacing the distinctive centerpiece with blocks.'
                finishBar = 'A nontrivial standalone asset is not complete as one box/cylinder or a primitive-only placeholder: complete the main form, its supporting components, visual details, coherent palette/materials, welds/collision and grounding as relevant. For scenes, add purposeful variation, depth, readable pathways and consistent style. Low-poly is a style, not permission to stop at a primitive blockout.'
                exceptions = 'Keep inherently simple tasks simple and follow explicit user requests for primitives, blockouts, low part counts or a deliberately plain style. Scale scope to time/tool/part limits; reduce how many assets are built instead of degrading the finish of each delivered asset.'
                workflow = 'inspect/select/measure -> choose art direction or world_style -> build_mesh_model (Blender, STANDARD) -> mesh_status uploadReady -> upload_asset -> mesh_apply_asset -> assembly/native support geometry -> detail/refine -> model_audit (and world_audit for scenes) -> fix measured issues -> report_done. Build directly in the target Place; a generated source file or later unsupported quality claim is not a model. Polygon building only with userRequestedPolygon=true after the lag warning.'
                motion = 'Add animation only when the task requests motion or the object is inherently living/moving. For organic models, explicitly use organic=true so per-model geometry, palette, enabled-motion and fresh-audit evidence is enforced; see organicBuildRules.'
            }
            meshBuildRules = @{
                title = 'Mesh-Build Engine 1.3 (Version 7.5.8) - STANDARDWEG: EIN Modell ist EIN Mesh, Blender baut, der Agent laedt hoch (Open Cloud), die Bridge setzt ein'
                whenThisApplies = 'DER STANDARDWEG (Version 7.5.5, Blender-first): Jedes 3D-Modell, das Arena baut, laeuft zuerst ueber Blender - egal ob Form, Organik oder Detailgrad. build_polygon_model gibt es nur noch auf ausdruecklichen Nutzerwunsch (userRequestedPolygon=true) und dann nur nach der Lag-Warnung. Seit 7.5.0 ist der Upload VOLL AUTOMATISIERT - der Nutzer muss nichts mehr hochladen.'
                ONE_MODEL_ONE_MESH = 'HARTE REGEL SEIT 7.5.1 (Owner-Beschwerde: "Warum baut mir Arena Wurzel, Stamm, Aeste und Kronen einzeln"): EIN zusammenhaengendes Modell wird als EIN Mesh in EINEM Slot gebaut - ein Baum ist EIN Mesh, ein Fass EIN Mesh, eine Laterne EIN Mesh. Mehrere Slots sind NUR in genau drei Faellen erlaubt: (1) bestimmte Teile werden ANIMIERT (je bewegliches Glied ein Slot), (2) bestimmte Teile brauchen EIGENE EIGENSCHAFTEN (eigene Farbe/Material/CanCollide/Transparenz, die ein einzelnes MeshPart nicht tragen kann), (3) die DREIECKSZAHL sprengt das Budget (dann nach Koerperteilen splitten, nicht nach "Wurzel/Stamm/Aeste/Krone"-Raten). Sonst gilt: EIN Blender-Skript, das die ganze Form baut - inklusive Wurzeln, Krone, Blaetter oder Details -, EIN Slot, EIN MeshPart. Wer ohne einen dieser drei Gruende splittet, macht die Arbeit des Nutzers groesser (mehr Uploads, mehr Platzhalter, mehr MeshParts) und hat den Bau nicht verstanden.'
                slots = 'Mehrere Slots NUR nach der Regel oben. Wenn wirklich geteilt wird, dann nach Funktion: je bewegliches Glied ein Slot (Kreatur, Fahrzeug, Maschine, Tuer, Rad) und die Gelenke wie gewohnt mit Welds/Motor6D verbinden; ein MeshPart traegt genau EINE Farbe/EIN Material (Roblox uebernimmt keine Blender-Materialien) - unterschiedliche Farben sind der zweite legitime Grund. Farbe und Material setzt Roblox ueber die Slot-Angaben color/material. Eine Zierde (Blatt, Blume, Frucht, Zierband) gehoert in DASSELBE Mesh, solange sie sich nicht bewegen muss.'
                axesAndUnits = 'ACHSEN UND EINHEITEN - hier hat sich 7.5.0 selbst widersprochen, das gilt jetzt eindeutig: 1 Blender-Einheit = 1 Stud. Im Blender-Skript ist Z OBEN (Blender-Konvention; alle Bauten im Skript also mit Z als Hoehe). Der Runner/Export dreht das GANZE Modell beim Export in die Roblox-Welt: Blender +Z (oben) wird Roblox +Y (oben), Blender +Y wird Roblox Z, Blender +X bleibt Roblox X. Deshalb steht ein Baum im Blender-Skript in Z-Richtung aufrecht - und kommt aufrecht in Roblox an. Was du NICHT tust: im Skript auf Y hochbauen ("weil Roblox Y oben hat"), Achsen selbst per Rotation/Rotation_Euler drehen, den Export mit eigenen forward_axis/up_axis-Parametern aufrufen oder Einheiten umrechnen (cm/feet/Inches). Der Runner erzeugt OBJ UND die Upload-Datei (FBX, sonst GLB) aus DERSELBEN Szene und DERSELBEN Mitte - beide Wege zeigen also in dieselbe Richtung, und mesh_status nennt die gemessene Groesse bereits in Studs (X/Y/Z). Wenn die Messung in Roblox passt, passt auch das Mesh.'
                orientationReading = 'So liest du die Messung: size = { x, y, z } ist IMMER die Roblox-Welt (x = Breite, y = Hoehe/oben, z = Tiefe). Ein Stamm, der im Skript in Blender-Z gebaut ist, MUSS hier ein grosses y zeigen. Zeigt die Messung die Hoehe stattdessen auf z, dann steht der Bau im Skript auf der Seite (Blender-Y als Hoehe) - drehe den BAU im Skript um, nicht den Export. Genau diesen Widerspruch hat der Owner live gesehen ("Stamm 7,96 Studs entlang Z statt Y") - NICHT durch Raten am Export reparieren, sondern indem das Skript in Blender-Z hochbaut.'
                workflow = '1 blender_status lesen (Bereitschaft + Zustand). 2 build_mesh_model mit EINEM Blender-Skript fuer das ganze Modell aufrufen (weitere Slots nur nach ONE_MODEL_ONE_MESH) -> sofort jobId (Blender laeuft im Hintergrund, KEIN synchrones Warten). 3 mesh_status pollen, bis state measured ist; die Antwort nennt je Slot Dreiecke + Groesse in Studs UND die Upload-Datei (uploadPath, FBX oder GLB). 4 Die Bridge legt die viereckigen MeshPart-Platzhalter selbst an. 5 DU laedst hoch: upload_asset { slotKey } -> Roblox-Open-Cloud-API -> die Antwort nennt die ECHTE assetId. 6 mesh_apply_asset { slots = [ { key, assetId } ] } setzt die Geometrie ein (applyPath = modelMeshId bei einem Roblox-Modell). 7 Erst dann model_audit + report_done.'
                scriptContract = 'Ein Slot = ein Blender-Skript = EIN MeshPart. Das Skript ist normaler Code mit bpy (bmesh, math, mathutils, random erlaubt) und baut NUR Geometrie: 1 Blender-Einheit = 1 Stud, Z ist im Skript OBEN (siehe axesAndUnits), die bbox-Mitte am Ursprung setzt der Runner automatisch, Modifier werden beim Export angewandt. Der Runner der Bridge macht Szene, Export, Zentrierung und Messung - bpy.ops.wm.*, Export, Datei-, Netzwerk- und Systemzugriff sind im Skript gesperrt (die Bridge lehnt solche Skripte vor dem Start ab).'
                budget = 'Roblox nimmt pro Mesh hoechstens rund 10.000 Dreiecke an (Datei max. 20 MB). Die Bridge MISST die OBJ-Datei selbst und lehnt einen Slot ueber der Grenze mit state rejected ab - dann weniger Unterteilungen, Decimate/Remesh oder - wenn es nicht anders geht - nach Koerperteilen splitten (Grund 3 der Regel oben). Ziel: unter 8.000 Dreiecken je Slot.'
                userStep = 'Der Upload ist seit 7.5.0 KEIN Menschen-Schritt mehr: die Bridge laedt das FBX/GLB ueber die offizielle Roblox-Open-Cloud-Assets-API selbst hoch (upload_asset) und nennt dir die Asset-Id. Was der Nutzer genau EINMAL machen muss, ist den Schluessel hinterlegen - steht er noch nicht in den Einstellungen (Abschnitt ROBLOX OPEN CLOUD API-KEY), antwortet upload_asset mit OPENCLOUD_KEY_MISSING; dann sagst du ihm den Satz aus userMessage WORTLICH: kurz auf das Zahnrad (Einstellungen), dort das aufklappbare Tutorial machen, Schluessel mit den Rechten assets + read + write erstellen und speichern. NICHT behaupten, das Modell sei fertig, solange ein Platzhalter noch viereckig ist.'
                uploadFormats = 'Roblox Open Cloud nimmt FUER MESHES NUR FBX, GLB oder GLTF an - NIEMALS das gemessene OBJ. Die Bridge erzeugt die Upload-Datei deshalb selbst (uploadPath in mesh_status, normalerweise .fbx, sonst .glb). Fehlt sie (uploadReady = false, uploadError gesetzt), ist dieses Mesh nicht hochladbar: Slot neu bauen statt das OBJ zu schicken - das lehnt Roblox mit UNSUPPORTED_FORMAT ab. Bilder gehen als PNG, JPG, JPEG, BMP oder TGA (max. 20 MB, unter 8000x8000 Pixel).'
                evidence = 'Beweis statt Behauptung: Dreieckszahl, Groesse und Dateigroesse kommen aus der Messung der Bridge und stehen in mesh_status und im Bau-Register. Die Asset-Id kommt von ROBLOX selbst (aus der Operation des Uploads) - keine Schaetzung, kein Raten. Nach dem Einsetzen meldet mesh_apply_asset je Slot die zurueckgelesene MeshId und den Weg (applyPath). Ein Mesh ist im Place messtechnisch eine Blackbox - Messung, zurueckgelesene Id und der Sichttest sind der Beleg.'
                failure = 'Schlaegt Blender fehl (nicht installiert, Faehigkeitsprobe rot, Exit ungleich 0, Zeitlimit), sagt die Bridge das mit Code und Protokollzeile; dann bleibt der Polygon-Weg. Schlaegt der UPLOAD fehl, kommen Status, Code und die Original-Antwort von Roblox unveraendert zu dir (429 Rate Limit, 401/403 Schluessel, 400 Datei, 5xx Stoerung) - melde sie dem Nutzer ehrlich und erfinde keine Asset-Id. Nie ein leeres oder unbemessenes Modell als fertig melden.'
                filePathIsMandatory = 'PFLICHT BEI JEDEM GESCHEITERTEN UPLOAD (Owner-Wunsch 7.5.1): Nenne dem Nutzer IMMER den exakten Dateipfad der Datei, die hochgeladen werden sollte - woertlich, in einer eigenen Zeile, kopierbar. Die Antwort von upload_asset traegt ihn als filePath (und sourcePath); mesh_status nennt ihn je Slot als uploadPath. Beispielsatz: "Die Datei liegt hier: C:\\Users\\<du>\\AppData\\Local\\ArenaRobloxBridge\\meshes\\<jobId>\\stamm.fbx - damit kannst du sie selbst in Roblox hochladen (Toolbox -> Import)." Auch wenn der Pfad schon in der Antwort steht: sag ihn im Chat, damit der Nutzer ihn nicht suchen muss.'
            }
            cloudUploadRules = @{
                title = 'Cloud-Upload (7.6.2) - Modelle, Bilder, Audio, Animationen und Videos'
                whenThisApplies = 'Immer, wenn ein Mesh (aus Blender) oder ein Bild (z. B. von dir selbst erzeugt) nach Roblox muss. Du brauchst dafuer KEINEN Menschen mehr - nur den einmalig hinterlegten Open-Cloud-Schluessel des Nutzers. Der Nutzer laedt nichts mehr von Hand hoch, es gibt kein Mesh-Fenster mehr.'
                workflow = '1 Mesh: build_mesh_model -> mesh_status (uploadPath/uploadReady) -> upload_asset { slotKey } -> assetId -> mesh_apply_asset { slots = [ { key, assetId } ] } -> model_audit. Bild: upload_asset { fileName = "name.png", contentBase64 = "<Base64>" } -> assetId -> selbst einsetzen (Decal.Texture, Texture.Texture, ImageLabel.Image, MeshPart.TextureID) -> auditieren.'
                meshUpload = 'Roblox Open Cloud legt ein hochgeladenes FBX/GLB als MODELL an (nicht als nackte Mesh-Id). Die Bridge kommt damit zurecht: mesh_apply_asset laedt das Modell, nimmt die MeshId aus dem MeshPart darin und setzt sie in den bestehenden Platzhalter ein (applyPath = modelMeshId). Alternativ fuegst du das komplette Modell mit insert_asset ein und positionierst es selbst.'
                imageUpload = 'Bilder schickst du als contentBase64 MIT fileName (Endung!) - dann braucht es keine Datei auf dem Rechner des Nutzers. Roblox-Grenzen: 20 MB je Datei und unter 8000x8000 Pixel. Ergebnis ist eine Asset-Id: setze sie selbst ein (Decal.Texture = "rbxassetid://<id>", ImageLabel.Image, MeshPart.TextureID).'
                limits = 'Roblox-Grenzen je Upload: 20 MB, ein Asset je Aufruf, Bilder unter 8000x8000 Pixel, Formate FBX/GLB/GLTF/RBXM/RBXMX (Modelle/Animationen), PNG/JPG/JPEG/BMP/TGA (Bilder), MP3/OGG/WAV/FLAC (Audio), MP4/MOV (Video). Bridge-Limit 20 MiB; Roblox-Konto-/Dauer-/Kontingentlimits gelten zusätzlich. Ein Rate Limit (429) ist ein echter Roblox-Zustand: sage dem Nutzer, dass Roblox gerade drosselt, und versuche es spaeter erneut - nicht sofort wieder.'
                missingKey = 'Fehlt der Schluessel, bleibt das Werkzeug ganz normal verfuegbar und antwortet erst beim Aufruf mit OPENCLOUD_KEY_MISSING. Die Antwort enthaelt userMessage: sage diesen Satz dem Nutzer WORTLICH auf Deutsch. Danach wartest du - du erfindest keine Asset-Id und behauptest keinen Erfolg.'
                honesty = 'Die Asset-Id ist nur dann echt, wenn Roblox sie genannt hat. Steht die Operation noch auf pending, rufst du upload_asset { operationId } erneut auf (kein enger Loop). Fehlertexte von Roblox gehoren unverfaelscht an den Nutzer - die Bridge versteckt und beschoenigt nichts.'
            }
            openCloudRules = @{
                title = 'Open Cloud 7.6.2 - feste Nutzerfreigabe, einzelne Rechte, kein Key-Export'
                workflow = 'open_cloud list -> describe -> call. 41 freigegebene Einzelrechte, 172 dokumentierte Endpunkte. Die Liste ist eine feste Allowlist, keine Weiterleitung beliebiger URLs. describe liefert Parameter, Request-Schemas und Roblox-Quellen. Bei Schreiben reale Nutzerdaten und mögliche Kosten beachten; nichts außerhalb des Nutzerauftrags ändern.'
                policy = 'Nur die ausdrücklich erlaubten Rechte; Sperren sind auch bei einem allmächtigen Key wirksam. Lesen braucht nicht pauschal Schreiben. Analytics write hat derzeit keinen dokumentierten Endpunkt. Keine Subscriptions, allgemeinen Thumbnails, Ban-Schreibzugriffe, Secrets, Messaging, Memory Stores, Luau-Cloud-Sessions, Gruppen-/Teamverwaltung, Werbung oder kostenpflichtige Badge-Erstellung.'
                key = 'Key bleibt DPAPI-verschlüsselt lokal. Kein Key in Tool-Argumenten, Antworten oder Logs. Redirects sind ausgeschaltet. Fehlgeschlagene Prüfung blockiert Aktionen. Berechtigungen neu prüfen aktualisiert den Cache; regulär 90 Sekunden.'
                targets = 'Die Komfort-Tools creator_dashboard und datastore bleiben auf die aktive Sitzung begrenzt. open_cloud erlaubt explizite dokumentierte Ressourcen-IDs für den vollständigen freigegebenen Umfang; nutze nur echte IDs für den Nutzerauftrag. Roblox entscheidet über die Ressourcenfreigabe. Jede schreibende Cloud-Aktion prüft zusätzlich den Read-only-Modus der Sitzung.'
            }
            creatorDashboardRules = @{
                title = 'Creator Dashboard + DataStores - convenience subset; full allowed API via open_cloud'
                setting = 'The old local opt-in switch is REMOVED. All cloud tools obey the fixed user allowlist AND the exact API-key permissions; when the user saves a key, Arena shows a permission window (Introspect) before anything is stored. A missing scope answers OPENCLOUD_SCOPE_MISSING with the exact scope name - tell it to the user verbatim so he can recreate the key with that permission.'
                target = 'Take universeId from gameId and placeId from the active connected Studio session. Do not accept a caller-supplied Universe/Place ID, do not use the Alle-Places token as a wildcard, and require positive IDs from an already-published Place.'
                supported = 'Official documented Open Cloud endpoints only: GET/PATCH Universe /cloud/v2/universes/{id}; GET/PATCH Place /cloud/v2/universes/{id}/places/{placeId}; list/get/create/update game passes; list/get/create/update developer products. Metadata edits are limited to displayName and description. Product create/update can send PNG/JPEG icons as multipart imageFile. The datastore tool adds the stable /cloud/v2/universes/{id}/data-stores/... APIs: list stores, list/read/create/update/increment/delete entries, list entry revisions.'
                permissions = 'For updates: universe:write and universe.place:write. For game passes: game-pass:read + game-pass:write. For developer products: developer-product:read + developer-product:write. For data stores: universe-datastores.control:list, universe-datastores.objects:list/read/create/update/delete, universe-datastores.versions:list. Existing mesh/image uploads still require their separate assets permissions. Roblox role/resource access must also allow the selected active game.'
                safety = 'Every mutating action independently rejects accessMode=readonly before network I/O. An HTTP 409 is reported without retry (Place updates can conflict with active Team Create); 429 and all transport/API errors are explicit. Never retry automatically. Data-store writes touch real player data: read before you change, and tell the user exactly which entry you changed.'
                notSupported = 'These convenience tools do not implement every API. Use open_cloud list/describe/call for the complete approved catalog, including place publishing. Never claim cookie-only access or undocumented actions. Do not claim changes succeeded unless Roblox returned a successful response.'
            }
            organicBuildRules = @{
                title = 'Organic Build Engine 1.1 (Version 7.5.8) - typed creature volumes, physical face, bilateral anatomy, measured before done'
