    # Dieselbe Sammlung wird im Hauptprogramm UND in jedem Handler-/
    # Worker-Runspace geladen (wie $Shared.BlenderToolsText und
    # $Shared.MeshToolkitText). Deshalb: KEIN $script:-Zustand, alles
    # kommt ueber $Shared oder ueber Parameter herein.
    #
    # Was hier passiert:
    #   * der Open-Cloud-Schluessel wird verschluesselt abgelegt (DPAPI,
    #     CurrentUser) und NUR im Speicher der Bridge entschluesselt,
    #   * Meshes (FBX/GLB) und Bilder (PNG/JPG/BMP/TGA) werden ueber die
    #     offizielle Assets-API hochgeladen (POST /assets/v1/assets),
    #   * die asynchrone Operation wird gepollt, bis Roblox die ASSET-ID
    #     nennt - genau diese ID bekommt der Agent zurueck, damit er das
    #     Mesh oder Bild selbst in den Place setzen kann.
    # ----------------------------------------------------------------

    function Get-OpenCloudKeyPath {
        param($Shared)
        $path = ''
        try { if ($Shared) { $path = [string]$Shared.OpenCloudKeyFile } } catch {}
        if ([string]::IsNullOrWhiteSpace($path)) {
            try { $path = [string]$script:OpenCloudKeyFile } catch {}
        }
        if ([string]::IsNullOrWhiteSpace($path) -and $Shared -and $Shared.AppDataRoot) {
            $path = Join-Path ([string]$Shared.AppDataRoot) 'opencloud.key'
        }
        return $path
    }

    function Protect-OpenCloudSecret {
        param([string]$Text)
        if ([string]::IsNullOrWhiteSpace($Text)) { return '' }
        try {
            try { Add-Type -AssemblyName System.Security -ErrorAction Stop } catch {}
            $bytes = [System.Text.Encoding]::UTF8.GetBytes($Text)
            $enc = [System.Security.Cryptography.ProtectedData]::Protect($bytes, $null, [System.Security.Cryptography.DataProtectionScope]::CurrentUser)
            return ('dpapi:' + [Convert]::ToBase64String($enc))
        } catch {
            # Kein DPAPI verfügbar (z. B. Server-Kontext): dann Klartext, aber
            # sichtbar markiert, damit niemand Sicherheit vortaeuscht.
            return ('plain:' + $Text)
        }
    }

    function Unprotect-OpenCloudSecret {
        param([string]$Data)
        if ([string]::IsNullOrWhiteSpace($Data)) { return '' }
        if ($Data.StartsWith('dpapi:')) {
            try {
                try { Add-Type -AssemblyName System.Security -ErrorAction Stop } catch {}
                $enc = [Convert]::FromBase64String($Data.Substring(6))
                $bytes = [System.Security.Cryptography.ProtectedData]::Unprotect($enc, $null, [System.Security.Cryptography.DataProtectionScope]::CurrentUser)
                return [System.Text.Encoding]::UTF8.GetString($bytes)
            } catch { return '' }
        }
        if ($Data.StartsWith('plain:')) { return $Data.Substring(6) }
        return ''
    }

    function Get-OpenCloudKey {
        param($Shared)
        # Der entschluesselte Schluessel liegt NUR im Speicher der Bridge
        # ($Shared.OpenCloudKeyCache). Nie in settings.json, nie im Log.
        try {
            $cached = [string]$Shared.OpenCloudKeyCache
            if (-not [string]::IsNullOrWhiteSpace($cached)) { return $cached }
        } catch {}
        $path = Get-OpenCloudKeyPath $Shared
        if ([string]::IsNullOrWhiteSpace($path) -or -not (Test-Path -LiteralPath $path)) { return '' }
        $key = ''
        try {
            $raw = [System.IO.File]::ReadAllText($path, (New-Object System.Text.UTF8Encoding($false)))
            $key = Unprotect-OpenCloudSecret ([string]$raw).Trim()
        } catch {}
        if (-not [string]::IsNullOrWhiteSpace($key)) {
            try { $Shared.OpenCloudKeyCache = $key } catch {}
        }
        return $key
    }

    function Set-OpenCloudKey {
        param($Shared, [string]$Key)
        $clean = ([string]$Key).Trim()
        $path = Get-OpenCloudKeyPath $Shared
        if ([string]::IsNullOrWhiteSpace($path)) { return $false }
        if ([string]::IsNullOrWhiteSpace($clean)) { return $false }
        try {
            $folder = [System.IO.Path]::GetDirectoryName($path)
            if (-not [string]::IsNullOrWhiteSpace($folder) -and -not (Test-Path -LiteralPath $folder)) {
                [void](New-Item -ItemType Directory -Path $folder -Force)
            }
            $protected = Protect-OpenCloudSecret $clean
            [System.IO.File]::WriteAllText($path, $protected, (New-Object System.Text.UTF8Encoding($false)))
            $Shared.OpenCloudKeyCache = $clean
            try { $Shared.OpenCloudIntrospectCache = $null } catch {}
            return $true
        } catch {
            try { Write-BridgeLog ('Open Cloud: Schluessel konnte nicht gespeichert werden: ' + $_.Exception.Message) } catch {}
            return $false
        }
    }

    function Remove-OpenCloudKey {
        param($Shared)
        try { $Shared.OpenCloudKeyCache = '' } catch {}
        try { $Shared.OpenCloudIntrospectCache = $null } catch {}
        $path = Get-OpenCloudKeyPath $Shared
        try {
            if (-not [string]::IsNullOrWhiteSpace($path) -and (Test-Path -LiteralPath $path)) {
                [System.IO.File]::Delete($path)
            }
            return $true
        } catch { return $false }
    }

    function Get-OpenCloudConfig {
        param($Shared)
        $key = Get-OpenCloudKey $Shared
        $creatorId = ''
        $creatorKind = 'user'
        $creatorName = ''
        $savedAt = ''
        $hint = ''
        try { $creatorId = [string]$Shared.BridgeSettings.openCloudCreatorId } catch {}
        try { if (-not [string]::IsNullOrWhiteSpace([string]$Shared.BridgeSettings.openCloudCreatorKind)) { $creatorKind = [string]$Shared.BridgeSettings.openCloudCreatorKind } } catch {}
        try { $creatorName = [string]$Shared.BridgeSettings.openCloudCreatorName } catch {}
        try { $savedAt = [string]$Shared.BridgeSettings.openCloudSavedAt } catch {}
        try { $hint = [string]$Shared.BridgeSettings.openCloudKeyHint } catch {}
        return @{
            hasKey      = (-not [string]::IsNullOrWhiteSpace($key))
            key         = $key
            creatorId   = $creatorId
            creatorKind = $creatorKind
            creatorName = $creatorName
            savedAt     = $savedAt
            keyHint     = $hint
        }
    }

    function Test-OpenCloudKeyHasExpiration {
        # Version 7.6.2: JEDES Ablaufdatum ist ein Nein. Die Bridge benutzt
        # den Key dann gar nicht - der Nutzer muss No Expiration setzen.
        param($Info)
        if ($null -eq $Info) { return $false }
        try { if ([bool]$Info.hasExpiration -eq $true) { return $true } } catch {}
        try { if ([bool]$Info.expired -eq $true) { return $true } } catch {}
        $expiry = ''
        try { $expiry = ([string]$Info.expirationTimeUtc).Trim() } catch {}
        if ([string]::IsNullOrWhiteSpace($expiry)) { return $false }
        $lower = $expiry.ToLowerInvariant()
        if ($lower -eq 'null' -or $lower -eq 'none' -or $lower.StartsWith('0001-01-01')) { return $false }
        return $true
    }

    function Set-OpenCloudIntrospectCache {
        param($Shared, $Info)
        if ($null -eq $Shared -or $null -eq $Info) { return }
        try {
            $copy = @{}
            foreach ($entry in @($Info.GetEnumerator())) { $copy[$entry.Key] = $entry.Value }
            $copy.cachedAtUtc = [DateTime]::UtcNow.ToString('o')
            $Shared.OpenCloudIntrospectCache = $copy
        } catch {
            try { $Shared.OpenCloudIntrospectCache = $Info } catch {}
        }
    }

    function Get-OpenCloudIntrospectCached {
        param($Shared, [int]$MaxAgeSeconds = 90)
        try {
            $cached = $Shared.OpenCloudIntrospectCache
            if ($null -eq $cached) { return $null }
            $stamp = ''
            try { $stamp = [string]$cached.cachedAtUtc } catch {}
            if ([string]::IsNullOrWhiteSpace($stamp)) { return $null }
            $at = [DateTime]::Parse($stamp, $null, [System.Globalization.DateTimeStyles]::RoundtripKind)
            if (([DateTime]::UtcNow - $at).TotalSeconds -gt $MaxAgeSeconds) { return $null }
            return $cached
        } catch { return $null }
    }

    function Test-OpenCloudPermission {
        param($Info, [string]$Permission)
        # Exact permission only: read != list, asset-permissions != asset,
        # analytics.alert != analytics. No wildcard/family inference.
        $wanted = $Permission.Trim().ToLowerInvariant()
        $catalog = Get-OpenCloudCatalog
        if ($null -eq $catalog.permissions.PSObject.Properties[$wanted]) { return $false }
        foreach ($scope in @($Info.scopes)) {
            if ($null -eq $scope) { continue }
            $name = ([string]$scope.name).Trim().ToLowerInvariant()
            if ($name.Contains(':')) {
                if ($name -ceq $wanted) { return $true }
            } else {
                foreach ($operation in @($scope.operations)) {
                    if (($name + ':' + ([string]$operation).Trim().ToLowerInvariant()) -ceq $wanted) { return $true }
                }
            }
        }
        return $false
    }

    function Assert-OpenCloudToolAccess {
        param($Shared, [string]$Family = '', [string]$What = '', [string[]]$RequiredScopes = @())
        $config = Get-OpenCloudConfig $Shared
        if (-not $config.hasKey) {
            return @{ ok = $false; code = 'OPENCLOUD_KEY_MISSING'; error = 'Kein Open-Cloud-Key gespeichert.'; userMessage = 'Bitte in den Bridge-Einstellungen unter Roblox Open Cloud API-Key das Tutorial öffnen und deinen Key ohne Ablaufdatum speichern. Den Key niemals an Arena senden.' }
        }
        $info = Get-OpenCloudIntrospectCached $Shared
        if ($null -eq $info) {
            $info = Invoke-OpenCloudIntrospect $Shared
            if ($info.ok -eq $true) { Set-OpenCloudIntrospectCache $Shared $info }
        }
        # Failed introspection must NEVER fall through to an authenticated call.
        if ($null -eq $info -or $info.ok -ne $true) {
            return @{ ok = $false; code = 'OPENCLOUD_CHECK_FAILED'; error = 'Der Key konnte nicht geprüft werden. Es wurde keine Aktion gesendet.'; userMessage = 'Bitte die Berechtigungsprüfung in der Bridge erneut ausführen.' }
        }
        if ($info.enabled -ne $true) { return @{ ok = $false; code = 'OPENCLOUD_KEY_REJECTED'; error = 'Der Key ist deaktiviert.' } }
        if (Test-OpenCloudKeyHasExpiration $info) {
            return @{ ok = $false; code = 'OPENCLOUD_KEY_HAS_EXPIRATION'; error = 'Die Bridge benutzt keine Keys mit Ablaufdatum.'; userMessage = 'Bitte einen Key mit Expiration = No Expiration in der Bridge speichern.' }
        }
        foreach ($permission in $RequiredScopes) {
            if ($null -eq (Get-OpenCloudCatalog).permissions.PSObject.Properties[$permission]) {
                return @{ ok = $false; code = 'OPENCLOUD_POLICY_DENIED'; error = 'Diese Berechtigung ist nicht für Arena freigegeben.' }
            }
            if (-not (Test-OpenCloudPermission $info $permission)) {
                return @{ ok = $false; code = 'OPENCLOUD_SCOPE_INCOMPLETE'; requiredScopes = $RequiredScopes; missingScope = $permission; error = ('Dem Key fehlt ' + $permission + '.'); userMessage = ('Bitte ' + $permission + ' am Key freigeben und die Berechtigungen erneut prüfen.'); howToFix = 'Den userMessage-Satz WORTLICH weitergeben. Keine zusätzlichen Rechte verlangen.' }
            }
        }
        return @{ ok = $true; code = 'OPENCLOUD_KEY_READY' }
    }

    function ConvertTo-OpenCloudMap {
        param($Value)
        $map = @{}
        if ($null -eq $Value) { return $map }
        if ($Value -is [System.Collections.IDictionary]) {
            foreach ($key in $Value.Keys) { $map[[string]$key] = $Value[$key] }
        } else {
            foreach ($property in $Value.PSObject.Properties) { $map[$property.Name] = $property.Value }
        }
        return $map
    }

    function Protect-OpenCloudTransportResult {
        param($Result, [string]$Key)
        foreach ($field in @('body','error','clientError')) {
            $Result[$field] = Protect-OpenCloudResponse -Text ([string]$Result[$field]) -Key $Key
        }
        return $Result
    }

    function Protect-OpenCloudResponse {
        param([string]$Text, [string]$Key)
        if (-not [string]::IsNullOrEmpty($Key)) {
            $Text = $Text.Replace($Key, '[REDACTED]')
            $Text = $Text.Replace([Uri]::EscapeDataString($Key), '[REDACTED]')
            $quoted = ConvertTo-Json -InputObject $Key -Compress
            if ($quoted.Length -gt 2) { $Text = $Text.Replace($quoted.Substring(1, $quoted.Length - 2), '[REDACTED]') }
        }
        return $Text
    }

    function New-OpenCloudCatalogBody {
        param($Operation, $Arguments)
        $bodyArg = Get-OpenCloudArgumentValue $Arguments 'body'
        $files = @($Arguments.files | Where-Object { $null -ne $_ })
        $forms = ConvertTo-OpenCloudMap $Arguments.form
        $contentType = [string]$Arguments.contentType
        $content = ConvertTo-OpenCloudMap $Operation.requestBody.content
        $limit = [Math]::Min(20971520, [int]$Operation.sizeLimit)
        if ($limit -le 0) { $limit = 20971520 }
        $raw = [string]$Arguments.contentBase64
        if ($raw.Length -gt 0) {
            if ($raw.Length -gt 28000000 -or $files.Count -gt 0 -or $forms.Count -gt 0 -or $bodyArg.found) { throw 'Binärdaten dürfen nicht mit JSON oder Formularfeldern vermischt werden.' }
            if ($contentType -notin @('application/xml','application/octet-stream','image/png','image/jpeg','image/bmp')) { throw 'Für Binärdaten einen unterstützten contentType angeben.' }
            if ($content.Count -gt 0 -and -not $content.ContainsKey($contentType)) { throw 'Dieser Endpunkt akzeptiert diesen Binärtyp nicht.' }
            $bytes = [Convert]::FromBase64String($raw)
            if ($bytes.Length -gt $limit) { throw 'Die Datei überschreitet das Upload-Limit.' }
            return @{ bytes = $bytes; contentType = $contentType }
        }
        if ($content.ContainsKey('multipart/form-data') -or $files.Count -gt 0 -or $forms.Count -gt 0) {
            if ($content.Count -gt 0 -and -not $content.ContainsKey('multipart/form-data')) { throw 'Dieser Endpunkt akzeptiert kein Multipart-Formular.' }
            if ($bodyArg.found) { throw 'Multipart verwendet form und files, nicht body.' }
            $boundary = 'ArenaCloud' + [guid]::NewGuid().ToString('N')
            $stream = [System.IO.MemoryStream]::new()
            try {
                foreach ($field in $forms.Keys) {
                    if ($field -notmatch '^[a-zA-Z0-9_.-]+$') { throw 'Ungültiger Formularfeldname.' }
                    $value = $forms[$field]
                    if ($value -isnot [string]) { $value = ConvertTo-Json -InputObject $value -Depth 60 -Compress }
                    $part = [Text.Encoding]::UTF8.GetBytes("--$boundary`r`nContent-Disposition: form-data; name=`"$field`"`r`n`r`n$value`r`n")
                    $stream.Write($part, 0, $part.Length)
                }
                foreach ($file in $files) {
                    $field = [string]$file.field
                    $name = [string]$file.fileName
                    $mime = [string]$file.contentType
                    if ($field -notmatch '^[a-zA-Z0-9_.\[\]-]+$' -or $name -notmatch '^[a-zA-Z0-9_. -]+$' -or $mime -notmatch '^[a-zA-Z0-9.+-]+/[a-zA-Z0-9.+-]+$') { throw 'Ungültiges Upload-Feld, Dateiname oder MIME-Typ.' }
                    if (([string]$file.contentBase64).Length -gt 28000000) { throw 'Datei zu groß.' }
                    $bytes = [Convert]::FromBase64String([string]$file.contentBase64)
                    if ($bytes.Length -gt $limit) { throw 'Datei zu groß.' }
                    $part = [Text.Encoding]::UTF8.GetBytes("--$boundary`r`nContent-Disposition: form-data; name=`"$field`"; filename=`"$name`"`r`nContent-Type: $mime`r`n`r`n")
                    $stream.Write($part, 0, $part.Length)
                    $stream.Write($bytes, 0, $bytes.Length)
                    $stream.WriteByte(13); $stream.WriteByte(10)
                    if ($stream.Length -gt 67108864) { throw 'Formular zu groß (maximal 64 MiB).' }
                }
                $part = [Text.Encoding]::UTF8.GetBytes("--$boundary--`r`n")
                $stream.Write($part, 0, $part.Length)
                return @{ bytes = $stream.ToArray(); contentType = ('multipart/form-data; boundary=' + $boundary) }
            } finally { $stream.Dispose() }
        }
        if ($bodyArg.found) {
            if (-not $content.ContainsKey('application/json')) { throw 'Dieser Endpunkt dokumentiert keinen JSON-Body.' }
            return @{ bytes = [Text.Encoding]::UTF8.GetBytes((ConvertTo-Json -InputObject $bodyArg.value -Depth 60 -Compress)); contentType = 'application/json' }
        }
        if ($Operation.requestBody.required -eq $true) { throw 'Der erforderliche Request-Body fehlt; zuerst describe aufrufen.' }
        return @{ bytes = $null; contentType = '' }
    }

    function Invoke-OpenCloudCatalogTool {
        param($Shared, [string]$SessionId, $Arguments)
        $catalog = Get-OpenCloudCatalog
        $action = ([string]$Arguments.action).ToLowerInvariant()
        if ([string]::IsNullOrWhiteSpace($action)) { $action = 'list' }
        if ($action -eq 'list') {
            $scope = [string]$Arguments.scope
            $items = @($catalog.operations | Where-Object { [string]::IsNullOrWhiteSpace($scope) -or @($_.policyScopes) -contains $scope } | ForEach-Object {
                @{ id = $_.id; summary = $_.summary; scopes = $_.scopes; readOnly = $_.readOnly }
            })
            return @{ ok = $true; result = @{ operations = $items; permissions = $catalog.permissions; note = 'Nur freigegebene Funktionen. describe liefert Parameter und Schemas. Ein gelistetes Tool beweist keine Rechte am konkreten Ziel; Roblox prüft Ressourcen und Rollen.' } }
        }
        $operation = @($catalog.operations | Where-Object { $_.id -ceq [string]$Arguments.operation })
        if ($operation.Count -ne 1) { return @{ ok = $false; code = 'OPENCLOUD_POLICY_DENIED'; error = 'Unbekannte oder gesperrte Operation. Zuerst open_cloud action=list verwenden.' } }
        $op = $operation[0]
        if ($action -eq 'describe') { return @{ ok = $true; result = $op } }
        if ($action -ne 'call') { return @{ ok = $false; code = 'BAD_ARGS'; error = 'action muss list, describe oder call sein.' } }
        # Unknown auth state is not write authorization. Existing session token
        # authentication happens in the server dispatcher before this handler.
        $accessMode = 'readonly'
        try { [void]$Shared.AccessModes.TryGetValue($SessionId, [ref]$accessMode) } catch {}
        if ($op.readOnly -ne $true -and $accessMode -ne 'readwrite') { return @{ ok = $false; code = 'READONLY_TOKEN'; error = 'Diese Sitzung darf keine Cloud-Daten ändern.' } }
        $gate = Assert-OpenCloudToolAccess -Shared $Shared -RequiredScopes @($op.scopes) -What ([string]$op.id)
        if ($gate.ok -ne $true) { return $gate }
        try {
            # No caller URL, HTTP method or authentication/header override.
            foreach ($forbidden in @('url','host','method','key','apiKey','authorization','cookie','filePath')) {
                if ((Get-OpenCloudArgumentValue $Arguments $forbidden).found) { throw ('Nicht erlaubtes Argument: ' + $forbidden) }
            }
            $pathArgs = ConvertTo-OpenCloudMap $Arguments.path
            $queryArgs = ConvertTo-OpenCloudMap $Arguments.query
            $headerArgs = ConvertTo-OpenCloudMap $Arguments.headers
            $maps = @{ path = $pathArgs; query = $queryArgs; header = $headerArgs }
            $path = [string]$op.path
            $query = New-Object System.Collections.Generic.List[string]
            $headers = @{}
            foreach ($location in @('path','query','header')) {
                foreach ($name in $maps[$location].Keys) {
                    if (-not @($op.parameters | Where-Object { $_.in -ceq $location -and $_.name -ceq $name }).Count) { throw ('Undokumentierter Parameter: ' + $name) }
                }
            }
            foreach ($parameter in @($op.parameters)) {
                $location = [string]$parameter.in
                $name = [string]$parameter.name
                if (-not $maps.ContainsKey($location)) { continue }
                $map = $maps[$location]
                if (-not $map.ContainsKey($name)) {
                    if ($parameter.required -eq $true) { throw ('Pflichtparameter fehlt: ' + $name) }
                    continue
                }
                $value = [string]$map[$name]
                if ($map[$name] -is [array]) { $value = $map[$name] -join ',' }
                if ($location -eq 'path') {
                    if ([string]::IsNullOrWhiteSpace($value) -or $value -eq '.' -or $value -eq '..' -or $value -match '[/\\%?#\x00-\x1f]') { throw ('Unsicheres Pfadsegment: ' + $name) }
                    $path = $path.Replace(('{' + $name + '}'), [Uri]::EscapeDataString($value))
                } elseif ($location -eq 'query') {
                    $values = @($value)
                    if ($map[$name] -is [array] -and $parameter.explode -ne $false) { $values = @($map[$name]) }
                    foreach ($queryValue in $values) {
                        $query.Add(([Uri]::EscapeDataString($name) + '=' + [Uri]::EscapeDataString([string]$queryValue)))
                    }
                } else {
                    if ($name -match '^(?i:authorization|cookie|host|x-api-key|content-type|content-length|connection|transfer-encoding)$' -or $value -match '[\r\n]') { throw 'Nicht erlaubter Header.' }
                    $headers[$name] = $value
                }
            }
            if ($path.Contains('{') -or -not $path.StartsWith('/')) { throw 'Unvollständiger API-Pfad.' }
            $url = 'https://apis.roblox.com' + $path
            if ($query.Count -gt 0) { $url += '?' + ($query.ToArray() -join '&') }
            $payload = New-OpenCloudCatalogBody -Operation $op -Arguments $Arguments
        } catch { return @{ ok = $false; code = 'BAD_ARGS'; error = $_.Exception.Message } }
        $config = Get-OpenCloudConfig $Shared
        # One send only, including mutations: no blind retry after timeouts.
        $response = Send-OpenCloudRequestFallback -Method ([string]$op.method) -Url $url -Key ([string]$config.key) -MultipartBytes $payload.bytes -MultipartContentType $payload.contentType -AdditionalHeaders $headers -TimeoutSeconds 90 -MaxResponseChars 4000000
        $body = Protect-OpenCloudResponse -Text ([string]$response.body) -Key ([string]$config.key)
        if ($response.bodyTruncated) { return @{ ok = $false; code = 'OPENCLOUD_RESPONSE_TOO_LARGE'; status = $response.status; error = 'Antwort zu groß. Abfrage eingrenzen/paginieren. Eine Schreibaktion NICHT blind wiederholen.' } }
        if ($response.status -lt 200 -or $response.status -gt 299) {
            return @{ ok = $false; code = 'OPENCLOUD_HTTP_ERROR'; status = $response.status; operation = $op.id; requiredScopes = $op.scopes; robloxResponse = $body; error = (Protect-OpenCloudResponse -Text ([string]$response.error) -Key ([string]$config.key)); note = 'Roblox entscheidet über Ressourcen, Rollen, Limits und Moderation. Bei Timeout keine Schreibaktion blind wiederholen.' }
        }
        $result = $body
        if (-not [string]::IsNullOrWhiteSpace($body)) { try { $result = ConvertFrom-Json -InputObject $body } catch {} }
        return @{ ok = $true; status = $response.status; operation = $op.id; result = $result }
    }

    function Get-OpenCloudAssetSpec {
        # Dateiendung -> assetType + Content-Type. Genau die Paare, die die
        # Assets-API annimmt (20 MB je Datei, Bilder unter 8000x8000).
        param([string]$Path, [string]$WantedType = '')
        $ext = ''
        try { $ext = ([System.IO.Path]::GetExtension([string]$Path)).ToLowerInvariant() } catch {}
        $map = @{
            '.fbx'  = @{ assetType = 'Model'; contentType = 'model/fbx' }
            '.glb'  = @{ assetType = 'Model'; contentType = 'model/gltf-binary' }
            '.gltf' = @{ assetType = 'Model'; contentType = 'model/gltf+json' }
            '.png'  = @{ assetType = 'Decal'; contentType = 'image/png' }
            '.jpg'  = @{ assetType = 'Decal'; contentType = 'image/jpeg' }
            '.jpeg' = @{ assetType = 'Decal'; contentType = 'image/jpeg' }
            '.bmp'  = @{ assetType = 'Decal'; contentType = 'image/bmp' }
            '.tga'  = @{ assetType = 'Decal'; contentType = 'image/tga' }
            '.mp3'  = @{ assetType = 'Audio'; contentType = 'audio/mpeg' }
            '.ogg'  = @{ assetType = 'Audio'; contentType = 'audio/ogg' }
            '.wav'  = @{ assetType = 'Audio'; contentType = 'audio/wav' }
            '.flac' = @{ assetType = 'Audio'; contentType = 'audio/flac' }
            '.rbxm' = @{ assetType = 'Model'; contentType = 'model/x-rbxm' }
            '.rbxmx'= @{ assetType = 'Model'; contentType = 'model/x-rbxm' }
            '.mp4'  = @{ assetType = 'Video'; contentType = 'video/mp4' }
            '.mov'  = @{ assetType = 'Video'; contentType = 'video/mov' }
        }
        if (-not $map.ContainsKey($ext)) {
            if ($ext -eq '.obj') {
                return @{ ok = $false; code = 'UNSUPPORTED_FORMAT'; error = 'Roblox Open Cloud nimmt KEIN OBJ an. Die Bridge baut fuer jeden Mesh-Slot zusaetzlich ein FBX (mesh_status nennt es unter uploadPath) - nimm dieses, oder baue den Slot neu.' }
            }
            return @{ ok = $false; code = 'UNSUPPORTED_FORMAT'; error = ('Die Dateiendung "' + $ext + '" kann Roblox Open Cloud nicht hochladen. Erlaubt: FBX/GLB/GLTF/RBXM/RBXMX, PNG/JPG/JPEG/BMP/TGA, MP3/OGG/WAV/FLAC, MP4/MOV. Roblox-Kontolimits gelten.') }
        }
        $spec = $map[$ext]
        $assetType = [string]$spec.assetType
        $wanted = ([string]$WantedType).Trim()
        if (-not [string]::IsNullOrWhiteSpace($wanted)) {
            $lower = $wanted.ToLowerInvariant()
            if ($lower -eq 'image' -and $assetType -eq 'Decal') { $assetType = 'Image' }
            elseif ($lower -eq 'decal' -and $assetType -eq 'Decal') { $assetType = 'Decal' }
            elseif ($lower -eq 'animation' -and $ext -in @('.rbxm','.rbxmx')) { $assetType = 'Animation' }
            elseif ($lower -eq $assetType.ToLowerInvariant()) { }
            elseif ($assetType -eq 'Model' -and $lower -in @('model','mesh','meshpart')) { $assetType = 'Model' }
            else {
                return @{ ok = $false; code = 'BAD_ARGS'; error = ('assetType "' + $wanted + '" passt nicht zur Datei. Typ muss zur Datei passen: Model, Animation, Audio, Video, Decal oder Image.') }
            }
        }
        return @{ ok = $true; assetType = $assetType; contentType = [string]$spec.contentType; extension = $ext }
    }

    # ------------------------------------------------------------------
    # Version 7.5.2 - LIVE-FIX "Der HTTP-Client konnte nicht erzeugt werden."
    #
    # WAS IN 7.5.0 PASSIERT IST (Live-Befund des Owners, 07.10.2026):
    # upload_asset UND "Pruefen" antworteten nach ~0,6 s mit
    # OPENCLOUD_UNREACHABLE / "Der HTTP-Client konnte nicht erzeugt werden."
    # - es ging also NIE ein Paket an Roblox. Ursache: Windows PowerShell 5.1
    # laedt die Assembly System.Net.Http nicht von selbst; der Typ
    # [System.Net.Http.HttpClient] ist dort erst nach
    # "Add-Type -AssemblyName System.Net.Http" bekannt. 7.5.0 hat den Typ
    # direkt benutzt und die Ausnahme still in $null verwandelt.
    #
    # WAS JETZT GILT:
    #   * die Assembly wird EINMAL explizit geladen (Ergebnis gemerkt),
    #   * laesst sie sich wirklich nicht laden, gibt es einen zweiten,
    #     vollstaendigen Transportweg ueber System.Net.HttpWebRequest
    #     (immer vorhanden) - inklusive multipart/form-data fuer den Upload,
    #   * es gibt KEINE leere Fehlermeldung mehr: jede Antwort nennt den
    #     Transportweg und den echten Grund, wenn nichts rausging,
    #   * ein schon GESENDETER Aufruf wird nie blind wiederholt (kein
    #     Doppel-Upload durch einen zweiten Weg).
    # ------------------------------------------------------------------
    function Get-OpenCloudHttpState {
        param($Shared)
        try {
            if ($null -eq $Shared) { return $null }
            $state = $null
            try { $state = $Shared.OpenCloudHttpState } catch {}
            if ($null -eq $state) {
                $state = [hashtable]::Synchronized(@{ probed = $false; available = $false; reason = '' })
                try { $Shared.OpenCloudHttpState = $state } catch {}
            }
            return $state
        } catch { return $null }
    }

    function Initialize-OpenCloudHttp {
        # EINMAL pro Bridge-Prozess: System.Net.Http laden und den Typ
        # wirklich anfassen. Das Ergebnis wird gemerkt, damit nicht jeder
        # Aufruf erneut laedt (und damit das runtime.log die Ursache nennt).
        param($Shared)
        $state = Get-OpenCloudHttpState $Shared
        if ($null -eq $state) { return $false }
        try {
            [System.Threading.Monitor]::Enter($state)
            if ([bool]$state.probed) { return [bool]$state.available }
            $state.probed = $true
            try { Add-Type -AssemblyName System.Net.Http -ErrorAction Stop } catch {
                $state.reason = ('Add-Type System.Net.Http: ' + $_.Exception.Message)
            }
            try {
                $probe = [System.Net.Http.HttpClient]::new()
                if ($null -ne $probe) {
                    $state.available = $true
                    try { $probe.Dispose() } catch {}
                }
            } catch {
                $state.available = $false
                if ([string]::IsNullOrWhiteSpace([string]$state.reason)) { $state.reason = $_.Exception.Message }
            }
            if ([bool]$state.available) {
                try { Write-BridgeLog 'Open Cloud: System.Net.Http ist geladen (HttpClient verfuegbar).' } catch {}
            } else {
                try { Write-BridgeLog ('Open Cloud: System.Net.Http NICHT verfuegbar (' + [string]$state.reason + ') - die Bridge benutzt den eingebauten HttpWebRequest-Weg.') } catch {}
            }
            return [bool]$state.available
        } catch {
            return $false
        } finally { try { [System.Threading.Monitor]::Exit($state) } catch {} }
    }

    function New-OpenCloudHttpClient {
        param($Shared, [string]$Key, [int]$TimeoutSeconds = 90)
        if (-not (Initialize-OpenCloudHttp $Shared)) { return $null }
        $client = $null
        try {
            $handler = [System.Net.Http.HttpClientHandler]::new()
            $handler.AllowAutoRedirect = $false
            $client = [System.Net.Http.HttpClient]::new($handler)
            $client.Timeout = [TimeSpan]::FromSeconds($TimeoutSeconds)
            try { $client.DefaultRequestHeaders.Remove('x-api-key') | Out-Null } catch {}
            $client.DefaultRequestHeaders.TryAddWithoutValidation('x-api-key', $Key) | Out-Null
        } catch {
            try { if ($null -ne $client) { $client.Dispose() } } catch {}
            $client = $null
        }
        return $client
    }

    function New-OpenCloudMultipartBytes {
        # multipart/form-data fuer beide offiziellen Open Cloud-Formate:
        # Assets-API: JSON-Teil "request" + "fileContent"; Monetization-APIs:
        # eigenstaendige Formularfelder + optional "imageFile".
        param([string]$JsonBody, [byte[]]$Bytes = $null, [string]$FileName = '', [string]$FileContentType = '', [string]$FieldName = 'fileContent', [string]$Boundary = '', [System.Collections.IDictionary]$FormFields = $null, [switch]$IncludeRequestPart)
        $encoding = New-Object System.Text.UTF8Encoding($false)
        $safeName = [string]$FileName
        if ([string]::IsNullOrWhiteSpace($safeName)) { $safeName = 'upload.bin' }
        $safeName = $safeName.Replace('"', '').Replace("`r", '').Replace("`n", '')
        $safeType = [string]$FileContentType
        if ([string]::IsNullOrWhiteSpace($safeType)) { $safeType = 'application/octet-stream' }
        $parts = New-Object System.Collections.Generic.List[byte]
        $hasPart = $false
        if ($IncludeRequestPart) {
            $headRequest = '--' + $Boundary + "`r`n" +
                'Content-Disposition: form-data; name="request"' + "`r`n" +
                'Content-Type: application/json' + "`r`n`r`n"
            $parts.AddRange($encoding.GetBytes($headRequest))
            $parts.AddRange($encoding.GetBytes([string]$JsonBody))
            $hasPart = $true
        }
        if ($null -ne $FormFields) {
            foreach ($fieldKey in $FormFields.Keys) {
                $fieldName = ([string]$fieldKey).Replace('"', '').Replace("`r", '').Replace("`n", '')
                if ([string]::IsNullOrWhiteSpace($fieldName)) { continue }
                if ($hasPart) { $headField = "`r`n--" + $Boundary + "`r`n" }
                else { $headField = '--' + $Boundary + "`r`n" }
                $headField += 'Content-Disposition: form-data; name="' + $fieldName + '"' + "`r`n`r`n"
                $parts.AddRange($encoding.GetBytes($headField))
                $parts.AddRange($encoding.GetBytes([string]$FormFields[$fieldKey]))
                $hasPart = $true
            }
        }
        if ($null -ne $Bytes -and $Bytes.Length -gt 0) {
            if ($hasPart) { $headFile = "`r`n--" + $Boundary + "`r`n" }
            else { $headFile = '--' + $Boundary + "`r`n" }
            $headFile += 'Content-Disposition: form-data; name="' + [string]$FieldName + '"; filename="' + $safeName + '"' + "`r`n" +
                'Content-Type: ' + $safeType + "`r`n`r`n"
            $parts.AddRange($encoding.GetBytes($headFile))
            $parts.AddRange($Bytes)
            $hasPart = $true
        }
        if ($hasPart) { $tail = "`r`n--" + $Boundary + '--' + "`r`n" }
        else { $tail = '--' + $Boundary + '--' + "`r`n" }
        $parts.AddRange($encoding.GetBytes($tail))
        return ,$parts.ToArray()
    }

    function Send-OpenCloudRequestFallback {
        # Zweiter Weg OHNE System.Net.Http - System.Net.HttpWebRequest ist in
        # jedem Windows PowerShell 5.1 vorhanden. WICHTIG: ein HTTP-Fehler
        # (401/403/429/5xx) ist KEIN Transportfehler; der Status und der
        # Originaltext von Roblox kommen unveraendert zurueck.
        param([string]$Method, [string]$Url, [string]$Key, [string]$JsonBody = '', [byte[]]$MultipartBytes = $null, [string]$MultipartContentType = '', [int]$TimeoutSeconds = 90, [System.Collections.IDictionary]$AdditionalHeaders = $null, [int]$MaxResponseChars = 4000000)
        $result = @{ transport = 'httpwebrequest'; status = 0; body = ''; error = ''; bodyTruncated = $false }
        $milliseconds = [int][Math]::Max(5000, ([int]$TimeoutSeconds * 1000))
        try {
            $request = [System.Net.HttpWebRequest]::Create([string]$Url)
            $request.AllowAutoRedirect = $false
            $request.Method = ([string]$Method).ToUpperInvariant()
            $request.Timeout = $milliseconds
            $request.ReadWriteTimeout = $milliseconds
            $request.Accept = 'application/json'
            try { $request.UserAgent = 'ArenaRobloxBridge' } catch {}
            if (-not [string]::IsNullOrWhiteSpace($Key)) {
                try { $request.Headers['x-api-key'] = $Key } catch { $request.Headers.Add('x-api-key', $Key) }
            }
            if ($null -ne $AdditionalHeaders) {
                foreach ($headerName in $AdditionalHeaders.Keys) {
                    if ([string]$headerName -match '^(?i:authorization|cookie|host|x-api-key|content-type|content-length|connection|transfer-encoding)$' -or [string]$AdditionalHeaders[$headerName] -match '[\r\n]') { throw 'Nicht erlaubter Header.' }
                    $request.Headers[[string]$headerName] = [string]$AdditionalHeaders[$headerName]
                }
            }
            $payload = $null
            $contentType = ''
            if ($null -ne $MultipartBytes -and $MultipartBytes.Length -gt 0) {
                $payload = $MultipartBytes
                $contentType = [string]$MultipartContentType
            } elseif (-not [string]::IsNullOrWhiteSpace($JsonBody)) {
                $payload = [System.Text.Encoding]::UTF8.GetBytes([string]$JsonBody)
                $contentType = 'application/json'
            }
            if ($null -ne $payload) {
                $request.ContentType = $contentType
                $request.ContentLength = $payload.Length
                $stream = $request.GetRequestStream()
                try { $stream.Write($payload, 0, $payload.Length) } finally { try { $stream.Dispose() } catch {} }
            }
            $response = $null
            try {
                $response = $request.GetResponse()
            } catch [System.Net.WebException] {
                $webError = $_.Exception
                if ($null -ne $webError -and $null -ne $webError.Response) { $response = $webError.Response } else { throw }
            }
            if ($null -ne $response) {
                $result.status = [int]$response.StatusCode
                $stream = $null
                try { $stream = $response.GetResponseStream() } catch {}
                if ($null -ne $stream) {
                    $reader = New-Object System.IO.StreamReader($stream, [System.Text.Encoding]::UTF8)
                    try {
                        $buffer = New-Object char[] 8192
                        $text = [Text.StringBuilder]::new()
                        while ($text.Length -le $MaxResponseChars) {
                            $count = $reader.Read($buffer, 0, [Math]::Min($buffer.Length, $MaxResponseChars + 1 - $text.Length))
                            if ($count -le 0) { break }
                            [void]$text.Append($buffer, 0, $count)
                        }
                        $result.bodyTruncated = $text.Length -gt $MaxResponseChars
                        $result.body = $text.ToString(0, [Math]::Min($text.Length, $MaxResponseChars))
                    } finally { try { $reader.Dispose() } catch {} }
                }
                try { $response.Dispose() } catch {}
            } else {
                $result.error = 'Roblox hat nicht geantwortet.'
            }
        } catch {
            $result.status = 0
            $result.error = $_.Exception.Message
            try { if ($_.Exception.InnerException) { $result.error = $result.error + ' / ' + $_.Exception.InnerException.Message } } catch {}
        }
        $result.body = Protect-OpenCloudResponse -Text ([string]$result.body) -Key $Key
        $result.error = Protect-OpenCloudResponse -Text ([string]$result.error) -Key $Key
        return $result
    }

    function Send-OpenCloudHttp {
        # EIN Aufruf nach Roblox (beliebige HTTP-Methode, JSON oder multipart).
        # Multipart unterstuetzt sowohl die Assets-API als auch Formularfelder
        # der offiziellen Pass-/Developer-Product-APIs.
        param($Shared, [string]$Method, [string]$Url, [string]$Key, [string]$JsonBody = '', [byte[]]$Bytes = $null, [string]$FileName = '', [string]$FileContentType = '', [string]$FileFieldName = 'fileContent', [int]$TimeoutSeconds = 90, [System.Collections.IDictionary]$FormFields = $null, [int]$MaxResponseChars = 2000000)
        $out = @{ transport = ''; status = 0; body = ''; error = ''; clientError = ''; bodyTruncated = $false }
        $methodUp = ([string]$Method).ToUpperInvariant()
        $hasFormFields = ($null -ne $FormFields)
        $hasFile = ($null -ne $Bytes -and $Bytes.Length -gt 0)
        $responseLimit = [Math]::Max(1, [int]$MaxResponseChars)
        if (Initialize-OpenCloudHttp $Shared) {
            $client = $null
            $request = $null
            $response = $null
            $sent = $false
            try {
                $client = New-OpenCloudHttpClient -Shared $Shared -Key $Key -TimeoutSeconds $TimeoutSeconds
                if ($null -ne $client) {
                    $content = $null
                    $form = $null
                    if ($hasFormFields -or $hasFile) {
                        $form = [System.Net.Http.MultipartFormDataContent]::new()
                        if (-not $hasFormFields) {
                            $requestPart = [System.Net.Http.StringContent]::new([string]$JsonBody, [System.Text.Encoding]::UTF8, 'application/json')
                            $form.Add($requestPart, 'request')
                        }
                        if ($hasFormFields) {
                            foreach ($fieldKey in $FormFields.Keys) {
                                $fieldName = ([string]$fieldKey).Replace('"', '').Replace("`r", '').Replace("`n", '')
                                if ([string]::IsNullOrWhiteSpace($fieldName)) { continue }
                                $fieldPart = [System.Net.Http.StringContent]::new([string]$FormFields[$fieldKey], [System.Text.Encoding]::UTF8, 'text/plain')
                                $form.Add($fieldPart, $fieldName)
                            }
                        }
                        if ($hasFile) {
                            $filePart = [System.Net.Http.ByteArrayContent]::new($Bytes)
                            $safeType = [string]$FileContentType
                            if ([string]::IsNullOrWhiteSpace($safeType)) { $safeType = 'application/octet-stream' }
                            $filePart.Headers.ContentType = [System.Net.Http.Headers.MediaTypeHeaderValue]::Parse($safeType)
                            $safeFileName = [string]$FileName
                            if ([string]::IsNullOrWhiteSpace($safeFileName)) { $safeFileName = 'upload.bin' }
                            $safeFileName = $safeFileName.Replace('"', '').Replace("`r", '').Replace("`n", '')
                            $form.Add($filePart, [string]$FileFieldName, $safeFileName)
                        }
                        $content = $form
                    } elseif (-not [string]::IsNullOrWhiteSpace($JsonBody)) {
                        $content = [System.Net.Http.StringContent]::new($JsonBody, [System.Text.Encoding]::UTF8, 'application/json')
                    }
                    $httpMethod = [System.Net.Http.HttpMethod]::new($methodUp)
                    $request = [System.Net.Http.HttpRequestMessage]::new($httpMethod, [Uri]$Url)
                    if ($null -ne $content) { $request.Content = $content }
                    $sent = $true
                    $response = $client.SendAsync($request).GetAwaiter().GetResult()
                    $out.transport = 'httpclient'
                    try { $out.status = [int]$response.StatusCode } catch {}
                    try {
                        $text = $response.Content.ReadAsStringAsync().GetAwaiter().GetResult()
                        $out.bodyTruncated = $text.Length -gt $responseLimit
                        if ($out.bodyTruncated) { $text = $text.Substring(0, $responseLimit) }
                        $out.body = Protect-OpenCloudResponse -Text $text -Key $Key
                    } catch {}
                    try { $response.Dispose() } catch {}
                    try { $request.Dispose() } catch {}
                    try { $client.Dispose() } catch {}
                    return (Protect-OpenCloudTransportResult -Result $out -Key $Key)
                }
            } catch {
                $out.clientError = $_.Exception.Message
                try { if ($_.Exception.InnerException) { $out.clientError = $out.clientError + ' / ' + $_.Exception.InnerException.Message } } catch {}
                if ($null -ne $response) { try { $response.Dispose() } catch {} }
                if ($null -ne $request) { try { $request.Dispose() } catch {} }
                if ($null -ne $client) { try { $client.Dispose() } catch {} }
                if ($sent) {
                    # Die Anfrage war schon unterwegs - NICHT blind erneut senden.
                    $out.status = 0
                    $out.transport = 'httpclient'
                    $out.error = $out.clientError
                    return (Protect-OpenCloudTransportResult -Result $out -Key $Key)
                }
            }
        }
        $multipart = $null
        $multipartType = ''
        if ($hasFormFields -or $hasFile) {
            $boundary = '----ArenaBridgeBoundary' + [guid]::NewGuid().ToString('N')
            $includeRequestPart = (-not $hasFormFields)
            $multipart = New-OpenCloudMultipartBytes -JsonBody $JsonBody -Bytes $Bytes -FileName $FileName -FileContentType $FileContentType -FieldName $FileFieldName -Boundary $boundary -FormFields $FormFields -IncludeRequestPart:$includeRequestPart
            $multipartType = 'multipart/form-data; boundary=' + $boundary
        }
        $fallback = Send-OpenCloudRequestFallback -Method $methodUp -Url $Url -Key $Key -JsonBody $JsonBody -MultipartBytes $multipart -MultipartContentType $multipartType -TimeoutSeconds $TimeoutSeconds -MaxResponseChars $responseLimit
        $out.bodyTruncated = [bool]$fallback.bodyTruncated
        $out.transport = [string]$fallback.transport
        $out.status = [int]$fallback.status
        $out.body = [string]$fallback.body
        if ($out.body.Length -gt $responseLimit) {
            $out.body = $out.body.Substring(0, $responseLimit)
            $out.bodyTruncated = $true
        }
        if ([int]$out.status -le 0) {
            if (-not [string]::IsNullOrWhiteSpace([string]$fallback.error)) { $out.error = [string]$fallback.error }
            elseif (-not [string]::IsNullOrWhiteSpace([string]$out.clientError)) { $out.error = [string]$out.clientError }
            elseif ([string]::IsNullOrWhiteSpace([string]$out.error)) { $out.error = 'Der Aufruf kam ohne Antwort zurueck.' }
        }
        return (Protect-OpenCloudTransportResult -Result $out -Key $Key)
    }

    function Get-OpenCloudTransportError {
        # Einheitliche, EHRLICHE Meldung, wenn nichts rausging: nennt den
        # Transportweg und den echten Grund - nie mehr nur "Client kaputt".
        param($Attempt, [string]$What = 'Der Aufruf')
        $reason = ''
        try { $reason = [string]$Attempt.error } catch {}
        if ([string]::IsNullOrWhiteSpace($reason)) { $reason = 'unbekannter Transportfehler' }
        $transport = ''
        try { $transport = [string]$Attempt.transport } catch {}
        if ([string]::IsNullOrWhiteSpace($transport)) { $transport = 'unbekannter Weg' }
        return @{
            ok = $false; code = 'OPENCLOUD_UNREACHABLE'
            error = ($What + ' konnte nicht zu Roblox gesendet werden (' + $transport + '): ' + $reason)
            transport = $transport
            transportError = $reason
            howToFix = 'Pruefe die Internetverbindung des Nutzers (Firewall/Proxy). Der Schluessel wurde NICHT verbraucht - versuche es erneut. Bleibt es dabei, nennt das runtime.log der Bridge den Transportweg und den genauen Grund.'
        }
    }

    function Get-OpenCloudErrorBody {
        param($Response, [int]$MaxCharacters = 600)
        try {
            if ($null -eq $Response) { return '' }
            $text = $Response.Content.ReadAsStringAsync().GetAwaiter().GetResult()
            if ([string]::IsNullOrWhiteSpace($text)) { return '' }
            $limit = [Math]::Max(1, [int]$MaxCharacters)
            if ($text.Length -gt $limit) { $text = $text.Substring(0, $limit) }
            return $text
        } catch { return '' }
    }

    function ConvertTo-OpenCloudHttpError {
        # Roblox-Fehler gehen UNVERAENDERT an den Agenten: Status, Code und
        # Antworttext. Nichts wird schoengeredet, nichts erfunden.
        param([int]$Status, [string]$Body, [string]$What = 'Upload')
        if ($Status -eq 429) {
            return @{
                ok = $false; code = 'OPENCLOUD_RATE_LIMITED'
                error = ('Roblox meldet 429 (Rate Limit) beim ' + $What + '. Zu viele Uploads in kurzer Zeit - warte einige Minuten und versuche es dann erneut.')
                status = 429; robloxResponse = $Body
                howToFix = 'Sage dem Nutzer in einem Satz, dass Roblox gerade drosselt. Warte, bevor du es erneut versuchst - ein sofortiger zweiter Versuch wird wieder abgelehnt.'
            }
        }
        if ($Status -eq 401 -or $Status -eq 403) {
            return @{
                ok = $false; code = 'OPENCLOUD_KEY_REJECTED'
                error = ('Roblox hat den Open-Cloud-Schluessel abgelehnt (HTTP ' + [string]$Status + ') beim ' + $What + '. Der Schluessel ist ungueltig, abgelaufen, ohne die Rechte ASSETS + LESEN + SCHREIBEN, oder die IP-Sperre (Security) passt nicht.')
                status = $Status; robloxResponse = $Body
                howToFix = 'Sage dem Nutzer woertlich: Bitte oben in der Bridge auf das Zahnrad (Einstellungen) gehen, im Abschnitt ROBLOX OPEN CLOUD das aufklappbare Tutorial machen und den Schluessel neu erstellen und speichern - mit den Rechten Assets/Lesen/Schreiben. Danach kann ich weiterarbeiten.'
            }
        }
        if ($Status -ge 500) {
            return @{
                ok = $false; code = 'OPENCLOUD_SERVER_ERROR'
                error = ('Roblox meldet einen Serverfehler (HTTP ' + [string]$Status + ') beim ' + $What + '.')
                status = $Status; robloxResponse = $Body
                howToFix = 'Das liegt nicht am Schluessel. Sage dem Nutzer, dass Roblox gerade stoert, und versuche es spaeter erneut.'
            }
        }
        return @{
            ok = $false; code = 'OPENCLOUD_UPLOAD_REJECTED'
            error = ('Roblox hat den ' + $What + ' abgelehnt (HTTP ' + [string]$Status + ').')
            status = $Status; robloxResponse = $Body
            howToFix = 'Pruefe die Angaben: Datei kleiner als 20 MB, Bilder unter 8000x8000 Pixel, Mesh als FBX/GLB. Die vollstaendige Roblox-Antwort steht in robloxResponse - melde sie dem Nutzer unverfaelscht.'
        }
    }

    function Get-OpenCloudStudioDeveloper {
        # Version 7.5.6: Der Asset-Ersteller ist das Konto, das in Roblox Studio
        # angemeldet ist. Das Plugin meldet StudioService:GetUserId() getrennt
        # von game.CreatorId/game.CreatorType (Eigentuemer des Places).
        param([string]$SessionId = '')
        if ([string]::IsNullOrWhiteSpace($SessionId)) { return $null }
        try {
            $entry = Get-SessionEntry $SessionId
            if ($null -eq $entry) { return $null }
            $userId = ([string]$entry.editorUserId).Trim()
            if ($userId -notmatch '^\d+$' -or $userId -eq '0') { return $null }
            return @{ ok = $true; creatorId = $userId; creatorKind = 'user'; source = 'studio_login' }
        } catch {
            return $null
        }
    }

    function Resolve-OpenCloudCreatorForUpload {
        # Version 7.5.6: ZUERST die echte Studio-Anmeldung (StudioService:GetUserId),
        # damit Open Cloud als der angemeldete Nutzer hochlaedt. Nur wenn Studio
        # keine User-ID meldet, bleibt die aus dem API-Key gelesene Resource der
        # automatische Rueckfall. Es gibt kein manuelles Entwickler-Feld mehr.
        param($Shared, [string]$SessionId = '')
        $studio = Get-OpenCloudStudioDeveloper -SessionId $SessionId
        if ($null -ne $studio) { return $studio }
        $fromKey = Resolve-OpenCloudCreatorFromKey -Shared $Shared
        if ($fromKey.ok -eq $true) {
            return @{ ok = $true; creatorId = [string]$fromKey.creatorId; creatorKind = [string]$fromKey.creatorKind; source = 'key' }
        }
        return $fromKey
    }

    function Invoke-OpenCloudUpload {
        param($Shared, [string]$FilePath, [string]$FileName, [byte[]]$Bytes, [string]$AssetType, [string]$DisplayName, [string]$Description, [int]$TimeoutSeconds = 90, [string]$SessionId = '')

        $gate = Assert-OpenCloudToolAccess -Shared $Shared -RequiredScopes @('asset:read','asset:write') -What 'upload_asset'
        if ($gate.ok -ne $true) { return $gate }
        $config = Get-OpenCloudConfig $Shared
        # Version 7.5.6: Der angemeldete Studio-Nutzer ist der primaere
        # Asset-Ersteller; ohne Studio-ID wird die Resource aus dem API-Key genutzt.
        $creatorFound = Resolve-OpenCloudCreatorForUpload -Shared $Shared -SessionId $SessionId
        if ($creatorFound.ok -ne $true) {
            return @{
                ok = $false; code = [string]$creatorFound.code
                error = ('Die Bridge konnte den Entwickler nicht ermitteln: ' + [string]$creatorFound.error)
                userMessage = [string]$creatorFound.userMessage
                howToFix = [string]$creatorFound.howToFix
                introspect = $creatorFound
            }
        }
        $config.creatorId = [string]$creatorFound.creatorId
        $config.creatorKind = [string]$creatorFound.creatorKind

        # --- Datei: entweder aus dem Dateisystem oder direkt aus den Bytes ---
        $content = $null
        $size = 0
        $name = ([string]$FileName).Trim()
        if ($null -ne $Bytes -and $Bytes.Length -gt 0) {
            $content = $Bytes
            $size = $Bytes.Length
            if ([string]::IsNullOrWhiteSpace($name)) { $name = 'upload.bin' }
        } else {
            if ([string]::IsNullOrWhiteSpace($FilePath) -or -not (Test-Path -LiteralPath $FilePath)) {
                return @{ ok = $false; code = 'FILE_NOT_FOUND'; error = ('Die Datei wurde nicht gefunden: ' + [string]$FilePath + '. Nenne einen Pfad aus mesh_status (uploadPath) oder liefere contentBase64 mit.'); howToFix = 'Lies mesh_status: dort steht je Slot der exakte uploadPath.' }
            }
            try {
                $content = [System.IO.File]::ReadAllBytes($FilePath)
                $size = $content.Length
                if ([string]::IsNullOrWhiteSpace($name)) { $name = [System.IO.Path]::GetFileName($FilePath) }
            } catch {
                return @{ ok = $false; code = 'FILE_UNREADABLE'; error = ('Die Datei konnte nicht gelesen werden: ' + $_.Exception.Message) }
            }
        }
        if ($size -le 0) { return @{ ok = $false; code = 'FILE_EMPTY'; error = 'Die Datei ist leer - es wurde nichts hochgeladen.' } }
        if ($size -gt 20971520) {
            return @{ ok = $false; code = 'FILE_TOO_LARGE'; error = ('Die Datei ist ' + [Math]::Round(($size / 1048576.0), 2) + ' MiB gross. Dieses Bridge-Upload-Tool nimmt höchstens 20 MiB je Datei an.'); howToFix = 'Baue den Slot einfacher (weniger Unterteilungen, Decimate/Remesh) oder teile das Modell in mehrere Slots.' }
        }
        $spec = Get-OpenCloudAssetSpec -Path $name -WantedType $AssetType
        if (-not $spec.ok) { return $spec }
        if ([string]::IsNullOrWhiteSpace($name)) { $name = ('upload' + [string]$spec.extension) }

        $display = ([string]$DisplayName).Trim()
        if ([string]::IsNullOrWhiteSpace($display)) { $display = [System.IO.Path]::GetFileNameWithoutExtension($name) }
        if ($display.Length -gt 90) { $display = $display.Substring(0, 90) }
        $text = ([string]$Description).Trim()
        if ([string]::IsNullOrWhiteSpace($text)) { $text = 'Hochgeladen von Arena Roblox Bridge.' }
        if ($text.Length -gt 900) { $text = $text.Substring(0, 900) }

        $creator = @{}
        if ([string]$config.creatorKind -eq 'group') { $creator['groupId'] = [string]$config.creatorId } else { $creator['userId'] = [string]$config.creatorId }
        $meta = @{
            assetType = [string]$spec.assetType
            displayName = $display
            description = $text
            creationContext = @{ creator = $creator; expectedPrice = 0 }
        }
        $metaJson = $meta | ConvertTo-Json -Depth 6 -Compress

        # Version 7.5.2: EIN Transportweg-Aufruf statt eines rohen HttpClient.
        # Ohne System.Net.Http (Windows PowerShell 5.1 laedt die Assembly nicht
        # von selbst) uebernimmt der HttpWebRequest-Weg - der Upload geht
        # trotzdem raus, statt mit "Client konnte nicht erzeugt werden" zu
        # enden.
        $attempt = Send-OpenCloudHttp -Shared $Shared -Method 'POST' -Url 'https://apis.roblox.com/assets/v1/assets' -Key ([string]$config.key) -JsonBody $metaJson -Bytes $content -FileName $name -FileContentType ([string]$spec.contentType) -FileFieldName 'fileContent' -TimeoutSeconds $TimeoutSeconds
        if ([int]$attempt.status -le 0) {
            $transportError = Get-OpenCloudTransportError -Attempt $attempt -What 'Der Upload'
            $transportError.transport = [string]$attempt.transport
            return $transportError
        }
        $status = [int]$attempt.status
        $body = [string]$attempt.body
        if ($status -lt 200 -or $status -gt 299) {
            return (ConvertTo-OpenCloudHttpError -Status $status -Body $body -What 'Upload')
        }
        try {
            $parsed = $null
            try { $parsed = $body | ConvertFrom-Json } catch { $parsed = $null }
            $opPath = ''
            try { if ($parsed -and $parsed.path) { $opPath = [string]$parsed.path } } catch {}
            $opId = ''
            if ($opPath -match '/([^/]+)$') { $opId = $Matches[1] }
            if ([string]::IsNullOrWhiteSpace($opId)) { $opId = $opPath }
            if ([string]::IsNullOrWhiteSpace($opId)) {
                return @{ ok = $false; code = 'OPENCLOUD_BAD_RESPONSE'; error = 'Roblox hat den Upload angenommen, aber keine Operation zum Nachverfolgen zurueckgemeldet.'; robloxResponse = $body }
            }
            # Schon fertig? Dann steht die Asset-Id direkt im ersten Ergebnis.
            $doneNow = $false
            try { if ($parsed -and $parsed.done -eq $true) { $doneNow = $true } } catch {}
            if ($doneNow) {
                $assetId = ''
                try { if ($parsed.response -and $parsed.response.assetId) { $assetId = [string]$parsed.response.assetId } } catch {}
                if (-not [string]::IsNullOrWhiteSpace($assetId)) {
                    return @{ ok = $true; code = 'UPLOADED'; assetId = $assetId; operationId = $opId; poll = @{ needed = $false } }
                }
            }
            return @{
                ok = $true; code = 'UPLOAD_STARTED'
                operationId = $opId
                operationPath = $opPath
                assetType = [string]$spec.assetType
                fileName = $name
                bytes = $size
                displayName = $display
            }
        } catch {
            # Nur noch Auswertungsfehler (JSON/Struktur) - der Netzweg steckt
            # vollstaendig in Send-OpenCloudHttp und meldet sich dort.
            $message = $_.Exception.Message
            return @{
                ok = $false; code = 'OPENCLOUD_BAD_RESPONSE'
                error = ('Die Antwort von Roblox war nicht lesbar: ' + $message)
                robloxResponse = $body
            }
        }
    }

    function Get-OpenCloudOperation {
        # Einmaliger Blick auf die asynchrone Operation. Ergebnis ist immer
        # ehrlich: pending, done (mit assetId) oder failed (mit Roblox-Text).
        param($Shared, [string]$OperationId)
        $gate = Assert-OpenCloudToolAccess -Shared $Shared -RequiredScopes @('asset:read') -What 'upload_asset'
        if ($gate.ok -ne $true) { return $gate }
        $config = Get-OpenCloudConfig $Shared
        $clean = ([string]$OperationId).Trim()
        if ($clean -match '/([^/]+)$') { $clean = $Matches[1] }
        if ([string]::IsNullOrWhiteSpace($clean)) {
            return @{ ok = $false; code = 'BAD_ARGS'; error = 'Keine operationId angegeben.' }
        }
        # Version 7.5.2: derselbe Transportweg wie beim Upload (HttpClient,
        # sonst HttpWebRequest) - kein "Client konnte nicht erzeugt werden".
        $attempt = Send-OpenCloudHttp -Shared $Shared -Method 'GET' -Url ('https://apis.roblox.com/assets/v1/operations/' + [Uri]::EscapeDataString($clean)) -Key ([string]$config.key) -TimeoutSeconds 30
        if ([int]$attempt.status -le 0) {
            return (Get-OpenCloudTransportError -Attempt $attempt -What 'Das Abfragen des Upload-Status')
        }
        try {
            $status = [int]$attempt.status
            $body = [string]$attempt.body
            if ($status -lt 200 -or $status -gt 299) {
                return (ConvertTo-OpenCloudHttpError -Status $status -Body $body -What 'Abfragen des Upload-Status')
            }
            $parsed = $null
            try { $parsed = $body | ConvertFrom-Json } catch { $parsed = $null }
            if ($null -eq $parsed) {
                return @{ ok = $false; code = 'OPENCLOUD_BAD_RESPONSE'; error = 'Die Antwort von Roblox war nicht lesbar.'; robloxResponse = $body }
            }
            $done = $false
            try { $done = [bool]$parsed.done } catch {}
            if (-not $done) {
                return @{ ok = $true; state = 'pending'; operationId = $clean }
            }
            $errText = ''
            try { if ($parsed.error) { $errText = ($parsed.error | ConvertTo-Json -Compress) } } catch {}
            if (-not [string]::IsNullOrWhiteSpace($errText)) {
                return @{
                    ok = $false; code = 'OPENCLOUD_OPERATION_FAILED'
                    error = ('Roblox hat den Upload abgelehnt: ' + $errText)
                    robloxResponse = $errText
                    howToFix = 'Haeufige Gruende: Datei zu gross, Format nicht erlaubt, Bild ueber 8000x8000 oder der Key erlaubt ASSETS write nicht fuer das angemeldete Studio-Konto. Melde dem Nutzer den Roblox-Text unverfaelscht.'
                }
            }
            $assetId = ''
            try { if ($parsed.response -and $parsed.response.assetId) { $assetId = [string]$parsed.response.assetId } } catch {}
            if ([string]::IsNullOrWhiteSpace($assetId)) {
                return @{ ok = $true; state = 'done_without_id'; operationId = $clean; robloxResponse = $body }
            }
            $assetType = ''
            try { if ($parsed.response -and $parsed.response.assetType) { $assetType = [string]$parsed.response.assetType } } catch {}
            return @{
                ok = $true; state = 'done'
                assetId = $assetId
                assetType = $assetType
                operationId = $clean
            }
        } catch {
            $message = $_.Exception.Message
            try { if ($_.Exception.InnerException) { $message = $message + ' / ' + $_.Exception.InnerException.Message } } catch {}
            return @{ ok = $false; code = 'OPENCLOUD_BAD_RESPONSE'; error = ('Die Statusantwort von Roblox war nicht lesbar: ' + $message); robloxResponse = ([string]$attempt.body) }
        }
    }

    function Wait-OpenCloudOperation {
        # Kurz pollen (Bilder sind oft in 1-2 s fertig, Meshes brauchen
        # laenger). Reicht die Zeit nicht, kommt der Stand 'pending' mit der
        # operationId zurueck - der Agent kann dann gezielt weiterfragen,
        # statt blind zu warten.
        param($Shared, [string]$OperationId, [int]$MaxSeconds = 20)
        $deadline = [DateTime]::UtcNow.AddSeconds($MaxSeconds)
        $last = $null
        $tries = 0
        while ($true) {
            if ($tries -gt 0) { Start-Sleep -Milliseconds 1500 }
            $last = Get-OpenCloudOperation $Shared $OperationId
            $tries = $tries + 1
            if ($null -eq $last) { break }
            if ($last.ok -ne $true) { return $last }
            if ([string]$last.state -ne 'pending') { return $last }
            if ([DateTime]::UtcNow -ge $deadline) { break }
        }
        if ($null -eq $last) { return @{ ok = $false; code = 'OPENCLOUD_BAD_RESPONSE'; error = 'Der Upload-Status blieb leer.' } }
        $last.state = 'pending'
        $last.pollBudgetSeconds = $MaxSeconds
        $last.nextCall = ('upload_asset { operationId: "' + [string]$OperationId + '" }')
        $last.hint = 'Roblox braucht laenger. Rufe upload_asset mit dieser operationId erneut auf, um fertig zu werden - nicht in einer engen Schleife pollen.'
        return $last
    }

    function Invoke-OpenCloudIntrospect {
        # Version 7.5.2: die OFFIZIELLE Selbstauskunft des Schluessels -
        # POST https://apis.roblox.com/api-keys/v1/introspect (Roblox-Doku:
        # "Manage API keys -> Introspect API keys"). Sie nennt Name, den
        # autorisierten Nutzer, ALLE Scopes mit Operationen und Ressourcen
        # (userId/groupId), ob der Schluessel aktiv ist, ob er abgelaufen ist -
        # und prueft dabei die IP-Freigabe. Das ist die einzige ehrliche
        # Pruefung: sie sagt wirklich, was der Schluessel DARF.
        param($Shared, [string]$Key = '')
        $clean = ([string]$Key).Trim()
        if ([string]::IsNullOrWhiteSpace($clean)) {
            $config = Get-OpenCloudConfig $Shared
            $clean = ([string]$config.key).Trim()
        }
        if ([string]::IsNullOrWhiteSpace($clean)) {
            return @{ ok = $false; code = 'OPENCLOUD_KEY_MISSING'; error = 'Kein Schluessel hinterlegt.' }
        }
        $payload = (@{ apiKey = $clean } | ConvertTo-Json -Compress)
        $attempt = Send-OpenCloudHttp -Shared $Shared -Method 'POST' -Url 'https://apis.roblox.com/api-keys/v1/introspect' -Key $clean -JsonBody $payload -TimeoutSeconds 20 -MaxResponseChars 2000000
        if ([int]$attempt.status -le 0) {
            return (Get-OpenCloudTransportError -Attempt $attempt -What 'Die Schluesselpruefung')
        }
        if ($attempt.bodyTruncated) { return @{ ok = $false; code = 'OPENCLOUD_RESPONSE_TOO_LARGE'; error = 'Die Selbstauskunft ist größer als 2 Millionen Zeichen. Der vorhandene Key bleibt unverändert.' } }
        $status = [int]$attempt.status
        $body = [string]$attempt.body
        if ($status -eq 401 -or $status -eq 403) {
            return @{ ok = $false; code = 'OPENCLOUD_KEY_REJECTED'; status = $status; error = ('Roblox hat den Schluessel abgelehnt (HTTP ' + [string]$status + ').'); robloxResponse = $body; transport = [string]$attempt.transport }
        }
        if ($status -lt 200 -or $status -gt 299) {
            $mapped = ConvertTo-OpenCloudHttpError -Status $status -Body $body -What 'die Schluesselpruefung'
            $mapped.transport = [string]$attempt.transport
            return $mapped
        }
        $parsed = $null
        try { $parsed = $body | ConvertFrom-Json } catch { $parsed = $null }
        if ($null -eq $parsed) {
            return @{ ok = $false; code = 'OPENCLOUD_BAD_RESPONSE'; error = 'Die Selbstauskunft von Roblox war nicht lesbar.'; robloxResponse = $body }
        }
        $scopes = New-Object System.Collections.Generic.List[object]
        $assetWrite = $false
        $assetRead = $false
        $universeWrite = $false
        $universePlaceWrite = $false
        $gamePassRead = $false
        $gamePassWrite = $false
        $developerProductRead = $false
        $developerProductWrite = $false
        $scopeNames = New-Object System.Collections.Generic.List[string]
        $writeUsers = New-Object System.Collections.Generic.List[string]
        $writeGroups = New-Object System.Collections.Generic.List[string]
        # Version 7.6.0: Der Schluessel soll FAST ALLES koennen - deshalb
        # erkennt die Selbstauskunft jetzt den kompletten offiziellen
        # Open-Cloud-Scope-Katalog (Roblox-OpenAPI-Spezifikation):
        # universe read, universe-places (Place-Publishing), Place-Instances,
        # DataStores (control/objects/versions), Ordered DataStores,
        # Memory-Stores, Messaging, Lokalisierung und Nutzer-Benachrichtigungen.
        $universeRead = $false
        $universePlaceRead = $false
        $placePublishWrite = $false
        $placePublishRead = $false
        $placeInstanceRead = $false
        $placeInstanceWrite = $false
        $datastoreControlList = $false
        $datastoreObjectsList = $false
        $datastoreObjectsRead = $false
        $datastoreObjectsCreate = $false
        $datastoreObjectsUpdate = $false
        $datastoreObjectsDelete = $false
        $datastoreVersionsList = $false
        $orderedDatastoreRead = $false
        $orderedDatastoreWrite = $false
        $memoryStoreAny = $false
        $messagingPublish = $false
        $localizationRead = $false
        $localizationWrite = $false
        $userNotificationWrite = $false
        $creatorStoreProductRead = $false
        $creatorStoreProductWrite = $false
        $userRestrictionRead = $false
        $userRestrictionWrite = $false
        $universeThumbnailRead = $false
        $universeThumbnailWrite = $false
        $universePlacesRead = $false
        $universePlacesWrite = $false
        $universeEventRead = $false
        $universeEventWrite = $false
        $universeAnalyticsRead = $false
        $universeAnalyticsWrite = $false
        $thumbnailsRead = $false
        $thumbnailsWrite = $false
        try {
            foreach ($scope in @($parsed.scopes)) {
                if ($null -eq $scope) { continue }
                $name = ([string]$scope.name).Trim()
                $lowerName = $name.ToLowerInvariant()
                $operations = New-Object System.Collections.Generic.List[string]
                try { foreach ($operation in @($scope.operations)) { $operations.Add((([string]$operation).Trim().ToLowerInvariant())) } } catch {}
                $scopeBase = $lowerName
                $scopeSuffix = ''
                if ($lowerName.Contains(':')) {
                    $scopeBase = $lowerName.Substring(0, $lowerName.IndexOf(':'))
                    $scopeSuffix = $lowerName.Substring($lowerName.IndexOf(':') + 1)
                }
                $allowedOperations = New-Object System.Collections.Generic.List[string]
                foreach ($opName in $operations.ToArray()) {
                    if ($null -ne (Get-OpenCloudCatalog).permissions.PSObject.Properties[($scopeBase + ':' + $opName)]) { $allowedOperations.Add($opName) }
                }
                $operations = $allowedOperations
                if ($scopeSuffix) {
                    if ($null -eq (Get-OpenCloudCatalog).permissions.PSObject.Properties[$lowerName]) { continue }
                } elseif ($operations.Count -eq 0) { continue }
                $scopeNames.Add($name)
                $writes = $operations.Contains('write') -or $operations.Contains('create') -or $operations.Contains('update') -or $scopeSuffix -eq 'write'
                $reads = $operations.Contains('read') -or $scopeSuffix -eq 'read'
                $lists = $operations.Contains('list') -or $scopeSuffix -eq 'list'
                $deletes = $operations.Contains('delete') -or $scopeSuffix -eq 'delete'
                $creates = $operations.Contains('create') -or $scopeSuffix -eq 'create'
                $updates = $operations.Contains('update') -or $operations.Contains('write') -or $scopeSuffix -eq 'update' -or $scopeSuffix -eq 'write'
                $isAsset = $scopeBase -eq 'asset'
                if ($isAsset -and $writes) {
                    $assetWrite = $true
                    try { foreach ($entry in @($scope.userIds)) { $value = ([string]$entry).Trim(); if (-not [string]::IsNullOrWhiteSpace($value) -and $value -ne '*') { $writeUsers.Add($value) } } } catch {}
                    try { foreach ($entry in @($scope.groupIds)) { $value = ([string]$entry).Trim(); if (-not [string]::IsNullOrWhiteSpace($value) -and $value -ne '*') { $writeGroups.Add($value) } } } catch {}
                }
                if ($isAsset -and $reads) { $assetRead = $true }
                if ($scopeBase -eq 'universe' -and $writes) { $universeWrite = $true }
                if ($scopeBase -eq 'universe' -and $reads) { $universeRead = $true }
                if ($scopeBase -eq 'universe.place' -and $writes) { $universePlaceWrite = $true }
                if ($scopeBase -eq 'universe.place' -and $reads) { $universePlaceRead = $true }
                if ($scopeBase -in @('game-pass','game-passes') -and $reads) { $gamePassRead = $true }
                if ($scopeBase -in @('game-pass','game-passes') -and $writes) { $gamePassWrite = $true }
                if ($scopeBase -in @('developer-product','developer-products') -and $reads) { $developerProductRead = $true }
                if ($scopeBase -in @('developer-product','developer-products') -and $writes) { $developerProductWrite = $true }
                if ($scopeBase -eq 'universe-places' -and ($writes -or $creates)) { $placePublishWrite = $true }
                if ($scopeBase -eq 'universe-places' -and $reads) { $placePublishRead = $true }
                if ($scopeBase -eq 'universe.places' -and $reads) { $universePlacesRead = $true }
                if ($scopeBase -eq 'universe.places' -and ($writes -or $creates)) { $universePlacesWrite = $true }
                if ($scopeBase -eq 'universe.place.instance' -and $reads) { $placeInstanceRead = $true }
                if ($scopeBase -eq 'universe.place.instance' -and $writes) { $placeInstanceWrite = $true }
                if ($scopeBase -eq 'universe-datastores.control' -and ($lists -or $reads)) { $datastoreControlList = $true }
                if ($scopeBase -eq 'universe-datastores.objects') {
                    if ($lists -or $reads) { $datastoreObjectsList = $true }
                    if ($reads) { $datastoreObjectsRead = $true }
                    if ($creates) { $datastoreObjectsCreate = $true }
                    if ($updates) { $datastoreObjectsUpdate = $true }
                    if ($deletes) { $datastoreObjectsDelete = $true }
                }
                if ($scopeBase -eq 'universe-datastores.versions' -and ($lists -or $reads)) { $datastoreVersionsList = $true }
                if ($scopeBase -eq 'universe.ordered-data-store.scope.entry' -and $reads) { $orderedDatastoreRead = $true }
                if ($scopeBase -eq 'universe.ordered-data-store.scope.entry' -and $writes) { $orderedDatastoreWrite = $true }
                if ($scopeBase -like 'memory-store*' -or $scopeBase -like 'universe.memory-store*') { $memoryStoreAny = $true }
                if ($scopeBase -eq 'universe-messaging-service' -or $scopeBase -like 'universe.messaging*') { $messagingPublish = $true }
                if ($scopeBase -like 'localization*' -and $reads) { $localizationRead = $true }
                if ($scopeBase -like 'localization*' -and $writes) { $localizationWrite = $true }
                if ($scopeBase -eq 'user.user-notification' -and $writes) { $userNotificationWrite = $true }
                if ($scopeBase.StartsWith('creator-store-product') -and $reads) { $creatorStoreProductRead = $true }
                if ($scopeBase.StartsWith('creator-store-product') -and $writes) { $creatorStoreProductWrite = $true }
                if (($scopeBase -eq 'universe.user-restriction' -or $scopeBase.Contains('user-restriction')) -and $reads) { $userRestrictionRead = $true }
                if (($scopeBase -eq 'universe.user-restriction' -or $scopeBase.Contains('user-restriction')) -and $writes) { $userRestrictionWrite = $true }
                if (($scopeBase -eq 'universe.thumbnail' -or $scopeBase.StartsWith('universe.thumbnails') -or $scopeBase.Contains('thumbnail-personalization')) -and $reads) { $universeThumbnailRead = $true }
                if (($scopeBase -eq 'universe.thumbnail' -or $scopeBase.StartsWith('universe.thumbnails') -or $scopeBase.Contains('thumbnail-personalization')) -and $writes) { $universeThumbnailWrite = $true }
                if (($scopeBase -eq 'universe.event' -or $scopeBase -eq 'universe.events' -or $scopeBase.Contains('virtual-event')) -and $reads) { $universeEventRead = $true }
                if (($scopeBase -eq 'universe.event' -or $scopeBase -eq 'universe.events' -or $scopeBase.Contains('virtual-event')) -and $writes) { $universeEventWrite = $true }
                if (($scopeBase -eq 'universe.analytics') -and $reads) { $universeAnalyticsRead = $true }
                if (($scopeBase -eq 'universe.analytics') -and $writes) { $universeAnalyticsWrite = $true }
                if (($scopeBase -eq 'thumbnails' -or $scopeBase -eq 'thumbnail') -and $reads) { $thumbnailsRead = $true }
                if (($scopeBase -eq 'thumbnails' -or $scopeBase -eq 'thumbnail') -and $writes) { $thumbnailsWrite = $true }
                $scopes.Add(@{
                    name = $name
                    operations = $operations.ToArray()
                    userIds = $(try { @($scope.userIds) } catch { @() })
                    groupIds = $(try { @($scope.groupIds) } catch { @() })
                    universeIds = $(try { @($scope.universeIds) } catch { @() })
                    universeDatastores = $(try { @($scope.universeDatastores) } catch { @() })
                })
            }
        } catch {}
        $enabled = $true
        try { $enabled = [bool]$parsed.enabled } catch {}
        $expired = $false
        try { $expired = [bool]$parsed.expired } catch {}
        $expirationTimeUtc = ''
        try { $expirationTimeUtc = [string]$parsed.expirationTimeUtc } catch {}
        $hasExpiration = $expired
        if (-not $hasExpiration -and -not [string]::IsNullOrWhiteSpace($expirationTimeUtc)) {
            $expiryLower = $expirationTimeUtc.Trim().ToLowerInvariant()
            if ($expiryLower -ne 'null' -and $expiryLower -ne 'none' -and -not $expiryLower.StartsWith('0001-01-01')) { $hasExpiration = $true }
        }
        if (-not $enabled) { return @{ ok = $false; code = 'OPENCLOUD_KEY_REJECTED'; error = 'Der Key ist deaktiviert. Der gespeicherte Key bleibt unverändert.' } }
        $authorizedUserId = ''
        try { if ($null -ne $parsed.authorizedUserId) { $authorizedUserId = [string]$parsed.authorizedUserId } } catch {}
        return @{
            ok = $true; code = 'KEY_ACCEPTED'; status = $status; accepted = $true
            transport = [string]$attempt.transport
            name = $(try { [string]$parsed.name } catch { '' })
            authorizedUserId = $authorizedUserId
            enabled = $enabled
            expired = $expired
            expirationTimeUtc = $expirationTimeUtc
            hasExpiration = $hasExpiration
            scopes = $scopes.ToArray()
            scopeNames = $scopeNames.ToArray()
            assetRead = $assetRead
            assetWrite = $assetWrite
            universeWrite = $universeWrite
            universePlaceWrite = $universePlaceWrite
            universePlaceRead = $universePlaceRead
            gamePassRead = $gamePassRead
            gamePassWrite = $gamePassWrite
            developerProductRead = $developerProductRead
            developerProductWrite = $developerProductWrite
            universeRead = $universeRead
            placePublishWrite = $placePublishWrite
            datastoreControlList = $datastoreControlList
            datastoreObjectsList = $datastoreObjectsList
            datastoreObjectsRead = $datastoreObjectsRead
            datastoreObjectsCreate = $datastoreObjectsCreate
            datastoreObjectsUpdate = $datastoreObjectsUpdate
            datastoreObjectsDelete = $datastoreObjectsDelete
            datastoreVersionsList = $datastoreVersionsList
            orderedDatastoreRead = $orderedDatastoreRead
            orderedDatastoreWrite = $orderedDatastoreWrite
            creatorStoreProductRead = $creatorStoreProductRead
            creatorStoreProductWrite = $creatorStoreProductWrite
            userRestrictionRead = $userRestrictionRead
            universeThumbnailRead = $universeThumbnailRead
            universeThumbnailWrite = $universeThumbnailWrite
            universeEventRead = $universeEventRead
            universeEventWrite = $universeEventWrite
            universeAnalyticsRead = $universeAnalyticsRead
            universeAnalyticsWrite = $universeAnalyticsWrite
            writeUserIds = $writeUsers.ToArray()
            writeGroupIds = $writeGroups.ToArray()
        }
    }

    function Get-OpenCloudArgumentValue {
        param($Arguments, [string]$Name)
        $found = $false
        $value = $null
        if ($null -eq $Arguments -or [string]::IsNullOrWhiteSpace($Name)) { return @{ found = $false; value = $null } }
        if ($Arguments -is [System.Collections.IDictionary]) {
            try {
                if ($Arguments.Contains($Name)) { $found = $true; $value = $Arguments[$Name] }
            } catch {}
        }
        if (-not $found) {
            try {
                $property = $Arguments.PSObject.Properties[$Name]
                if ($null -ne $property) { $found = $true; $value = $property.Value }
            } catch {}
        }
        return @{ found = $found; value = $value }
    }

    function Get-CreatorDashboardImage {
        # Game-pass/developer-product APIs accept an icon as the multipart
        # "imageFile" field. Accept PNG/JPEG only and verify the actual header.
        param($Arguments)
        $encodedArg = Get-OpenCloudArgumentValue -Arguments $Arguments -Name 'iconBase64'
        if (-not $encodedArg.found) { return @{ ok = $true; supplied = $false; bytes = $null; fileName = ''; contentType = '' } }
        $encoded = ([string]$encodedArg.value).Trim()
        if ([string]::IsNullOrWhiteSpace($encoded)) {
            return @{ ok = $false; code = 'BAD_ARGS'; error = 'iconBase64 wurde angegeben, ist aber leer.' }
        }
        if ($encoded -match '^data:[^;]+;base64,') { $encoded = $encoded.Substring($encoded.IndexOf(',') + 1) }
        if ($encoded.Length -gt 14000000) {
            return @{ ok = $false; code = 'ICON_TOO_LARGE'; error = 'Das Icon ist zu groß. Arena akzeptiert hier höchstens 10 MiB (PNG/JPEG), bevor Roblox es erhält.' }
        }
        $nameArg = Get-OpenCloudArgumentValue -Arguments $Arguments -Name 'iconFileName'
        $fileName = ''
        if ($nameArg.found) { $fileName = ([string]$nameArg.value).Trim() }
        if ([string]::IsNullOrWhiteSpace($fileName)) {
            return @{ ok = $false; code = 'BAD_ARGS'; error = 'iconFileName ist zusammen mit iconBase64 erforderlich (zum Beispiel "icon.png" oder "icon.jpg").' }
        }
        if ($fileName.Length -gt 128 -or $fileName -match '[\\/\r\n"\0]') {
            return @{ ok = $false; code = 'BAD_ARGS'; error = 'iconFileName darf höchstens 128 Zeichen lang sein und keine Pfadtrenner, Anführungszeichen oder Steuerzeichen enthalten.' }
        }
        $extension = ''
        try { $extension = [System.IO.Path]::GetExtension($fileName).ToLowerInvariant() } catch {}
        $contentType = ''
        if ($extension -eq '.png') { $contentType = 'image/png' }
        elseif ($extension -eq '.jpg' -or $extension -eq '.jpeg') { $contentType = 'image/jpeg' }
        else { return @{ ok = $false; code = 'UNSUPPORTED_ICON_FORMAT'; error = 'Creator-Dashboard-Icons müssen hier PNG oder JPEG sein; SVG und andere Formate werden nicht gesendet.' } }
        $bytes = $null
        try { $bytes = [Convert]::FromBase64String($encoded) } catch {
            return @{ ok = $false; code = 'BAD_ARGS'; error = 'iconBase64 ist kein gültiger Base64-Inhalt.' }
        }
        if ($null -eq $bytes -or $bytes.Length -le 0) { return @{ ok = $false; code = 'BAD_ARGS'; error = 'Das Icon ist leer.' } }
        if ($bytes.Length -gt 10485760) { return @{ ok = $false; code = 'ICON_TOO_LARGE'; error = 'Das Icon ist zu groß. Arena akzeptiert hier höchstens 10 MiB (PNG/JPEG), bevor Roblox es erhält.' } }
        $signatureOk = $false
        if ($extension -eq '.png' -and $bytes.Length -ge 8) {
            $pngSignature = @(137, 80, 78, 71, 13, 10, 26, 10)
            $signatureOk = $true
            for ($i = 0; $i -lt $pngSignature.Count; $i++) { if ([int]$bytes[$i] -ne [int]$pngSignature[$i]) { $signatureOk = $false; break } }
        } elseif (($extension -eq '.jpg' -or $extension -eq '.jpeg') -and $bytes.Length -ge 3) {
            $signatureOk = ([int]$bytes[0] -eq 255 -and [int]$bytes[1] -eq 216 -and [int]$bytes[2] -eq 255)
        }
        if (-not $signatureOk) { return @{ ok = $false; code = 'ICON_FORMAT_MISMATCH'; error = 'Dateiendung und Dateiinhalte des Icons stimmen nicht überein; erwartet wird eine echte PNG- oder JPEG-Datei.' } }
        return @{ ok = $true; supplied = $true; bytes = $bytes; fileName = $fileName; contentType = $contentType }
    }

    function Get-CreatorDashboardFormFields {
        param($Arguments, [string[]]$AllowedFields, [bool]$RequireName = $false)
        $fields = [ordered]@{}
        foreach ($fieldName in $AllowedFields) {
            $arg = Get-OpenCloudArgumentValue -Arguments $Arguments -Name $fieldName
            if (-not $arg.found -or $null -eq $arg.value) { continue }
            if ($fieldName -in @('isForSale','isRegionalPricingEnabled','storePageEnabled')) {
                $booleanValue = $false
                if ($arg.value -is [bool]) { $booleanValue = [bool]$arg.value }
                else {
                    $parsedBoolean = $false
                    if (-not [bool]::TryParse(([string]$arg.value).Trim(), [ref]$parsedBoolean)) {
                        return @{ ok = $false; code = 'BAD_ARGS'; error = ($fieldName + ' muss true oder false sein.') }
                    }
                    $booleanValue = $parsedBoolean
                }
                $fields[$fieldName] = $booleanValue.ToString().ToLowerInvariant()
            } elseif ($fieldName -eq 'price') {
                $price = [long]0
                $rawPrice = ([string]$arg.value).Trim()
                $style = [System.Globalization.NumberStyles]::Integer
                $culture = [System.Globalization.CultureInfo]::InvariantCulture
                if (-not [long]::TryParse($rawPrice, $style, $culture, [ref]$price) -or $price -lt 0) {
                    return @{ ok = $false; code = 'BAD_ARGS'; error = 'price muss eine nichtnegative int64-Ganzzahl sein.' }
                }
                $fields[$fieldName] = [string]$price
            } else {
                if ($arg.value -is [System.Collections.IDictionary] -or $arg.value -is [System.Array]) {
                    return @{ ok = $false; code = 'BAD_ARGS'; error = ($fieldName + ' muss Text sein.') }
                }
                $textValue = [string]$arg.value
                if ($fieldName -eq 'name' -and [string]::IsNullOrWhiteSpace($textValue)) {
                    return @{ ok = $false; code = 'BAD_ARGS'; error = 'name darf nicht leer sein.' }
                }
                if ($textValue.Length -gt 4000) { return @{ ok = $false; code = 'BAD_ARGS'; error = ($fieldName + ' darf höchstens 4000 Zeichen enthalten.') } }
                $fields[$fieldName] = $textValue
            }
        }
        if ($RequireName -and (-not $fields.Contains('name') -or [string]::IsNullOrWhiteSpace([string]$fields['name']))) {
            return @{ ok = $false; code = 'BAD_ARGS'; error = 'name ist für das Erstellen eines Gamepasses/Developer-Produkts erforderlich.' }
        }
        return @{ ok = $true; fields = $fields }
    }

    function Invoke-CreatorDashboardHttp {
        param($Shared, [string]$Action, [string]$Url, [string]$Method, [string]$Key, [string]$JsonBody = '', [System.Collections.IDictionary]$FormFields = $null, [byte[]]$Bytes = $null, [string]$FileName = '', [string]$FileContentType = '', [string]$FileFieldName = 'imageFile', [string[]]$RequiredScopes = @(), [string]$UniverseId = '', [string]$PlaceId = '', [int]$TimeoutSeconds = 35)
        $gate = Assert-OpenCloudToolAccess -Shared $Shared -RequiredScopes $RequiredScopes -What $Action
        if ($gate.ok -ne $true) { return $gate }
        $attempt = Send-OpenCloudHttp -Shared $Shared -Method $Method -Url $Url -Key $Key -JsonBody $JsonBody -FormFields $FormFields -Bytes $Bytes -FileName $FileName -FileContentType $FileContentType -FileFieldName $FileFieldName -TimeoutSeconds $TimeoutSeconds -MaxResponseChars 2000000
        if ([int]$attempt.status -le 0) { return (Get-OpenCloudTransportError -Attempt $attempt -What 'Der Creator-Dashboard-Aufruf') }
        $status = [int]$attempt.status
        $body = [string]$attempt.body
        if ($status -eq 401) {
            return @{ ok = $false; code = 'OPENCLOUD_KEY_REJECTED'; status = $status; action = $Action; error = 'Roblox hat den Open Cloud API-Key beim Creator-Dashboard-Aufruf abgelehnt (HTTP 401).'; robloxResponse = $body; howToFix = 'Prüfe den gespeicherten Key und erstelle ihn bei Bedarf neu. Der Key bleibt verschlüsselt in der Bridge.' }
        }
        if ($status -eq 403) {
            return @{ ok = $false; code = 'OPENCLOUD_SCOPE_MISSING'; status = $status; action = $Action; requiredScopes = @($RequiredScopes); error = ('Roblox verweigert diese Creator-Dashboard-Aktion (HTTP 403). Erforderliche Berechtigungen: ' + (@($RequiredScopes) -join ', ') + '.'); robloxResponse = $body; howToFix = 'Prüfe die angegebenen Scopes am Open-Cloud-Key und die Roblox-Rolle für dieses Erlebnis. Nach einer Rechteänderung den neuen Key in Arena speichern.' }
        }
        if ($status -eq 429) {
            return @{ ok = $false; code = 'OPENCLOUD_RATE_LIMITED'; status = $status; action = $Action; error = 'Roblox drosselt Open-Cloud-Anfragen (HTTP 429). Arena hat nicht automatisch wiederholt.'; robloxResponse = $body; howToFix = 'Warte, bevor du dieselbe Anfrage erneut startest; wiederhole nicht in einer engen Schleife.' }
        }
        if ($status -ge 500) {
            return @{ ok = $false; code = 'OPENCLOUD_SERVER_ERROR'; status = $status; action = $Action; error = ('Roblox meldet einen Serverfehler (HTTP ' + [string]$status + ') beim Creator-Dashboard-Aufruf.'); robloxResponse = $body; howToFix = 'Roblox antwortet gerade mit einem Serverfehler. Nicht automatisch wiederholen; später erneut versuchen.' }
        }
        if ($status -eq 409) {
            return @{ ok = $false; code = 'CREATOR_DASHBOARD_CONFLICT'; status = $status; action = $Action; error = 'Roblox meldet einen Konflikt (HTTP 409). Beim Place-Update kann das bedeuten, dass der Place in einer aktiven Team-Create-Sitzung geöffnet ist; es wurde nichts automatisch wiederholt.'; robloxResponse = $body; howToFix = 'Beende/prüfe eine aktive Team-Create-Sitzung und kontrolliere den aktuellen Dashboard-Zustand, bevor du die Änderung erneut sendest.' }
        }
        if ($status -eq 404) {
            return @{ ok = $false; code = 'CREATOR_DASHBOARD_NOT_FOUND'; status = $status; action = $Action; error = 'Roblox hat den aktiven Place, Universe oder das angeforderte Monetarisierungsprodukt nicht gefunden (HTTP 404).'; robloxResponse = $body; howToFix = 'Prüfe, ob das Studio-Fenster mit dem richtigen bereits veröffentlichten Place verbunden ist und ob die Produkt-ID zu diesem Spiel gehört.' }
        }
        if ($status -lt 200 -or $status -gt 299) {
            return @{ ok = $false; code = 'CREATOR_DASHBOARD_REJECTED'; status = $status; action = $Action; error = ('Roblox hat die Creator-Dashboard-Aktion abgelehnt (HTTP ' + [string]$status + ').'); robloxResponse = $body; howToFix = 'Prüfe die Roblox-Antwort in robloxResponse. Arena hat nur die dokumentierte Aktion gesendet und nicht automatisch wiederholt.' }
        }
        if ($attempt.bodyTruncated -eq $true) {
            return @{ ok = $false; code = 'CREATOR_DASHBOARD_RESPONSE_TOO_LARGE'; status = $status; action = $Action; error = 'Die erfolgreiche Roblox-Antwort überschritt die lokale 2-MiB-Antwortgrenze und wurde abgeschnitten; Arena kann sie nicht sicher als JSON auswerten.'; robloxResponse = $body }
        }
        $parsed = $null
        if (-not [string]::IsNullOrWhiteSpace($body)) {
            try { $parsed = $body | ConvertFrom-Json } catch {
                return @{ ok = $false; code = 'OPENCLOUD_BAD_RESPONSE'; status = $status; action = $Action; error = 'Roblox antwortete erfolgreich, aber der Antwortinhalt war kein lesbares JSON.'; robloxResponse = $body }
            }
        }
        return @{
            ok = $true
            code = 'CREATOR_DASHBOARD_OK'
            action = $Action
            status = $status
            transport = [string]$attempt.transport
            universeId = $UniverseId
            placeId = $PlaceId
            requiredScopes = @($RequiredScopes)
            result = $parsed
            note = 'Direkte Antwort der offiziellen Roblox Open Cloud API. Es wurde kein Creator-Hub-Cookie-Endpunkt verwendet.'
        }
    }

    function Invoke-CreatorDashboardTool {
        # Nur Open-Cloud-Endpunkte, nur das derzeit verbundene Studio-Spiel.
        # Creator-Dashboard ist ein ausdrückliches Opt-in; diese Prüfung bleibt
        # lokal im Serverwerkzeug, weil der Server-Dispatch vor writeTools liegt.
        param($Shared, [string]$SessionId, $Arguments)
        $actionArg = Get-OpenCloudArgumentValue -Arguments $Arguments -Name 'action'
        $action = ''
        if ($actionArg.found) { $action = ([string]$actionArg.value).Trim().ToLowerInvariant() }
        $actions = @('universe_get','universe_update','place_get','place_update','gamepass_list','gamepass_get','gamepass_create','gamepass_update','developer_product_list','developer_product_get','developer_product_create','developer_product_update')
        if ($action -notin $actions) {
            return @{ ok = $false; code = 'BAD_ARGS'; error = 'Ungültige action. Erlaubt: ' + ($actions -join ', ') + '.' }
        }
        # Version 7.6.0: Der lokale Opt-in-Schalter ist entfernt. Was Arena
        # mit dem Open-Cloud-Schluessel darf, entscheidet allein der
        # Schluessel: fehlen Scopes, antwortet Roblox 403 und die Bridge
        # nennt den fehlenden Scope ehrlich (OPENCLOUD_SCOPE_MISSING).
        $managedPricingArg = Get-OpenCloudArgumentValue -Arguments $Arguments -Name 'isManagedPricingEnabled'
        if ($managedPricingArg.found -and $null -ne $managedPricingArg.value) {
            return @{ ok = $false; code = 'UNSUPPORTED_FIELD'; error = 'isManagedPricingEnabled ist kein Feld der dokumentierten Creator-Dashboard-Open-Cloud-Endpunkte. Es wurde keine Anfrage an Roblox gesendet.' }
        }
        $writeActions = @('universe_update','place_update','gamepass_create','gamepass_update','developer_product_create','developer_product_update')
        $accessMode = 'readonly'
        try { [void]$Shared.AccessModes.TryGetValue([string]$SessionId, [ref]$accessMode) } catch {}
        if ($action -in $writeActions -and [string]$accessMode -ne 'readwrite') {
            return @{ ok = $false; code = 'READONLY_TOKEN'; error = ('Die Aktion ' + $action + ' ändert Roblox-Creator-Dashboard-Daten, aber diese Studio-Sitzung ist auf „nur lesen“ gestellt. Es wurde nichts gesendet.'); howToFix = 'Der Nutzer muss für diese Place-Sitzung in der Bridge Vollzugriff einschalten. Die Creator-Dashboard-Einstellung ersetzt den Read-only-Schutz nicht.' }
        }
        foreach ($targetField in @('universeId','placeId','gameId','targetPlace')) {
            $targetArg = Get-OpenCloudArgumentValue -Arguments $Arguments -Name $targetField
            if ($targetArg.found -and $null -ne $targetArg.value -and -not [string]::IsNullOrWhiteSpace([string]$targetArg.value)) {
                return @{ ok = $false; code = 'BAD_ARGS'; error = ($targetField + ' darf nicht angegeben werden. Creator-Dashboard-Werkzeuge zielen ausschließlich auf die aktuell verbundene Studio-Sitzung; es werden keine fremden IDs angenommen.') }
            }
        }
        $entry = $null
        try { $entry = Get-SessionEntry ([string]$SessionId) } catch {}
        if ($null -eq $entry) {
            return @{ ok = $false; code = 'NO_ACTIVE_STUDIO_PLACE'; error = 'Es gibt keine aktive Studio-Sitzung für dieses Token. Es wurde keine Anfrage an Roblox gesendet.' }
        }
        $universeId = ([string]$entry.gameId).Trim()
        $placeId = ([string]$entry.placeId).Trim()
        if ($universeId -notmatch '^[1-9][0-9]{0,19}$' -or $placeId -notmatch '^[1-9][0-9]{0,19}$') {
            return @{ ok = $false; code = 'PUBLISHED_PLACE_REQUIRED'; error = 'Die aktive Studio-Sitzung meldet keine gültige Universe-ID und Place-ID. Creator-Dashboard-Verwaltung ist nur für einen bereits veröffentlichten Place mit echten IDs verfügbar; Arena veröffentlicht oder erstellt keine Places.'; howToFix = 'Veröffentliche/speichere den Place zuerst in Roblox Studio, verbinde dieses Fenster erneut und versuche es dann.' }
        }
        $family = 'universe'
        if ($action -like 'place_*') { $family = 'universe.place' }
        elseif ($action -like 'gamepass_*') { $family = 'game-pass' }
        elseif ($action -like 'developer_product_*') { $family = 'developer-product' }
        $gate = Assert-OpenCloudToolAccess -Shared $Shared -What ('creator_dashboard:' + $action)
        if ($gate.ok -ne $true) { return $gate }
        $config = Get-OpenCloudConfig $Shared
        $base = 'https://apis.roblox.com'
        $url = ''
        $method = 'GET'
        $jsonBody = ''
        $formFields = $null
        $iconBytes = $null
        $iconFileName = ''
        $iconContentType = ''
        $requiredScopes = @()
        switch ($action) {
            'universe_get' {
                $url = $base + '/cloud/v2/universes/' + $universeId
            }
            'universe_update' {
                $fields = [ordered]@{}
                foreach ($fieldName in @('displayName','description')) {
                    $arg = Get-OpenCloudArgumentValue -Arguments $Arguments -Name $fieldName
                    if (-not $arg.found -or $null -eq $arg.value) { continue }
                    if ($arg.value -is [System.Collections.IDictionary] -or $arg.value -is [System.Array]) { return @{ ok = $false; code = 'BAD_ARGS'; error = ($fieldName + ' muss Text sein.') } }
                    $textValue = [string]$arg.value
                    if ($fieldName -eq 'displayName' -and [string]::IsNullOrWhiteSpace($textValue)) { return @{ ok = $false; code = 'BAD_ARGS'; error = 'displayName darf nicht leer sein.' } }
                    if ($textValue.Length -gt 4000) { return @{ ok = $false; code = 'BAD_ARGS'; error = ($fieldName + ' darf höchstens 4000 Zeichen enthalten.') } }
                    $fields[$fieldName] = $textValue
                }
                if ($fields.Count -eq 0) { return @{ ok = $false; code = 'BAD_ARGS'; error = 'universe_update benötigt mindestens displayName oder description.' } }
                $updateMask = [Uri]::EscapeDataString(($fields.Keys -join ','))
                $url = $base + '/cloud/v2/universes/' + $universeId + '?updateMask=' + $updateMask
                $method = 'PATCH'
                $jsonBody = ConvertTo-Json -InputObject $fields -Compress -Depth 6
                $requiredScopes = @('universe:write')
            }
            'place_get' {
                $url = $base + '/cloud/v2/universes/' + $universeId + '/places/' + $placeId
            }
            'place_update' {
                $fields = [ordered]@{}
                foreach ($fieldName in @('displayName','description')) {
                    $arg = Get-OpenCloudArgumentValue -Arguments $Arguments -Name $fieldName
                    if (-not $arg.found -or $null -eq $arg.value) { continue }
                    if ($arg.value -is [System.Collections.IDictionary] -or $arg.value -is [System.Array]) { return @{ ok = $false; code = 'BAD_ARGS'; error = ($fieldName + ' muss Text sein.') } }
                    $textValue = [string]$arg.value
                    if ($fieldName -eq 'displayName' -and [string]::IsNullOrWhiteSpace($textValue)) { return @{ ok = $false; code = 'BAD_ARGS'; error = 'displayName darf nicht leer sein.' } }
                    if ($textValue.Length -gt 4000) { return @{ ok = $false; code = 'BAD_ARGS'; error = ($fieldName + ' darf höchstens 4000 Zeichen enthalten.') } }
                    $fields[$fieldName] = $textValue
                }
                if ($fields.Count -eq 0) { return @{ ok = $false; code = 'BAD_ARGS'; error = 'place_update benötigt mindestens displayName oder description.' } }
                $updateMask = [Uri]::EscapeDataString(($fields.Keys -join ','))
                $url = $base + '/cloud/v2/universes/' + $universeId + '/places/' + $placeId + '?updateMask=' + $updateMask
                $method = 'PATCH'
                $jsonBody = ConvertTo-Json -InputObject $fields -Compress -Depth 6
                $requiredScopes = @('universe.place:write')
            }
            { $_ -like 'gamepass_*' } {
                $root = $base + '/game-passes/v1/universes/' + $universeId + '/game-passes'
                if ($action -eq 'gamepass_list') {
                    $pageSize = 50
                    $pageSizeArg = Get-OpenCloudArgumentValue -Arguments $Arguments -Name 'pageSize'
                    if ($pageSizeArg.found -and $null -ne $pageSizeArg.value) {
                        $parsedPageSize = 0
                        if (-not [int]::TryParse(([string]$pageSizeArg.value), [ref]$parsedPageSize) -or $parsedPageSize -lt 1 -or $parsedPageSize -gt 100) { return @{ ok = $false; code = 'BAD_ARGS'; error = 'pageSize muss eine ganze Zahl von 1 bis 100 sein.' } }
                        $pageSize = $parsedPageSize
                    }
                    $url = $root + '/creator?pageSize=' + [string]$pageSize
                    $pageTokenArg = Get-OpenCloudArgumentValue -Arguments $Arguments -Name 'pageToken'
                    if ($pageTokenArg.found -and -not [string]::IsNullOrWhiteSpace([string]$pageTokenArg.value)) { $url += '&pageToken=' + [Uri]::EscapeDataString([string]$pageTokenArg.value) }
                    $requiredScopes = @('game-pass:read')
                    break
                }
                if ($action -eq 'gamepass_get' -or $action -eq 'gamepass_update') {
                    $idArg = Get-OpenCloudArgumentValue -Arguments $Arguments -Name 'gamePassId'
                    if (-not $idArg.found) { $idArg = Get-OpenCloudArgumentValue -Arguments $Arguments -Name 'id' }
                    $productId = ''
                    if ($idArg.found) { $productId = ([string]$idArg.value).Trim() }
                    if ($productId -notmatch '^[1-9][0-9]{0,19}$') { return @{ ok = $false; code = 'BAD_ARGS'; error = 'gamePassId/id muss eine positive numerische Roblox-ID sein.' } }
                    $root += '/' + $productId
                    if ($action -eq 'gamepass_get') {
                        $url = $root + '/creator'
                        $requiredScopes = @('game-pass:read')
                        break
                    }
                    $url = $root
                    $method = 'PATCH'
                    $requiredScopes = @('game-pass:write')
                } else {
                    $url = $root
                    $method = 'POST'
                    $requiredScopes = @('game-pass:write')
                }
                $allowed = @('name','description','isForSale','price','isRegionalPricingEnabled')
                $formResult = Get-CreatorDashboardFormFields -Arguments $Arguments -AllowedFields $allowed -RequireName ($action -eq 'gamepass_create')
                if ($formResult.ok -ne $true) { return $formResult }
                $formFields = $formResult.fields
                $image = Get-CreatorDashboardImage -Arguments $Arguments
                if ($image.ok -ne $true) { return $image }
                $iconNameArg = Get-OpenCloudArgumentValue -Arguments $Arguments -Name 'iconFileName'
                if (-not $image.supplied -and $iconNameArg.found -and -not [string]::IsNullOrWhiteSpace([string]$iconNameArg.value)) { return @{ ok = $false; code = 'BAD_ARGS'; error = 'iconFileName erfordert iconBase64.' } }
                if ($image.supplied) { $iconBytes = $image.bytes; $iconFileName = $image.fileName; $iconContentType = $image.contentType }
                if ($action -eq 'gamepass_update' -and $formFields.Count -eq 0 -and -not $image.supplied) { return @{ ok = $false; code = 'BAD_ARGS'; error = 'gamepass_update benötigt mindestens ein änderbares Feld oder iconBase64.' } }
            }
            { $_ -like 'developer_product_*' } {
                $root = $base + '/developer-products/v2/universes/' + $universeId + '/developer-products'
                if ($action -eq 'developer_product_list') {
                    $pageSize = 50
                    $pageSizeArg = Get-OpenCloudArgumentValue -Arguments $Arguments -Name 'pageSize'
                    if ($pageSizeArg.found -and $null -ne $pageSizeArg.value) {
                        $parsedPageSize = 0
                        if (-not [int]::TryParse(([string]$pageSizeArg.value), [ref]$parsedPageSize) -or $parsedPageSize -lt 1 -or $parsedPageSize -gt 100) { return @{ ok = $false; code = 'BAD_ARGS'; error = 'pageSize muss eine ganze Zahl von 1 bis 100 sein.' } }
                        $pageSize = $parsedPageSize
                    }
                    $url = $root + '/creator?pageSize=' + [string]$pageSize
                    $pageTokenArg = Get-OpenCloudArgumentValue -Arguments $Arguments -Name 'pageToken'
                    if ($pageTokenArg.found -and -not [string]::IsNullOrWhiteSpace([string]$pageTokenArg.value)) { $url += '&pageToken=' + [Uri]::EscapeDataString([string]$pageTokenArg.value) }
                    $requiredScopes = @('developer-product:read')
                    break
                }
                if ($action -eq 'developer_product_get' -or $action -eq 'developer_product_update') {
                    $idArg = Get-OpenCloudArgumentValue -Arguments $Arguments -Name 'productId'
                    if (-not $idArg.found) { $idArg = Get-OpenCloudArgumentValue -Arguments $Arguments -Name 'id' }
                    $productId = ''
                    if ($idArg.found) { $productId = ([string]$idArg.value).Trim() }
                    if ($productId -notmatch '^[1-9][0-9]{0,19}$') { return @{ ok = $false; code = 'BAD_ARGS'; error = 'productId/id muss eine positive numerische Roblox-ID sein.' } }
                    $root += '/' + $productId
                    if ($action -eq 'developer_product_get') {
                        $url = $root + '/creator'
                        $requiredScopes = @('developer-product:read')
                        break
                    }
                    $url = $root
                    $method = 'PATCH'
                    $requiredScopes = @('developer-product:write')
                } else {
                    $url = $root
                    $method = 'POST'
                    $requiredScopes = @('developer-product:write')
                }
                $allowed = @('name','description','isForSale','price','isRegionalPricingEnabled')
                if ($action -eq 'developer_product_update') { $allowed += 'storePageEnabled' }
                $formResult = Get-CreatorDashboardFormFields -Arguments $Arguments -AllowedFields $allowed -RequireName ($action -eq 'developer_product_create')
                if ($formResult.ok -ne $true) { return $formResult }
                $formFields = $formResult.fields
                $image = Get-CreatorDashboardImage -Arguments $Arguments
                if ($image.ok -ne $true) { return $image }
                $iconNameArg = Get-OpenCloudArgumentValue -Arguments $Arguments -Name 'iconFileName'
                if (-not $image.supplied -and $iconNameArg.found -and -not [string]::IsNullOrWhiteSpace([string]$iconNameArg.value)) { return @{ ok = $false; code = 'BAD_ARGS'; error = 'iconFileName erfordert iconBase64.' } }
                if ($image.supplied) { $iconBytes = $image.bytes; $iconFileName = $image.fileName; $iconContentType = $image.contentType }
                if ($action -eq 'developer_product_update' -and $formFields.Count -eq 0 -and -not $image.supplied) { return @{ ok = $false; code = 'BAD_ARGS'; error = 'developer_product_update benötigt mindestens ein änderbares Feld oder iconBase64.' } }
            }
        }
        return (Invoke-CreatorDashboardHttp -Shared $Shared -Action $action -Url $url -Method $method -Key ([string]$config.key) -JsonBody $jsonBody -FormFields $formFields -Bytes $iconBytes -FileName $iconFileName -FileContentType $iconContentType -FileFieldName 'imageFile' -RequiredScopes $requiredScopes -UniverseId $universeId -PlaceId $placeId)
    }

    function Invoke-DatastoreHttp {
        # Version 7.6.0: EIN Open-Cloud-Aufruf fuer das Datastore-Werkzeug.
        # Fehler werden wie ueberall ehrlich weitergereicht: Status, Scope und
        # die unveraenderte Roblox-Antwort.
        param($Shared, [string]$Action, [string]$Url, [string]$Method, [string]$Key, [string]$JsonBody = '', [string[]]$RequiredScopes = @(), [string]$UniverseId = '', [int]$TimeoutSeconds = 35)
        $gate = Assert-OpenCloudToolAccess -Shared $Shared -RequiredScopes $RequiredScopes -What $Action
        if ($gate.ok -ne $true) { return $gate }
        $attempt = Send-OpenCloudHttp -Shared $Shared -Method $Method -Url $Url -Key $Key -JsonBody $JsonBody -TimeoutSeconds $TimeoutSeconds -MaxResponseChars 2000000
        if ([int]$attempt.status -le 0) { return (Get-OpenCloudTransportError -Attempt $attempt -What 'Der Datastore-Aufruf') }
        $status = [int]$attempt.status
        $body = [string]$attempt.body
        if ($status -eq 401) {
            return @{ ok = $false; code = 'OPENCLOUD_KEY_REJECTED'; status = $status; action = $Action; error = 'Roblox hat den Open Cloud API-Key beim Datastore-Aufruf abgelehnt (HTTP 401).'; robloxResponse = $body; howToFix = 'Pruefe den gespeicherten Key und erstelle ihn bei Bedarf neu (Tutorial in den Einstellungen). Der Key bleibt verschluesselt in der Bridge.' }
        }
        if ($status -eq 403) {
            return @{ ok = $false; code = 'OPENCLOUD_SCOPE_MISSING'; status = $status; action = $Action; requiredScopes = @($RequiredScopes); error = ('Roblox verweigert diese Datastore-Aktion (HTTP 403). Erforderliche Berechtigungen: ' + (@($RequiredScopes) -join ', ') + '.'); robloxResponse = $body; howToFix = 'Der Schluessel braucht die genannten Datastore-Scopes (siehe Berechtigungs-Fenster beim Speichern des Keys). Nach einer Rechteaenderung den neuen Key in Arena speichern.' }
        }
        if ($status -eq 404) {
            return @{ ok = $false; code = 'DATASTORE_NOT_FOUND'; status = $status; action = $Action; error = ('Roblox kennt diesen Datastore/Eintrag nicht (HTTP 404).'); robloxResponse = $body; howToFix = 'Pruefe Name und Scope: datastore { action = "list_datastores" } nennt die echten Stores des verbundenen Spiels, list_entries die echten Eintraege (engine-Scope ist "global").' }
        }
        if ($status -eq 429) {
            return @{ ok = $false; code = 'OPENCLOUD_RATE_LIMITED'; status = $status; action = $Action; error = 'Roblox meldet 429 (Rate Limit) beim Datastore-Aufruf.'; robloxResponse = $body; howToFix = 'Warte einige Minuten, bevor du es erneut versuchst.' }
        }
        if ($status -ge 500) {
            return @{ ok = $false; code = 'OPENCLOUD_SERVER_ERROR'; status = $status; action = $Action; error = ('Roblox meldet einen Serverfehler (HTTP ' + [string]$status + ') beim Datastore-Aufruf.'); robloxResponse = $body; howToFix = 'Das liegt nicht am Schluessel. Versuche es spaeter erneut.' }
        }
        if ($status -lt 200 -or $status -gt 299) {
            return @{ ok = $false; code = 'DATASTORE_REJECTED'; status = $status; action = $Action; error = ('Roblox hat den Datastore-Aufruf abgelehnt (HTTP ' + [string]$status + ').'); robloxResponse = $body; howToFix = 'Die vollstaendige Roblox-Antwort steht in robloxResponse - melde sie dem Nutzer unverfaelscht.' }
        }
        $parsed = $null
        if (-not [string]::IsNullOrWhiteSpace($body)) { try { $parsed = $body | ConvertFrom-Json } catch { $parsed = $null } }
        return @{ ok = $true; status = $status; action = $Action; universeId = $UniverseId; requiredScopes = @($RequiredScopes); result = $parsed; robloxResponse = $body }
    }

    function Invoke-DatastoreTool {
        # Version 7.6.0: DataStores des VERBUNDENEN Spiels ueber die offizielle
        # STABILE Cloud-v2-API (/cloud/v2/universes/{u}/data-stores/...).
        # Wie beim Creator-Dashboard gilt: NUR die aktive Studio-Sitzung,
        # keine fremden Ziel-IDs, Read-only sperrt Schreibaktionen, und die
        # Scopes des Schluessels sind die einzige Berechtigungsquelle.
        param($Shared, [string]$SessionId, $Arguments)
        $actionArg = Get-OpenCloudArgumentValue -Arguments $Arguments -Name 'action'
        $action = ''
        if ($actionArg.found) { $action = ([string]$actionArg.value).Trim().ToLowerInvariant() }
        $actions = @('list_datastores','list_entries','get_entry','create_entry','update_entry','increment_entry','delete_entry','list_versions')
        if ($action -notin $actions) {
            return @{ ok = $false; code = 'BAD_ARGS'; error = 'Ungueltige action. Erlaubt: ' + ($actions -join ', ') + '.' }
        }
        $writeActions = @('create_entry','update_entry','increment_entry','delete_entry')
        $accessMode = 'readonly'
        try { [void]$Shared.AccessModes.TryGetValue([string]$SessionId, [ref]$accessMode) } catch {}
        if ($action -in $writeActions -and [string]$accessMode -ne 'readwrite') {
            return @{ ok = $false; code = 'READONLY_TOKEN'; error = ('Die Aktion ' + $action + ' aendert Spielerdaten, aber diese Studio-Sitzung ist auf „nur lesen“ gestellt. Es wurde nichts gesendet.'); howToFix = 'Der Nutzer muss fuer diese Place-Sitzung in der Bridge Vollzugriff einschalten.' }
        }
        foreach ($targetField in @('universeId','placeId','gameId','targetPlace')) {
            $targetArg = Get-OpenCloudArgumentValue -Arguments $Arguments -Name $targetField
            if ($targetArg.found -and $null -ne $targetArg.value -and -not [string]::IsNullOrWhiteSpace([string]$targetArg.value)) {
                return @{ ok = $false; code = 'BAD_ARGS'; error = ($targetField + ' darf nicht angegeben werden. Das Datastore-Werkzeug zielt ausschliesslich auf die aktuell verbundene Studio-Sitzung; es werden keine fremden IDs angenommen.') }
            }
        }
        $entry = $null
        try { $entry = Get-SessionEntry ([string]$SessionId) } catch {}
        if ($null -eq $entry) {
            return @{ ok = $false; code = 'NO_ACTIVE_STUDIO_PLACE'; error = 'Es gibt keine aktive Studio-Sitzung fuer dieses Token. Es wurde keine Anfrage an Roblox gesendet.' }
        }
        $universeId = ([string]$entry.gameId).Trim()
        if ($universeId -notmatch '^[1-9][0-9]{0,19}$') {
            return @{ ok = $false; code = 'PUBLISHED_PLACE_REQUIRED'; error = 'Die aktive Studio-Sitzung meldet keine gueltige Universe-ID. Datastore-Zugriff ueber Open Cloud ist nur fuer einen bereits veroeffentlichten Place mit echter Universe-ID verfuegbar.'; howToFix = 'Veroeffentliche/speichere den Place zuerst in Roblox Studio, verbinde dieses Fenster erneut und versuche es dann.' }
        }
        $gate = Assert-OpenCloudToolAccess -Shared $Shared -What 'datastore'
        if ($gate.ok -ne $true) { return $gate }
        $config = Get-OpenCloudConfig $Shared
        $base = 'https://apis.roblox.com/cloud/v2/universes/' + $universeId
        # Datastore-Ziel: Name (empfohlen, wie in Studio) oder die ID aus
        # list_datastores. Beides wird als Pfadsegment verwendet - genau wie
        # im offiziellen Roblox-Beispiel (dataStoreId = 'Inventory').
        $datastoreName = ''
        $nameArg = Get-OpenCloudArgumentValue -Arguments $Arguments -Name 'datastoreName'
        if ($nameArg.found -and $null -ne $nameArg.value) { $datastoreName = ([string]$nameArg.value).Trim() }
        if ([string]::IsNullOrWhiteSpace($datastoreName)) {
            $idArg = Get-OpenCloudArgumentValue -Arguments $Arguments -Name 'datastoreId'
            if ($idArg.found -and $null -ne $idArg.value) { $datastoreName = ([string]$idArg.value).Trim() }
        }
        $scopeName = 'global'
        $scopeArg = Get-OpenCloudArgumentValue -Arguments $Arguments -Name 'scope'
        if ($scopeArg.found -and $null -ne $scopeArg.value -and -not [string]::IsNullOrWhiteSpace([string]$scopeArg.value)) { $scopeName = ([string]$scopeArg.value).Trim() }
        $entryKey = ''
        foreach ($keyField in @('entryId','entryKey','key')) {
            $keyArg = Get-OpenCloudArgumentValue -Arguments $Arguments -Name $keyField
            if ($keyArg.found -and $null -ne $keyArg.value -and -not [string]::IsNullOrWhiteSpace([string]$keyArg.value)) { $entryKey = ([string]$keyArg.value); break }
        }
        $needsStore = ($action -ne 'list_datastores')
        $needsEntry = ($action -in @('get_entry','update_entry','increment_entry','delete_entry','list_versions'))
        if ($needsStore -and [string]::IsNullOrWhiteSpace($datastoreName)) {
            return @{ ok = $false; code = 'BAD_ARGS'; error = ($action + ' braucht datastoreName (z. B. "PlayerData") oder datastoreId aus list_datastores.') }
        }
        if ($needsEntry -and [string]::IsNullOrWhiteSpace($entryKey)) {
            return @{ ok = $false; code = 'BAD_ARGS'; error = ($action + ' braucht entryId (den Schluessel des Eintrags, z. B. "Player_12345").') }
        }
        if ($needsEntry -and $entryKey.Length -gt 50) {
            return @{ ok = $false; code = 'BAD_ARGS'; error = 'entryId darf hoechstens 50 Zeichen lang sein (Roblox-Grenze).' }
        }
        $storeSegment = [Uri]::EscapeDataString($datastoreName)
        $scopeSegment = [Uri]::EscapeDataString($scopeName)
        $entriesRoot = $base + '/data-stores/' + $storeSegment + '/scopes/' + $scopeSegment + '/entries'
        $entrySegment = ''
        if ($needsEntry) { $entrySegment = [Uri]::EscapeDataString($entryKey) }
        $pageQuery = ''
        $pageSize = 50
        $pageSizeArg = Get-OpenCloudArgumentValue -Arguments $Arguments -Name 'pageSize'
        if ($pageSizeArg.found -and $null -ne $pageSizeArg.value) {
            $parsedPageSize = 0
            if (-not [int]::TryParse(([string]$pageSizeArg.value), [ref]$parsedPageSize) -or $parsedPageSize -lt 1 -or $parsedPageSize -gt 256) { return @{ ok = $false; code = 'BAD_ARGS'; error = 'pageSize muss eine ganze Zahl von 1 bis 256 sein.' } }
            $pageSize = $parsedPageSize
        }
        $pageQuery = 'maxPageSize=' + [string]$pageSize
        $pageTokenArg = Get-OpenCloudArgumentValue -Arguments $Arguments -Name 'pageToken'
        if ($pageTokenArg.found -and $null -ne $pageTokenArg.value -and -not [string]::IsNullOrWhiteSpace([string]$pageTokenArg.value)) {
            $pageQuery = $pageQuery + '&pageToken=' + [Uri]::EscapeDataString(([string]$pageTokenArg.value))
        }
        $url = ''
        $method = 'GET'
        $jsonBody = ''
        $requiredScopes = @()
        switch ($action) {
            'list_datastores' {
                $showDeleted = ''
                $showDeletedArg = Get-OpenCloudArgumentValue -Arguments $Arguments -Name 'showDeleted'
                if ($showDeletedArg.found -and $null -ne $showDeletedArg.value -and ([string]$showDeletedArg.value).ToLowerInvariant() -eq 'true') { $showDeleted = '&showDeleted=true' }
                $url = $base + '/data-stores?' + $pageQuery + $showDeleted
                $requiredScopes = @('universe-datastores.control:list')
            }
            'list_entries' {
                $url = $entriesRoot + '?' + $pageQuery
                $filterArg = Get-OpenCloudArgumentValue -Arguments $Arguments -Name 'filter'
                if ($filterArg.found -and $null -ne $filterArg.value -and -not [string]::IsNullOrWhiteSpace([string]$filterArg.value)) {
                    $url = $url + '&filter=' + [Uri]::EscapeDataString(([string]$filterArg.value))
                }
                $requiredScopes = @('universe-datastores.objects:list')
            }
            'get_entry' {
                $url = $entriesRoot + '/' + $entrySegment
                $requiredScopes = @('universe-datastores.objects:read')
            }
            'create_entry' {
                $valueArg = Get-OpenCloudArgumentValue -Arguments $Arguments -Name 'value'
                $valueJsonArg = Get-OpenCloudArgumentValue -Arguments $Arguments -Name 'valueJson'
                if ((-not $valueArg.found -or $null -eq $valueArg.value) -and (-not $valueJsonArg.found -or $null -eq $valueJsonArg.value)) {
                    return @{ ok = $false; code = 'BAD_ARGS'; error = 'create_entry braucht value (JSON-Wert) oder valueJson (JSON-Text).' }
                }
                $url = $entriesRoot + '?id=' + [Uri]::EscapeDataString($entryKey)
                $method = 'POST'
                $jsonBody = (Get-DatastoreValueBody -ValueArg $valueArg -ValueJsonArg $valueJsonArg)
                if ($jsonBody.StartsWith('ERR:')) { return @{ ok = $false; code = 'BAD_ARGS'; error = $jsonBody.Substring(4) } }
                $requiredScopes = @('universe-datastores.objects:create')
            }
            'update_entry' {
                $valueArg = Get-OpenCloudArgumentValue -Arguments $Arguments -Name 'value'
                $valueJsonArg = Get-OpenCloudArgumentValue -Arguments $Arguments -Name 'valueJson'
                if ((-not $valueArg.found -or $null -eq $valueArg.value) -and (-not $valueJsonArg.found -or $null -eq $valueJsonArg.value)) {
                    return @{ ok = $false; code = 'BAD_ARGS'; error = 'update_entry braucht value (JSON-Wert) oder valueJson (JSON-Text).' }
                }
                $url = $entriesRoot + '/' + $entrySegment
                $method = 'PATCH'
                $jsonBody = (Get-DatastoreValueBody -ValueArg $valueArg -ValueJsonArg $valueJsonArg)
                if ($jsonBody.StartsWith('ERR:')) { return @{ ok = $false; code = 'BAD_ARGS'; error = $jsonBody.Substring(4) } }
                $requiredScopes = @('universe-datastores.objects:update')
            }
            'increment_entry' {
                $amountArg = Get-OpenCloudArgumentValue -Arguments $Arguments -Name 'amount'
                if (-not $amountArg.found -or $null -eq $amountArg.value) {
                    $amountArg = Get-OpenCloudArgumentValue -Arguments $Arguments -Name 'by'
                }
                $amount = 0.0
                $rawAmount = ''
                if ($amountArg.found -and $null -ne $amountArg.value) { $rawAmount = ([string]$amountArg.value).Trim() }
                if (-not [double]::TryParse($rawAmount, [System.Globalization.NumberStyles]::Float, [System.Globalization.CultureInfo]::InvariantCulture, [ref]$amount)) {
                    return @{ ok = $false; code = 'BAD_ARGS'; error = 'increment_entry braucht amount als Zahl (z. B. 1, -5 oder 2.5).' }
                }
                $url = $entriesRoot + '/' + $entrySegment + ':increment'
                $method = 'POST'
                $jsonBody = (@{ amount = $amount } | ConvertTo-Json -Compress -Depth 4)
                $requiredScopes = @('universe-datastores.objects:create','universe-datastores.objects:update')
            }
            'delete_entry' {
                $url = $entriesRoot + '/' + $entrySegment
                $method = 'DELETE'
                $requiredScopes = @('universe-datastores.objects:delete')
            }
            'list_versions' {
                $url = $entriesRoot + '/' + $entrySegment + ':listRevisions?' + $pageQuery
                $requiredScopes = @('universe-datastores.versions:list')
            }
        }
        $response = (Invoke-DatastoreHttp -Shared $Shared -Action $action -Url $url -Method $method -Key ([string]$config.key) -JsonBody $jsonBody -RequiredScopes $requiredScopes -UniverseId $universeId)
        if ($response.ok) {
            $response.datastoreName = $datastoreName
            $response.scope = $scopeName
            $response.entryId = $entryKey
        }
        return $response
    }

    function Get-DatastoreValueBody {
        # value (beliebiger JSON-Wert) ODER valueJson (fertiger JSON-Text).
        # Ergebnis ist der Request-Body { "value": ... } oder "ERR:..." fuer
        # ungueltige Eingaben.
        param($ValueArg, $ValueJsonArg)
        if ($ValueJsonArg.found -and $null -ne $ValueJsonArg.value) {
            $rawJson = ([string]$ValueJsonArg.value)
            try { $null = $rawJson | ConvertFrom-Json } catch { return 'ERR:valueJson ist kein gueltiger JSON-Text.' }
            return ('{"value":' + $rawJson + '}')
        }
        if ($ValueArg.found -and $null -ne $ValueArg.value) {
            try {
                return (@{ value = $ValueArg.value } | ConvertTo-Json -Compress -Depth 32)
            } catch { return ('ERR:value konnte nicht als JSON serialisiert werden: ' + $_.Exception.Message) }
        }
        return 'ERR:weder value noch valueJson gefunden.'
    }

    function Resolve-OpenCloudCreatorFromKey {
        # Version 7.5.6: Key-Resource als Rueckfall, falls Studio keine
        # angemeldete Nutzer-ID meldet. Roblox nennt im Introspect die
        # Ressourcen (userId/groupId) der Scopes.
        # Reihenfolge:
        # 1) Genau eine Gruppe -> Gruppe, sonst genau ein Nutzer -> Nutzer.
        # 2) Mehrere konkrete Ressourcen -> erste konkrete nehmen.
        # 3) Eine Seite steht auf "*" (alle Ressourcen) UND die andere nennt
        #    nichts Konkretes -> Fallback auf authorizedUserId (User, der den
        #    Schluessel erstellt hat - genau der, fuer den die Assets dann
        #    auch tatsaechlich gehoeren, auch wenn der Schluessel von einer
        #    Gruppe aus agiert).
        # 4) Wenn authorizedUserId fehlt/0/leer ist UND die Scopes keine
        #    konkrete Resource nennen -> Roblox hat schlicht keinen
        #    Verfuegungsempfaenger im Schluessel eingetragen. Falls auch keine
        #    Studio-Anmeldung vorliegt, muss der Nutzer im Creator-Dashboard
        #    eine Resource festlegen - sonst weiss Roblox nicht, wem das Asset
        #    gehoeren soll.
        param($Shared, $Introspect = $null)
        $info = $Introspect
        if ($null -eq $info) { $info = Invoke-OpenCloudIntrospect $Shared }
        if ($info.ok -ne $true) { return @{ ok = $false; code = [string]$info.code; error = [string]$info.error; userMessage = [string]$info.userMessage; howToFix = [string]$info.howToFix } }
        $groups = @()
        $users = @()
        try { $groups = @($info.writeGroupIds) } catch {}
        try { $users = @($info.writeUserIds) } catch {}
        $kind = ''
        $id = ''
        # Bevorzuge eine EINZELNE konkrete Ressource - das ist die uebliche
        # Konfiguration und der Schluessel-Ersteller hat sie bewusst gewaehlt.
        if ($groups.Count -eq 1) { $kind = 'group'; $id = [string]$groups[0] }
        elseif ($users.Count -eq 1) { $kind = 'user'; $id = [string]$users[0] }
        elseif ($groups.Count -gt 1) { $kind = 'group'; $id = [string]$groups[0] }
        elseif ($users.Count -gt 1) { $kind = 'user'; $id = [string]$users[0] }
        else {
            # Keine konkrete Ressource gefunden. Pruefen, ob authorizedUserId
            # nutzbar ist (Roblox liefert das als Zahl, eine 0 waere ein
            # ungueltiger Platzhalter, also verwerfen).
            $authRaw = $null
            try { $authRaw = $info.authorizedUserId } catch {}
            $authString = ''
            try { if ($null -ne $authRaw) { $authString = [string]$authRaw } } catch {}
            if (-not [string]::IsNullOrWhiteSpace($authString) -and $authString -ne '0') {
                $kind = 'user'; $id = $authString
            }
        }
        if ([string]::IsNullOrWhiteSpace($id)) {
            return @{
                ok = $false; code = 'OPENCLOUD_CREATOR_MISSING'
                error = 'Roblox nennt im Schluessel keinen Empfaenger fuer die Assets und das Studio-Plugin hat keine angemeldete Nutzer-ID gemeldet.'
                userMessage = 'Die Bridge konnte den Asset-Ersteller noch nicht erkennen. Bitte melde dich in Roblox Studio mit deinem Roblox-Konto an und öffne ein Place, bis unten links in der Bridge dein Profilbild und Anzeigename erscheinen. Danach nutzt die Bridge automatisch genau dieses Konto; du musst keinen Entwicklernamen eintragen. Wenn Roblox den Upload trotzdem mit 403 ablehnt, muss der Open-Cloud-Key das Recht assets:write fuer dieses Studio-Konto haben.'
                howToFix = 'Sage dem Nutzer den Satz aus userMessage WORTLICH auf Deutsch. Falls das Studio-Profil sichtbar ist und Roblox dennoch 403 meldet, muss der API-Key ASSETS write fuer die angezeigte Nutzer-ID erlauben.'
            }
        }
        try {
            if ($null -ne $Shared) {
                $Shared.BridgeSettings.openCloudCreatorId = [string]$id
                $Shared.BridgeSettings.openCloudCreatorKind = [string]$kind
                $Shared.BridgeSettings.openCloudCreatorName = [string]$info.name
            }
        } catch {}
        return @{ ok = $true; creatorKind = [string]$kind; creatorId = [string]$id; name = [string]$info.name; assetRead = [bool]$info.assetRead; assetWrite = [bool]$info.assetWrite }
    }

    function Test-OpenCloudKeyAuth {
        # Version 7.5.2: die Pruefung ist jetzt die ECHTE Selbstauskunft
        # (Introspect) statt eines Stocherns in einer erfundenen Operation.
        # Sie sagt damit nicht nur "Schluessel wird angenommen", sondern auch,
        # was er DARF (Assets lesen/schreiben) - und liefert gleich den
        # Key-Resource mit, die bei fehlender Studio-ID als Upload-Rueckfall dient.
        param($Shared)
        $config = Get-OpenCloudConfig $Shared
        if (-not $config.hasKey) { return @{ ok = $false; code = 'OPENCLOUD_KEY_MISSING'; error = 'Kein Schluessel hinterlegt.' } }
        $info = Invoke-OpenCloudIntrospect $Shared
        if ($info.ok -ne $true) { return $info }
        $creator = Resolve-OpenCloudCreatorFromKey -Shared $Shared -Introspect $info
        $advice = ''
        if (-not [bool]$info.assetRead -or -not [bool]$info.assetWrite) {
            $advice = 'Dem Schluessel fehlt das Recht ASSETS mit LESEN und SCHREIBEN - ohne das lehnt Roblox jeden Upload mit 403 ab.'
        }
        return @{
            ok = $true; code = 'KEY_ACCEPTED'; status = [int]$info.status; accepted = $true; transport = [string]$info.transport
            keyName = [string]$info.name
            authorizedUserId = [string]$info.authorizedUserId
            scopes = $info.scopes
            assetRead = [bool]$info.assetRead
            assetWrite = [bool]$info.assetWrite
            universeWrite = [bool]$info.universeWrite
            universePlaceWrite = [bool]$info.universePlaceWrite
            gamePassRead = [bool]$info.gamePassRead
            gamePassWrite = [bool]$info.gamePassWrite
            developerProductRead = [bool]$info.developerProductRead
            developerProductWrite = [bool]$info.developerProductWrite
            creatorOk = [bool]$creator.ok
            creatorKind = [string]$creator.creatorKind
            creatorId = [string]$creator.creatorId
            advice = $advice
            robloxResponse = [string]$info.robloxResponse
        }
    }
}

# ----------------------------------------------------------------------------
# Alles, was Handler- und Worker-Runspaces brauchen, liegt in $Shared.
# ----------------------------------------------------------------------------
$script:Shared.MeshRoot = [string]$script:MeshRoot
$script:Shared.BlenderFolder = [string]$script:BlenderFolder
$script:Shared.BlenderStatusFile = [string]$script:BlenderStatusFile
$script:Shared.MeshRegistryPath = [string]$script:MeshRegistryFile
$script:Shared.MeshRunnerText = [string]$script:MeshRunnerTemplate
$script:Shared.MeshToolkitText = [string]$script:BridgeMeshToolkit
$script:Shared.MeshJobScriptText = [string]$script:BridgeMeshJobScript
$script:Shared.BlenderToolsText = [string]$script:BridgeBlenderTools
$script:Shared.OpenCloudToolsText = [string]$script:BridgeOpenCloudTools
$script:Shared.OpenCloudKeyFile = [string]$script:OpenCloudKeyFile
$script:Shared.BlenderStepScriptText = [string]$script:BridgeBlenderStepScript
$script:Shared.BlenderProbeScriptText = [string]$script:BridgeBlenderProbeScript
$script:Shared.LocalPort = [int]$script:Port
$script:Shared.LocalBaseUrl = [string]$script:LocalBaseUrl
$script:Shared.MeshRootFolder = [string]$script:AppDataRoot
try {
    if (-not (Test-Path -LiteralPath $script:MeshRoot)) { [void](New-Item -ItemType Directory -Path $script:MeshRoot -Force) }
    if (-not (Test-Path -LiteralPath $script:BlenderFolder)) { [void](New-Item -ItemType Directory -Path $script:BlenderFolder -Force) }
} catch { }

# ----------------------------------------------------------------------------
# Version 7.4.0: MESH-TAKT und MESH-FENSTER
# Der Toolkit-Text liegt in $Shared, damit auch der Handler-Runspace ihn
# benutzen kann. Fuer die Oberflaeche wird er hier EINMAL geladen - so gibt es
# genau eine Quelle fuer Queue-Anmeldung, Registerpflege und Messung.
# ----------------------------------------------------------------------------
try { . ([scriptblock]::Create([string]$script:BridgeMeshToolkit)) } catch { Write-RuntimeLog ('Mesh-Werkzeuge konnten nicht geladen werden: ' + $_.Exception.Message) }
try { . ([scriptblock]::Create([string]$script:BridgeOpenCloudTools)) } catch { Write-RuntimeLog ('Open-Cloud-Werkzeuge konnten nicht geladen werden: ' + $_.Exception.Message) }

function Update-MeshTick {
    # Laeuft im UI-Takt (kein zusaetzlicher Timer). Holt Ergebnisse interner
    # Mesh-Befehle ab, legt nach der Messung die Platzhalter an und pflegt das
    # Register. Kein Netzwerkzugriff, keine Annahmen: steht keine Antwort da,
    # passiert nichts.
    try {
        $map = $script:Shared.MeshInternal
        foreach ($pair in @($map.GetEnumerator())) {
            $key = [string]$pair.Key
            if (-not $key.StartsWith('cmd:')) { continue }
            $commandId = $key.Substring(4)
            $tag = [string]$pair.Value
            $outcome = Get-MeshCommandOutcome $script:Shared $commandId
            $state = [string]$outcome.state
            if ($state -eq 'pending' -or $state -eq 'invalid') { continue }
            $discard = $null
            [void]$map.TryRemove($key, [ref]$discard)
            if ($tag.StartsWith('placeholders:')) {
                $jobId = $tag.Substring(13)
                if ($state -eq 'done') {
                    Update-MeshRegistryFromPlaceholderResult $script:Shared $jobId ([string]$outcome.json)
                } else {
                    # Version 7.5.2: Auch im Fehlerfall wird die Befehls-Id
                    # GERAEUMT (ueber den sicheren Setter). Blieb sie stehen,
                    # sperrte sie den Job dauerhaft; fehlte sie, lief die
                    # Schleife - beides war falsch.
                    $job = Get-MeshJobData $script:Shared $jobId
                    if ($null -ne $job) {
                        Set-MeshJobFieldOnObject $job 'placeholderCommandId' ''
                        Set-MeshJobFieldOnObject $job 'placeholderState' 'failed'
                        Set-MeshJobFieldOnObject $job 'error' ([string]$outcome.message)
                        Save-MeshJobData $script:Shared $job
                        Write-RuntimeLog ('Mesh-Platzhalter-Befehl fehlgeschlagen (Job ' + [string]$jobId + '): ' + [string]$outcome.message + ' - der Job wird NICHT weiter wiederholt (Versuche: ' + [string]$job.placeholderAttempts + '/3).')
                    }
                }
                continue
            }
            if ($tag.StartsWith('apply:')) {
                $jobId = $tag.Substring(6)
                if ($state -eq 'done') {
                    $appliedOk = $false
                    try { $appliedOk = [bool](Update-MeshRegistryFromApplyResult $script:Shared ([string]$outcome.json)) } catch {}
                    if ($appliedOk) {
                        # Version 7.4.1: Dateimuell vermeiden - OBJ + Slot-Skript
                        # loeschen, den Job-Ordner nur, wenn nichts mehr wartet.
                        $cleaned = 0
                        try { $cleaned = [int](Remove-MeshAppliedFileSets $script:Shared $jobId) } catch {}
                        Write-RuntimeLog ('Eingesetzte Mesh-Dateien geloescht (' + [string]$cleaned + ' Slot(s), Job ' + $jobId + ') - der MeshPart traegt jetzt die echte Geometrie.')
                    } else {
                        Write-RuntimeLog ('Mesh-Einsetzen fehlgeschlagen (Job ' + $jobId + ') - der Slot meldet den echten Fehler.')
                    }
                } else {
                    $failedNow = 0
                    foreach ($slot in (Get-MeshSlotsBySession $script:Shared '' $jobId)) {
                        if ([string]$slot.state -ne 'applying') { continue }
                        $pending = ''
                        try { $pending = [string]$slot.pendingCommandId } catch {}
                        if ($pending -eq $commandId -or [string]::IsNullOrWhiteSpace($pending)) {
                            Set-MeshSlotField $script:Shared ([string]$slot.slotKey) 'state' 'apply_failed'
                            Set-MeshSlotField $script:Shared ([string]$slot.slotKey) 'error' ([string]$outcome.message)
                            $failedNow = $failedNow + 1
                        }
                    }
                    if ($failedNow -gt 0) { Write-RuntimeLog ('Mesh-Einsetzen fehlgeschlagen: ' + [string]$outcome.message) }
                    Save-MeshRegistryFile $script:Shared
                }
                continue
            }
            if ($tag.StartsWith('drop:')) {
                $jobId = $tag.Substring(5)
                if ($state -eq 'done') {
                    $droppedOk = $false
                    try { $droppedOk = [bool](Update-MeshRegistryFromDropResult $script:Shared $jobId ([string]$outcome.json)) } catch {}
                    if ($droppedOk) {
                        Write-RuntimeLog ('Mesh-Slot storniert (' + $jobId + '): Platzhalter und Dateien sind entfernt.')
                    } else {
                        Write-RuntimeLog ('Mesh-Slot konnte nicht storniert werden (' + $jobId + ') - der Slot meldet den echten Fehler.')
                    }
                } else {
                    $failedNow = 0
                    foreach ($slot in (Get-MeshSlotsBySession $script:Shared '' $jobId)) {
                        if ([string]$slot.state -ne 'dropping') { continue }
                        $pending = ''
                        try { $pending = [string]$slot.pendingCommandId } catch {}
                        if ($pending -eq $commandId -or [string]::IsNullOrWhiteSpace($pending)) {
                            Set-MeshSlotField $script:Shared ([string]$slot.slotKey) 'state' 'drop_failed'
                            Set-MeshSlotField $script:Shared ([string]$slot.slotKey) 'error' ([string]$outcome.message)
                            $failedNow = $failedNow + 1
                        }
                    }
                    if ($failedNow -gt 0) { Write-RuntimeLog ('Mesh-Slot stornieren fehlgeschlagen: ' + [string]$outcome.message) }
                    Save-MeshRegistryFile $script:Shared
                }
                continue
            }
            Write-RuntimeLog ('Mesh-Befehl ohne Zuordnung beendet: ' + $tag)
        }

        # Nach der Messung: Platzhalter automatisch anlegen lassen.
        #
        # Version 7.5.2 - DIE ENDLOSSCHLEIFE IST ZU. Live-Befund des Owners:
        # weil das Feld placeholderCommandId am aus JSON gelesenen Job nicht
        # gesetzt werden konnte, war die Id nach dem Absenden wieder leer und
        # dieser Block schickte den Befehl im UI-Takt (etwa 2x je Sekunde)
        # erneut - tausende identische MeshParts in Studio. Ab hier gilt:
        #   1. ein laufender Befehl sperrt den Job (placeholderCommandId),
        #   2. hoechstens 3 Versuche je Job (placeholderAttempts), mit
        #      Wartezeit dazwischen - danach ehrlich 'failed' statt Schleife,
        #   3. nach einem erfolgreichen Lauf ist placeholdersCreated gesetzt.
        foreach ($jobPair in @($script:Shared.MeshJobs.GetEnumerator())) {
            $job = Get-MeshJobData $script:Shared ([string]$jobPair.Key)
            if ($null -eq $job) { continue }
            if ([string]$job.state -ne 'measured') { continue }
            if ([bool]$job.placeholdersCreated) { continue }
            if (-not [string]::IsNullOrWhiteSpace([string]$job.placeholderCommandId)) { continue }
            if ([string]$job.sessionId -eq $null -or [string]::IsNullOrWhiteSpace([string]$job.sessionId)) { continue }
            $attempts = 0
            try { $attempts = [int]$job.placeholderAttempts } catch { $attempts = 0 }
            if ($attempts -ge 3) {
                $stateNow = ''
                try { $stateNow = [string]$job.placeholderState } catch {}
                if ($stateNow -ne 'failed') {
                    Set-MeshJobFieldOnObject $job 'placeholderState' 'failed'
                    Set-MeshJobFieldOnObject $job 'error' 'Die Platzhalter konnten nach 3 Versuchen nicht angelegt werden - die Bridge wiederholt es NICHT weiter (kein Part-Regen). Baue den Slot neu (build_mesh_model) oder lege die Platzhalter mit mesh_slots selbst an.'
                    Save-MeshJobData $script:Shared $job
                    Write-RuntimeLog ('Mesh-Platzhalter aufgegeben: Job ' + [string]$job.id + ' nach 3 Versuchen - es werden KEINE weiteren Befehle geschickt.')
                }
                continue
            }
            $requestedAt = 0
            try { $requestedAt = [int64]$job.placeholderRequestedAt } catch { $requestedAt = 0 }
            $nowSeconds = [DateTimeOffset]::UtcNow.ToUnixTimeSeconds()
            if ($requestedAt -gt 0 -and ($nowSeconds - $requestedAt) -lt 20) { continue }
            $open = $false
            $ready = 0
            foreach ($slot in (Get-MeshSlotsBySession $script:Shared ([string]$job.sessionId) ([string]$job.id))) {
                $slotState = [string]$slot.state
                if ($slotState -in @('pending', 'running', 'script', 'measured')) { $open = $true }
                if ($slotState -eq 'obj' -or $slotState -eq 'applied') { $ready = $ready + 1 }
            }
            if ($open -or $ready -eq 0) { continue }
            $sent = Send-MeshPlaceholders $script:Shared ([string]$job.id)
            if (-not [string]::IsNullOrWhiteSpace($sent)) {
                Write-RuntimeLog ('Mesh-Platzhalter beauftragt: Job ' + [string]$job.id + ', ' + [string]$ready + ' Slot(s), commandId=' + $sent)
            }
        }
    } catch {
        try { Write-RuntimeLog ('Mesh-Takt Fehler: ' + $_.Exception.Message) } catch {}
    }
}

# ----------------------------------------------------------------------------
# Tunnel (cloudflared)
# ----------------------------------------------------------------------------
$script:TunnelStreamReaderScript = {
    param($Process, $StreamName, $Queue, $LogFile)
    try {
        $stream = if ($StreamName -eq 'Out') { $Process.StandardOutput } else { $Process.StandardError }
        while ($true) {
            $line = $stream.ReadLine()
            if ($null -eq $line) { break }
            # Alte Reader duerfen nach einem Neustart noch gepufferte Zeilen
            # schreiben. Die Prozess-ID macht sie im UI eindeutig filterbar,
            # damit eine alte Quick-Tunnel-URL keinen neuen Prozess uebermalt.
            $processId = 0
            try { $processId = [int]$Process.Id } catch {}
            $Queue.Enqueue(('[pid=' + [string]$processId + '] ' + $line))
            try {
                Add-Content -LiteralPath $LogFile -Value ('{0:u} cloudflared: {1}' -f (Get-Date), $line) -Encoding UTF8
            } catch {}
        }
    } catch {}
}

# ----------------------------------------------------------------------------
# CLOUDFLARED AUTOMATISCH INSTALLIEREN (Version 3.3)
# Fehlt cloudflared, wird es ohne Nachfrage installiert:
#   Weg 1: Download der neuesten offiziellen Version von GitHub (Cloudflare)
#          nach %LOCALAPPDATA%\ArenaRobloxBridge\bin\cloudflared.exe.
#          Braucht keine Admin-Rechte.
#   Weg 2: Klappt der Download nicht, wird winget versucht (falls vorhanden).
# Der Fortschritt wird in der Datei install.status festgehalten. Die
# Oberflaeche (Refresh-Ui) prueft sie regelmaessig, zeigt den Status an und
# startet den Tunnel automatisch, sobald cloudflared verfuegbar ist.
# ----------------------------------------------------------------------------
function Get-CloudflaredPath {
    # 1) Bereits im PATH?
    $command = Get-Command cloudflared -ErrorAction SilentlyContinue
    if ($command) { return $command.Source }
    # 2) Bereits automatisch heruntergeladen (fruehere Starts)?
    $localCopy = Join-Path $script:BinFolder 'cloudflared.exe'
    if (Test-Path -LiteralPath $localCopy) { return $localCopy }
    # 3) Klassische Installation (z.B. per winget/MSI in Program Files)?
    $installRoots = @(${env:ProgramFiles(x86)}, $env:ProgramFiles) | Where-Object { $_ }
    foreach ($root in $installRoots) {
        $candidate = Join-Path $root 'cloudflared\cloudflared.exe'
        if (Test-Path -LiteralPath $candidate) { return $candidate }
    }
    return $null
}

function Update-ProcessPath {
    # PATH aus der Registry neu einlesen. Installationen von aussen (z.B.
    # winget) aktualisieren den PATH eines bereits laufenden Programms nicht
    # von selbst.
    try {
        $machinePath = [System.Environment]::GetEnvironmentVariable('Path', 'Machine')
        $userPath = [System.Environment]::GetEnvironmentVariable('Path', 'User')
        $pathParts = @($machinePath, $userPath) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) }
        if ($pathParts.Count -gt 0) { $env:Path = ($pathParts -join ';') }
    } catch {}
}

function Start-CloudflaredInstall {
    # Stoesst die vollautomatische Installation an (lauft im Hintergrund
    # weiter, das Fenster bleibt bedienbar). Refresh-Ui ueberwacht den
    # Fortschritt und startet den Tunnel, sobald die Installation fertig ist.
    if ($script:TunnelInstalling) { return }
    $script:TunnelInstalling = $true
    $script:TunnelInstallFailed = $false
    $script:TunnelInstallMessage = ''
    $script:TunnelInstallStartedAt = Get-Date
    try { New-Item -ItemType Directory -Path $script:BinFolder -Force | Out-Null } catch {}

    $targetPath = Join-Path $script:BinFolder 'cloudflared.exe'
    $statusPath = Join-Path $script:BinFolder 'install.status'

    Write-RuntimeLog 'Cloudflared fehlt - automatische Installation wird gestartet (Download von GitHub, Fallback winget).'
    try {
        if ($script:ToastHost) {
            Show-Toast -Message 'Cloudflared fehlt und wird jetzt automatisch installiert. Der Tunnel startet danach von selbst.' -Kind 'Info' -Seconds 8
        } else {
            Add-PendingToast 'Cloudflared fehlt und wird jetzt automatisch installiert. Der Tunnel startet danach von selbst.' 'Info' 8
        }
    } catch {}

    $installerScript = {
        param([string]$TargetPath, [string]$StatusPath)
        function Write-InstallStatus([string]$Text) {
            try { Set-Content -LiteralPath $StatusPath -Value $Text -Encoding UTF8 } catch {}
        }
        try {
            try { [System.Net.ServicePointManager]::SecurityProtocol = [System.Net.SecurityProtocolType]::Tls12 } catch {}
            $oldProgress = $ProgressPreference
            $ProgressPreference = 'SilentlyContinue'
            $tempPath = "$TargetPath.download"
            if (Test-Path -LiteralPath $tempPath) { Remove-Item -LiteralPath $tempPath -Force }
            Write-InstallStatus 'downloading'
            Invoke-WebRequest -Uri 'https://github.com/cloudflare/cloudflared/releases/latest/download/cloudflared-windows-amd64.exe' -OutFile $tempPath -UseBasicParsing -TimeoutSec 600
            $downloaded = Get-Item -LiteralPath $tempPath
            $head = [byte[]]::new(2)
            $stream = [System.IO.File]::OpenRead($tempPath)
            try { [void]$stream.Read($head, 0, 2) } finally { $stream.Dispose() }
            if ($head[0] -ne 0x4D -or $head[1] -ne 0x5A -or $downloaded.Length -lt 5242880) {
                throw ("Heruntergeladene Datei ist keine gueltige cloudflared.exe ($($downloaded.Length) Bytes).")
            }
            if (Test-Path -LiteralPath $TargetPath) { Remove-Item -LiteralPath $TargetPath -Force }
            Move-Item -LiteralPath $tempPath -Destination $TargetPath -Force
            Write-InstallStatus 'ok'
        } catch {
            $downloadError = $_.Exception.Message
            # Fallback: winget, falls vorhanden
            $wingetCommand = Get-Command winget -ErrorAction SilentlyContinue
            if ($wingetCommand) {
                try {
                    Write-InstallStatus 'winget'
                    $wingetOutput = & $wingetCommand.Source install --id Cloudflare.cloudflared -e --silent --disable-interactivity --accept-source-agreements --accept-package-agreements 2>&1
                    if ($LASTEXITCODE -eq 0) {
                        Write-InstallStatus 'ok'
                    } else {
                        Write-InstallStatus ('error: winget: ' + (($wingetOutput | Out-String).Trim()) + ' / Download: ' + $downloadError)
                    }
                } catch {
                    Write-InstallStatus ('error: winget: ' + $_.Exception.Message + ' / Download: ' + $downloadError)
                }
            } else {
                Write-InstallStatus ('error: ' + $downloadError)
            }
        }
    }

    $installer = [PowerShell]::Create()
    [void]$installer.AddScript($installerScript).AddArgument($targetPath).AddArgument($statusPath)
    [void]$installer.BeginInvoke()
    $script:TunnelInstaller = $installer
}

function Start-CloudflareTunnel {
    param([string]$Protocol = 'auto')
    try {
        # Version 7.4.0: Schritt 4 hat Vorrang. Solange Blender geprueft oder
        # installiert wird, startet kein Tunnel - auch nicht aus der
        # Selbstheilung im UI-Takt heraus.
        if ($script:BlenderGatePending) {
            Write-RuntimeLog 'Der Tunnel wartet noch auf den Blender-Schritt 4.'
            return
        }
        $cloudflaredPath = Get-CloudflaredPath
        if (-not $cloudflaredPath) {
            # Nicht installiert: komplett automatische Installation anstossen.
            # Der Tunnel startet sich selbst, sobald der Download fertig ist
            # (siehe Refresh-Ui / Start-CloudflaredInstall).
            Start-CloudflaredInstall
            return
        }

        # Kein zweiter Prozess fuer dieselbe Bridge: sonst koennte eine alte
        # Quick-Tunnel-URL weiter im UI stehen, obwohl ein anderer Prozess die
        # neue Verbindung verwaltet.
        $alreadyRunning = $false
        try { $alreadyRunning = ($null -ne $script:TunnelProcess -and -not [bool]$script:TunnelProcess.HasExited) } catch {}
        if ($alreadyRunning) {
            Write-RuntimeLog 'Cloudflare-Tunnel ist bereits aktiv; kein zweiter Prozess wird gestartet.'
            return
        }

        $effectiveProtocol = if ([string]::IsNullOrWhiteSpace($Protocol)) { 'auto' } else { [string]$Protocol }
        $arguments = "tunnel --url $script:LocalBaseUrl --no-autoupdate"
        if ($effectiveProtocol -ne 'auto') { $arguments = "$arguments --protocol $effectiveProtocol" }

        $psi = [System.Diagnostics.ProcessStartInfo]::new()
        $psi.FileName = $cloudflaredPath
        $psi.Arguments = $arguments
        $psi.UseShellExecute = $false
        $psi.CreateNoWindow = $true
        $psi.RedirectStandardOutput = $true
        $psi.RedirectStandardError = $true
        $psi.StandardOutputEncoding = [System.Text.Encoding]::UTF8
        $psi.StandardErrorEncoding = [System.Text.Encoding]::UTF8
        $process = [System.Diagnostics.Process]::new()
        $process.StartInfo = $psi
        [void]$process.Start()

        foreach ($streamName in @('Out', 'Err')) {
            $reader = [PowerShell]::Create()
            [void]$reader.AddScript([string]$script:TunnelStreamReaderScript).AddArgument($process).AddArgument($streamName).AddArgument($script:TunnelLines).AddArgument($script:RuntimeLog)
            [void]$reader.BeginInvoke()
            $script:TunnelReaders += $reader
        }
        $script:TunnelProcess = $process
        $script:TunnelUrl = $null
        $script:TunnelLiveSince = [DateTime]::MinValue
        $script:TunnelProtocol = $effectiveProtocol
        $script:TunnelStartedAt = Get-Date
        $script:TunnelHttp2Tried = ($effectiveProtocol -eq 'http2')
        $script:TunnelSlowNotified = $false
        $script:TunnelFailed = $false
        Write-RuntimeLog "Cloudflare-Tunnel-Prozess gestartet (PID $($process.Id), Datei: $cloudflaredPath, Argumente: $arguments)."
    } catch {
        $script:TunnelFailed = $true
        $script:LastTunnelMessage = "Cloudflare-Tunnel-Fehler: $($_.Exception.Message)"
        Write-RuntimeLog $script:LastTunnelMessage
    }
}

function Restart-CloudflareTunnel {
    param([string]$Protocol = 'auto')
    try {
        if ($script:TunnelProcess -and -not $script:TunnelProcess.HasExited) {
            $script:TunnelProcess.Kill()
            Start-Sleep -Milliseconds 600
        }
    } catch {}
    $script:TunnelUrl = $null
    Start-CloudflareTunnel -Protocol $Protocol
}

function Remove-BridgeStartupEntries {
    # Raeumt nur Bridge-Eintraege des aktuellen Benutzers weg - keine anderen
    # Programme und keine systemweiten (HKLM) Startprogramme.
    foreach ($item in (Get-BridgeStartupItems)) {
        try {
            if ([string]$item.kind -eq 'registry') {
                Remove-ItemProperty -Path ([string]$item.key) -Name ([string]$item.name) -Force -ErrorAction SilentlyContinue
            } elseif ([string]$item.kind -eq 'file' -and -not [string]::IsNullOrWhiteSpace([string]$item.path)) {
                Remove-Item -LiteralPath ([string]$item.path) -Force -ErrorAction SilentlyContinue
            }
        } catch {}
    }
    # Ein alter Task-Manager-Schalter kann einen neuen Run-Eintrag sonst weiter
    # als deaktiviert markieren. Ohne diesen Marker ist der eine neue Eintrag an.
    foreach ($approvedPath in $script:BridgeStartupApprovedPaths) {
        try {
            $approved = Get-ItemProperty -Path $approvedPath -ErrorAction Stop
            foreach ($property in $approved.PSObject.Properties) {
                $name = [string]$property.Name
                if ($name -match '^PS[A-Z]') { continue }
                if ($name -match '(?i)Arena(?:[\s._-]*Roblox)?[\s._-]*Bridge') {
                    Remove-ItemProperty -Path $approvedPath -Name $name -Force -ErrorAction SilentlyContinue
                }
            }
        } catch {}
    }
}

function Set-StartupEnabled {
    param([bool]$Enabled, [string]$UpdaterPath = '')
    $runKey = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Run'
    if ($Enabled) {
        $updater = Resolve-BridgeUpdaterExePath -PreferredPath $UpdaterPath
        if ([string]::IsNullOrWhiteSpace([string]$updater)) {
            throw 'ArenaBridge.exe (der Starter/Updater) wurde nicht gefunden. Es wird absichtlich kein PowerShell-Autostart eingerichtet. Starte zuerst die ArenaBridge.exe und aktiviere den Schalter danach erneut.'
        }
        # Alte Powershell-/Skript- und Mehrfach-Eintraege entfernen, bevor die
        # eine kanonische Registrierung geschrieben wird.
        Remove-BridgeStartupEntries
        New-Item -Path $runKey -Force | Out-Null
        Set-ItemProperty -Path $runKey -Name 'ArenaRobloxBridge' -Value ('"' + [string]$updater + '"')
        $script:UpdaterExePath = [string]$updater
        [void](Save-BridgeUpdaterExePath $script:UpdaterExePath)
        Write-RuntimeLog ('Autostart aktiviert: nur ArenaBridge.exe/Updater wird gestartet (' + [string]$updater + '); alte Bridge-Startvarianten wurden bereinigt.')
        return $true
    }
    Remove-BridgeStartupEntries
    Write-RuntimeLog 'Autostart deaktiviert: Bridge-Run-/RunOnce-Eintraege und Benutzer-Startup-Verknuepfungen entfernt.'
    return $true
}

function Get-StartupEnabled {
    $items = Get-BridgeStartupItems
    if ($items.Count -le 0) { return $false }
    $updater = Resolve-BridgeUpdaterExePath -PreferredPath ([string]$script:UpdaterExePath)
    if (-not [string]::IsNullOrWhiteSpace([string]$updater)) {
        try {
            [void](Set-StartupEnabled -Enabled $true -UpdaterPath $updater)
            return $true
        } catch {
            try { Write-RuntimeLog ('Autostart konnte nicht auf den Updater umgestellt werden: ' + $_.Exception.Message) } catch {}
        }
    }
    # Ein verwaister PowerShell-Eintrag ist genau das unerwuenschte Verhalten:
    # nicht weiter starten lassen, wenn kein echter Updater-Pfad existiert.
    try {
        Remove-BridgeStartupEntries
        Write-RuntimeLog 'Autostart deaktiviert: alter Bridge-Eintrag entfernt, aber ArenaBridge.exe/Updater wurde nicht gefunden. Bitte den Updater einmal starten und Autostart erneut einschalten.'
    } catch {}
    return $false
}

# Alte Installationen werden beim naechsten Bridge-Start still auf genau einen
# Updater-Eintrag migriert, statt erst beim naechsten PC-Neustart aufzufallen.
try { [void](Get-StartupEnabled) } catch {
    try { Write-RuntimeLog ('Autostart-Pruefung fehlgeschlagen: ' + $_.Exception.Message) } catch {}
}

# ----------------------------------------------------------------------------
# SITZUNGEN (ein Studio-Fenster = eine Sitzung = ein Token)
# ----------------------------------------------------------------------------
# Version 5.2: verstorbene Sitzung restlos entsorgen (Token UND jeglicher
# Nebenzustand). Frueher blieb fast alles davon bis zum Programmende liegen.
function Remove-DeadSession {
    param([string]$SessionId)
    if ([string]::IsNullOrWhiteSpace($SessionId)) { return }
    $placeName = ''
    try {
        $rawEntry = $null
        if ($script:Shared.Sessions.TryGetValue($SessionId, [ref]$rawEntry)) { $placeName = [string](($rawEntry | ConvertFrom-Json).placeName) }
    } catch {}
    $removedJson = $null
    [void]$script:Shared.Sessions.TryRemove($SessionId, [ref]$removedJson)
    $token = $null
    if ($script:Shared.SessionTokens.TryRemove($SessionId, [ref]$token)) {
        $removedSession = $null
        [void]$script:Shared.TokenSessions.TryRemove($token, [ref]$removedSession)
    }
    $junk = $null
    $junkInt = [int]0
    $junkLong = [long]0
    $junkBool = $false
    foreach ($bagName in @('AccessModes','PendingCommands','LateResults','PlayRetryDedupe','AiPlayIntents','LastPlayEvents','RunOwners','AgentKeys','AgentQueues','AgentResults','AgentStates','CommandQueues','CommandSignals','ActivityLogs','ActivityCommandMap','ExecutorStates')) {
        try { [void]$script:Shared.$bagName.TryRemove($SessionId, [ref]$junk) } catch {}
    }
    try { [void]$script:Shared.Pollers.TryRemove($SessionId, [ref]$junkInt) } catch {}
    # Version 7.1.2: Toolbox-Drossel und Import-Sperre duerfen eine beendete
    # Sitzung NIE ueberleben - sonst bliebe der Place dauerhaft "beschaeftigt".
    try { [void]$script:Shared.ToolboxSlots.TryRemove($SessionId, [ref]$junkInt) } catch {}
    try { $junkString = ''; [void]$script:Shared.ToolboxImportLocks.TryRemove($SessionId, [ref]$junkString) } catch {}
    foreach ($longBag in @('Presence','UserActiveAt','AgentLastSeen','ExecutorResetRequests')) {
        try { [void]$script:Shared.$longBag.TryRemove($SessionId, [ref]$junkLong) } catch {}
    }
    try { [void]$script:Shared.DocsSent.TryRemove($SessionId, [ref]$junkBool) } catch {}
    # Command-level records use commandId keys, so remove them through the
    # explicit owner map rather than leaving result/signalling state behind.
    try {
        foreach ($ownerPair in @($script:Shared.CommandOwners.GetEnumerator())) {
            if ([string]$ownerPair.Value -ne $SessionId) { continue }
            $commandId = [string]$ownerPair.Key
            [void]$script:Shared.CommandOwners.TryRemove($commandId, [ref]$junk)
            [void]$script:Shared.CommandStates.TryRemove($commandId, [ref]$junk)
            [void]$script:Shared.CommandPayloads.TryRemove($commandId, [ref]$junk)
            [void]$script:Shared.CommandResults.TryRemove($commandId, [ref]$junk)
            [void]$script:Shared.ResultChunks.TryRemove($commandId, [ref]$junk)
            [void]$script:Shared.ResultChunkAt.TryRemove($commandId, [ref]$junkLong)
            $signal = $null
            if ($script:Shared.ResultSignals.TryRemove($commandId, [ref]$signal)) { try { $signal.Dispose() } catch {} }
        }
        $prefix = $SessionId + ':'
        foreach ($key in @($script:Shared.CancelRequests.Keys)) {
            if ([string]$key -like ($prefix + '*')) { [void]$script:Shared.CancelRequests.TryRemove([string]$key, [ref]$junkLong) }
        }
        foreach ($key in @($script:Shared.CompletedCommandIds.Keys)) {
            if ([string]$key -like ($prefix + '*')) { [void]$script:Shared.CompletedCommandIds.TryRemove([string]$key, [ref]$junkLong) }
        }
    } catch {}
    # Version 7.0.3: Auch die Diagnose-Eintraege dieser Sitzung entfernen,
    # damit wiederholtes Verbinden/Trennen nichts ansammelt.
    try {
        if ($null -ne $script:Shared.Perf) {
            foreach ($perfKey in @('PollRate:' + $SessionId, 'Plugin:' + $SessionId, 'PluginAt:' + $SessionId)) {
                [void]$script:Shared.Perf.Remove($perfKey)
            }
        }
    } catch {}
    try { $script:PlaceNames.Remove($SessionId) } catch {}
    try { $script:PlaceNameResolveErrorLogged.Remove($SessionId) } catch {}
    try {
        foreach ($failureKey in @($script:PlaceRowFailureLogAt.Keys)) {
            if ([string]$failureKey -like ($SessionId + '|*')) { [void]$script:PlaceRowFailureLogAt.Remove([string]$failureKey) }
        }
    } catch {}
    try { $script:PlaceNameSources.Remove($SessionId) } catch {}
    try {
        # Fenster-Besitz freigeben, damit ein neu geoeffnetes Studio-Fenster
        # den Handle uebernehmen kann (und keine Geister-Bindung bleibt).
        $identity = $null
        if ($script:PlaceIdentities.ContainsKey($SessionId)) { $identity = $script:PlaceIdentities[$SessionId] }
        if ($null -ne $identity) {
            foreach ($key in @($script:PreviewHandleClaims.Keys)) {
                if ([string]$script:PreviewHandleClaims[$key] -eq $SessionId) { [void]$script:PreviewHandleClaims.Remove($key) }
            }
        }
        [void]$script:PlaceIdentities.Remove($SessionId)
    } catch {}
    # Vorschau-Worker und Caches gehoeren zur Sitzung und duerfen nach dem
    # Schliessen eines Studio-Fensters weder weiterlaufen noch Handles halten.
    try {
        if ($script:PlacePreviewJobs.ContainsKey($SessionId)) {
            $previewJob = $script:PlacePreviewJobs[$SessionId]
            # Nur der PS-Fallback-Worker laesst sich stoppen; ein C#-Task-Job
            # wird schlicht fallengelassen (nichts blockiert den UI-Thread).
            if ($previewJob.Worker) {
                try { $previewJob.Worker.Stop() } catch {}
                try { $previewJob.Worker.Dispose() } catch {}
            }
            [void]$script:PlacePreviewJobs.Remove($SessionId)
        }
        [void]$script:PlacePreviewHandles.Remove($SessionId)
        try { [void]$script:PreviewHandleInfos.Remove($SessionId) } catch {}
        [void]$script:PlacePreviewLastCaptureAt.Remove($SessionId)
        [void]$script:PlacePreviewFailLogAt.Remove($SessionId)
    } catch {}
    Write-RuntimeLog ('Place-Sitzung ' + $SessionId + ' ("' + $placeName + '") nach ' + $script:PlaceCleanupSeconds + ' s ohne Lebenszeichen entfernt.')
}
function Get-ActiveStudios {
    $now = [DateTimeOffset]::UtcNow.ToUnixTimeSeconds()
    $items = New-Object System.Collections.Generic.List[object]
    foreach ($pair in $script:Shared.Sessions.GetEnumerator()) {
        try {
            $item = $pair.Value | ConvertFrom-Json
            $sessionId = [string]$item.sessionId
            # Version 5.2: Lebenszeichen PRIMAER aus Presence - Presence setzt
            # ausschliesslich das Edit-Plugin (Heartbeat/Long-Poll). Frueher
            # wurde das Maximum aus lastSeen UND Presence genommen; ein
            # verklemmter Session-Reporter (Agent-Heartbeat) frischt aber NUR
            # lastSeen weiter und hielt tote Places fuer immer sichtbar
            # ("Geister-Place"). Jetzt: nach spaetestens ~15 s ist er weg.
            $aliveAt = [int64]0
            $presenceKnown = $false
            if ($script:Shared.Presence.TryGetValue($sessionId, [ref]$aliveAt)) {
                $presenceKnown = $true
            } else {
                $aliveAt = [int64]$item.lastSeen
            }
            $age = $now - [int64]$aliveAt
            $limit = $script:PlaceVisibleSeconds
            # Sauber abgemeldete Fenster: kurze Gnadenfrist (Plugin-Neuladen),
            # danach sofort raus aus der Liste.
            if ($item.orphan -eq $true -and -not $presenceKnown) { $limit = $script:PlaceOrphanGraceSeconds }
            if ($age -lt $limit) {
                # Sicherheitsnetz gegen kaputte Umlaute in der Anzeige
                $item.placeName = Repair-Mojibake ([string]$item.placeName)
                $items.Add($item)
            } elseif ($age -gt $script:PlaceCleanupSeconds) {
                # Version 5.2: restlos aufraeumen (Token + jeglicher Nebenzustand).
                Remove-DeadSession $sessionId
            }
        } catch {}
    }
    # ------------------------------------------------------------------
    # 4.0.1 DEDUPLIZIERUNG (Live-Befund: waehrend eines Playtests erschienen
    # "Place1" UND "Game"). Ein physischer Studio-Platz darf genau EINE
    # sichtbare Zeile haben. Zwei wirklich getrennt geoeffnete Fenster
    # bleiben getrennt, weil sie unterschiedliche instanceGuids haben und
    # beide dauerhaft heartbeaten.
    #
    # Zusammengefasst wird nur, was nachweislich dieselbe physische
    # Verbindung ist:
    #   a) gleiche instanceGuid (identisches Plugin), oder
    #   b) eine Test-/Play-Session desselben Place, die parallel zu einer
    #      Edit-Sitzung desselben Place laeuft (Studio klont das Place fuer
    #      den Test und nennt es dann haeufig "Game").
    # Sichtbar bleibt die aeltere, echte Sitzung (connectedAt).
    # ------------------------------------------------------------------
    $deduped = New-Object System.Collections.Generic.List[object]
    foreach ($item in $items) {
        $hide = $false
        foreach ($other in $items) {
            if ([string]$other.sessionId -eq [string]$item.sessionId) { continue }
            # Nur die AELTERE Sitzung darf eine juengere verdecken.
            if ([int64]$other.connectedAt -ge [int64]$item.connectedAt) { continue }
            # Version 7.0.0: NUR dieselbe Plugin-Instanz darf sich selbst
            # verdecken. Der alte Zweig "gleiche placeId + laeuft" hat zwei
            # FENSTER mit placeId=0 (zwei lokale Places) zu EINER Zeile
            # verschmolzen, sobald eines davon einen Test laufen liess.
            $sameGuid = ((-not [string]::IsNullOrWhiteSpace([string]$item.instanceGuid)) -and
                         ([string]$other.instanceGuid -eq [string]$item.instanceGuid))
            if ($sameGuid) { $hide = $true; break }
        }
        if (-not $hide) { $deduped.Add($item) }
    }

    $deduped | Sort-Object placeName, sessionId
}

function Reset-SessionToken {
    param([string]$SessionId)
    if ($SessionId -eq '__arena_all_places__') {
        # Version 5: only an explicit click changes the aggregate token.
        $script:AllPlacesToken = New-Token
        $script:Shared.MultiPlaceToken = $script:AllPlacesToken
        Write-RuntimeLog 'Token für Alle Places wurde manuell zurückgesetzt.'
        Show-CopyConfirm -Message 'Token für alle Places wurde zurückgesetzt.' -Seconds 4
        return
    }
    $old = $null
    if ($script:Shared.SessionTokens.TryRemove($SessionId, [ref]$old)) {
        $removed = $null
        [void]$script:Shared.TokenSessions.TryRemove($old, [ref]$removed)
    }
    $new = New-Token
    $script:Shared.SessionTokens[$SessionId] = $new
    $script:Shared.TokenSessions[$new] = $SessionId
    Write-RuntimeLog "Token fuer Sitzung $SessionId neu vergeben."
    Show-CopyConfirm -Message 'Token wurde zurückgesetzt.' -Seconds 4
}

function Set-SessionMode {
    param([string]$SessionId, [string]$Mode)
    # Version 5: intentionally runtime-only. A newly registered Place must
    # always start with full access, therefore nothing is written to settings.json.
    if ($SessionId -eq '__arena_all_places__') { Set-AllSessionsMode $Mode; return }
    $script:Shared.AccessModes[$SessionId] = $Mode
}

function Set-AllSessionsMode {
    param([string]$Mode)
    # The aggregate switch affects only the Places connected right now. A Place
    # that connects later always receives its registration default (read/write).
    $now = [DateTimeOffset]::UtcNow.ToUnixTimeSeconds()
    foreach ($pair in $script:Shared.Sessions.GetEnumerator()) {
        try {
            $entry = $pair.Value | ConvertFrom-Json
            # Version 5.2: nur wirklich lebende Fenster umschalten (Presence).
            $aliveAt = [int64]0
            if (-not $script:Shared.Presence.TryGetValue([string]$pair.Key, [ref]$aliveAt)) { $aliveAt = [int64]$entry.lastSeen }
            if ($entry -and ($now - $aliveAt) -lt 30 -and $entry.orphan -ne $true) {
                $script:Shared.AccessModes[[string]$pair.Key] = $Mode
            }
        } catch {}
    }
}

# ----------------------------------------------------------------------------
# HILFSFUNKTIONEN FUER DIE OBERFLAECHE
# ----------------------------------------------------------------------------
$script:BrushCache = @{}
function Get-Brush {
    param([string]$Hex)
    $key = $Hex.ToUpperInvariant()
    if (-not $script:BrushCache.ContainsKey($key)) {
        $color = [System.Windows.Media.ColorConverter]::ConvertFromString($Hex)
        $brush = [System.Windows.Media.SolidColorBrush]::new($color)
        $brush.Freeze()
        $script:BrushCache[$key] = $brush
    }
    return $script:BrushCache[$key]
}

function New-Shadow {
    param([double]$Blur = 20, [double]$Opacity = 0.5, [string]$Color = '#000000')
    $shadow = [System.Windows.Media.Effects.DropShadowEffect]::new()
    $shadow.Color = [System.Windows.Media.ColorConverter]::ConvertFromString($Color)
    $shadow.BlurRadius = $Blur
    $shadow.ShadowDepth = 0
    $shadow.Opacity = $Opacity
    $shadow.Direction = 270
    return $shadow
}

function New-CheckPath {
    param([string]$Color = '#FFFFFF')
    $path = [System.Windows.Shapes.Path]::new()
    $path.Data = [System.Windows.Media.Geometry]::Parse('M 4,10.4 L 8,14.4 L 16,5.2')
    $path.Stroke = Get-Brush $Color
    $path.StrokeThickness = 2.2
    $path.StrokeStartLineCap = 'Round'
    $path.StrokeEndLineCap = 'Round'
    $path.HorizontalAlignment = 'Center'
    $path.VerticalAlignment = 'Center'
    return $path
}

function Set-Text {
    param($Element, [string]$Value)
    if ($null -eq $Element) { return }
    if ([string]$Element.Text -ne $Value) { $Element.Text = $Value }
}

function Set-Dot {
    param($Element, [string]$Hex)
    if ($null -eq $Element) { return }
    if ([string]$Element.Tag -ne $Hex) {
        $Element.Tag = $Hex
        $Element.Fill = Get-Brush $Hex
    }
}

